window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0152", [{"word":"social integration","ipa_uk":"/ˌsəʊʃəl ˌɪntɪˈɡreɪʃən/","ipa_us":"/ˌsoʊʃəl ˌɪntɪˈɡreɪʃən/","definition_zh":"社会融合；社会整合：不同群体、个体与制度在日常往来中被纳入同一个社会整体，并形成稳定联系的过程与状态","definition_en":"the process or state in which different groups, individuals and institutions are brought into one society and held together by stable everyday ties","core_image":"一条老街区的新旧住户在同一张长桌上分食，孩子在桌下交换玩具，界线在日常往来里一点点消失","scene":"社区中心把新迁来的家庭与老住户请到同一张长桌，孩子先在桌下交换玩具，大人们随后谈起共同的学校问题。Social integration grows through small daily contacts rather than through a single official ceremony.","sceneCN":"这里指不同群体在日常往来中被纳入同一社会整体的过程（第 1 个义项：群体层面的社会融合）；句意为社会融合靠日常的小接触累积，而不是靠一场官方仪式。","pos":[{"tag":"n.","zh":"社会融合（不可数，指群体被纳入整体的过程）"},{"tag":"n.","zh":"社会整合（社会学用语，指社会各部分被联结的状态）"}],"collocations":[{"phrase":"promote social integration","zh":"促进社会融合"},{"phrase":"social integration of migrants","zh":"移民的社会融合"},{"phrase":"social integration policy","zh":"社会融合政策"},{"phrase":"a sense of social integration","zh":"社会融入感"},{"phrase":"barriers to social integration","zh":"社会融合的障碍"},{"phrase":"measure social integration","zh":"测量社会融合程度"}],"forms":[{"label":"原形（名词短语，不可数）","form":"social integration"},{"label":"连字符定语形式","form":"social-integration"},{"label":"形容词性短语（已融入社会的）","form":"socially integrated"},{"label":"动词短语（使融入社会）","form":"socially integrate"},{"label":"核心名词的名词化形式","form":"integration"}],"derivatives":[{"word":"integration","pos":"n.","zh":"integrate + -ion（动作或结果）→ 整合这一过程或其结果"},{"word":"integrative","pos":"adj.","zh":"integrate + -ive（具有……性质的）→ 具有整合作用的"},{"word":"integrationist","pos":"n./adj.","zh":"integration + -ist（主张者）→ 主张社会融合的人或立场"},{"word":"disintegrate","pos":"v.","zh":"dis-（相反） + integrate → 由「使完整」反转为「使解体」"},{"word":"reintegrate","pos":"v.","zh":"re-（重新） + integrate → 重新纳入整体，语义偏移为「回归社会」"},{"word":"socially","pos":"adv.","zh":"social + -ly（方式副词）→ 以社会交往的方式"}],"senses":[{"no":"01","title":"Groups drawn into everyday contact","titleCN":"不同群体在日常往来中被纳入同一整体","definition":"the process by which newcomers and established residents come to share ordinary daily contacts, schools and workplaces","definitionCN":"新来者与原住户逐渐共享日常接触、学校与工作场所的过程","example":"Evening language classes became the cheapest route to social integration.","exampleCN":"夜间语言课成了社会融合最省钱的途径。","why":"the phrase joins social, from Latin socius 'companion', with integration, from integrare 'to make whole', so it literally names the making of companions out of strangers.","whyCN":"短语由表示「同伴」的 social 与表示「使完整」的 integration 组成，字面上说的就是把陌生人变成同伴。"},{"no":"02","title":"The sociological concept of cohesion","titleCN":"社会学意义上的社会凝聚力","definition":"the degree to which members of a society feel bound by shared norms and collective life, as treated in classical sociology","definitionCN":"社会成员受共同规范与集体生活约束的程度，是古典社会学的研究对象","example":"Durkheim treated social integration as a buffer against anomic suicide.","exampleCN":"涂尔干把社会整合视为抵御失范性自杀的缓冲。","why":"sociology took the everyday phrase and gave it a collective, measurable reading: how tightly are members held together?","whyCN":"社会学把这个日常短语收为集体的、可测量的概念，追问成员被联结得有多紧。"},{"no":"03","title":"Coordination among institutions","titleCN":"机构之间的协调与整合","definition":"the fitting together of separate institutions, such as schools, health services and labour offices, into one working system","definitionCN":"把学校、卫生服务、劳动部门等分立机构装进一个运转系统","example":"Social integration of the health and housing services cut waiting time for new arrivals.","exampleCN":"卫生与住房服务的整合缩短了新来者的等待时间。","why":"integration also names the fitting of parts into a whole, so the phrase extends from people to the institutions that serve them.","whyCN":"integration 也指把各部分装进整体，于是短语从人延伸到服务于人的机构。"},{"no":"04","title":"Inclusion of pupils in mainstream schools","titleCN":"学生被纳入普通学校与普通班级","definition":"the placement and participation of pupils with disabilities or minority backgrounds in ordinary classrooms","definitionCN":"让残障或少数群体背景的学生进入普通课堂并真正参与","example":"The district measured social integration by how often pupils with aides joined group work.","exampleCN":"该学区用有陪读的学生参加小组活动的频率来衡量社会融合。","why":"school is the first place where a society's parts meet daily, so the phrase naturally names classroom inclusion.","whyCN":"学校是社会各部分每天相遇的第一现场，因此短语自然用来指课堂接纳。"},{"no":"05","title":"Entry into the labour market","titleCN":"进入劳动力市场并获得工作网络","definition":"the movement of migrants or excluded groups into paid work, training and the networks that form at work","definitionCN":"移民或被排斥群体进入有薪工作、培训以及工作中形成的关系网络","example":"Apprenticeships did more for social integration than leaflets about equality.","exampleCN":"学徒制对社会融合的作用，比平等主题的宣传单更大。","why":"a job puts people into repeated contact under shared rules, which is exactly the mechanism the phrase describes.","whyCN":"工作把人放进共享规则下的反复接触，这正是短语所描述的机制。"},{"no":"06","title":"Shared urban space and mixed neighbourhoods","titleCN":"共享城市空间与混合居住的街区","definition":"the condition in which different income and ethnic groups use the same streets, parks and public services","definitionCN":"不同收入与族裔群体使用同样的街道、公园与公共服务","example":"Planners argued that mixed housing would promote social integration more than a new community centre.","exampleCN":"规划者认为混合住房比新建社区中心更能促进社会融合。","why":"integration needs a physical surface, and shared space is where strangers become familiar.","whyCN":"融合需要一个物理表面，共享空间正是陌生人变得熟悉的地方。"},{"no":"07","title":"Participation in online communities","titleCN":"在线上社群中获得参与与承认","definition":"the process by which isolated or new users become recognised participants in an online group","definitionCN":"孤立或新来的用户成为线上群体中被承认的参与者","example":"Moderators used welcome threads to support social integration of shy newcomers.","exampleCN":"版主用欢迎帖帮助羞怯的新成员融入社群。","why":"contact, recognition and shared rules reappear wherever a group meets, including on a screen.","whyCN":"接触、被承认与共享规则的同一模式会出现在任何群体相遇之处，屏幕上也不例外。"},{"no":"08","title":"A measured level of union","titleCN":"可测量的融合程度","definition":"a quantified degree to which groups are linked, used as a variable in surveys and policy evaluation","definitionCN":"群体被联结的程度被量化为指标，用于调查与政策评估","example":"The survey scored social integration from zero to ten and compared regions.","exampleCN":"该调查用零到十分给社会融合打分，并比较各地区。","why":"once the process is understood it can be scored, and the phrase then names the score rather than the process.","whyCN":"过程一旦被理解就可以打分，短语于是指那个分数，而不是过程本身。"}],"etymology":{"intro":{"en":"The phrase joins two Latin-derived nouns. Social goes back to Latin socius 'companion, ally'; integration goes back to integer 'whole, untouched' and integrare 'to make whole'. The phrase itself is a modern sociological formation. Dates are approximate.","cn":"这个短语由两个拉丁来源的名词组成。social 追溯至拉丁 socius「同伴、同盟」；integration 追溯至 integer「完整、未受触动」与 integrare「使完整」。短语本身是近代社会学的构造。年代为约数。"},"items":[{"era":"LATIN SOCIUS","en":"Socius meant 'companion, ally, associate'. Standard references connect it with sequi 'to follow', so a companion is one who follows or accompanies; socialis in Late Latin meant 'of companions, of alliance'.","cn":"socius 意为「同伴、同盟、伙伴」。通行词源资料把它与 sequi「跟随」联系起来，同伴即同行之人；晚期拉丁 socialis 意为「同伴的、结盟的」。"},{"era":"LATIN INTEGER","en":"Integer 'whole, complete, untouched' is built from in- 'not' and the root tag- 'to touch' seen in tangere. The same root gives intact and contact.","cn":"integer「完整、未受触动」由 in-「不」与 tangere 中可见的 tag-「触碰」词根构成。同一词根还给出 intact 与 contact。"},{"era":"LATIN INTEGRARE","en":"Integrare meant 'to make whole, to renew, to restore'. Its noun integratio named a renewal or a restoring of a whole, first in religious and later in general prose.","cn":"integrare 意为「使完整、更新、恢复」。其名词 integratio 指更新或使整体复原，先用于宗教文字，后进入一般散文。"},{"era":"FRENCH AND ENGLISH","en":"Social entered English through Old French social, and integration through French integration in the eighteenth century, both keeping the Latin sense of joining or making whole.","cn":"social 经古法语进入英语，integration 在 18 世纪经法语 integration 进入，两者都保留拉丁语「联结、使完整」的意思。"},{"era":"SOCIOLOGICAL USE","en":"From the late nineteenth century the two words were combined in sociology, above all in Durkheim's work, to name the binding of individuals and groups into a collective life.","cn":"从 19 世纪末起，两个词在社会学中被组合使用，尤其在涂尔干的著作里，用来指个体与群体被联结为集体生活。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first citation of the exact phrase): the combination formed gradually in sociological writing, so no single first use is established; the link of socius to sequi and the pre-Latin origin of the root are reconstructions.","cn":"来源不确定（确切短语的首见书证）：这一组合在社会学写作中逐步形成，没有公认的首次使用；socius 与 sequi 的联系及其拉丁语之前的来源均属重构。"}]},"similar":{"note":{"en":"Group one holds expressions that look close in form but name something else; group two holds near neighbours that describe related but distinct social processes.","cn":"第一组是形式相近却指别的事的表达；第二组是语义相邻、但描述不同社会过程的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"socialization","ipa":"/ˌsəʊʃəlaɪˈzeɪʃən/","tag":"form near, meaning different","definition":"The process by which a child or newcomer learns the norms and skills of a society; it names learning, not the resulting union of groups.","definitionCN":"指儿童或新来者学习社会规范与技能的过程，强调的是学习，而非群体最终形成的联结。"},{"word":"social inclusion","ipa":"/ˌsəʊʃəl ɪnˈkluːʒən/","tag":"access, not union","definition":"A policy phrase about giving excluded people access to services and opportunities; it stresses access rather than the ties that follow.","definitionCN":"关于让被排斥者获得服务与机会的政策短语，强调「能够进入」，而非随后形成的联结。"},{"word":"societal","ipa":"/səˈsaɪətəl/","tag":"adjective only","definition":"An adjective meaning 'of society as a whole'; it describes a level of analysis and never names a process of joining.","definitionCN":"形容词，意为「整个社会的」，只描述分析层次，从不指联合的过程。"}]},{"heading":"NEAR MEANING","entries":[{"word":"assimilation","ipa":"/əˌsɪməˈleɪʃən/","tag":"one-way absorption","definition":"The process by which a minority group is absorbed into the dominant culture, often at the cost of its own language; integration does not demand that cost.","definitionCN":"少数群体被主流文化吸收的过程，往往以其自身语言为代价；社会融合不要求这种代价。"},{"word":"social cohesion","ipa":"/ˌsəʊʃəl kəʊˈhiːʒən/","tag":"the bond, not the process","definition":"The strength of the bonds that hold a society together; it names the resulting glue, while integration names the movement that produces it.","definitionCN":"把社会维系在一起的联结强度，指作为结果的黏合力，而 integration 指产生它的运动。"},{"word":"inclusion","ipa":"/ɪnˈkluːʒən/","tag":"being admitted","definition":"The practice of admitting people to opportunities and settings; it covers access, whereas integration also covers the ties formed after access.","definitionCN":"把人接纳进机会与场所的做法，覆盖「进入」；integration 还覆盖进入之后形成的联结。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"socialis 'of companions' plus integrare 'to make whole': making companions out of strangers.","cn":"socialis「同伴的」加 integrare「使完整」：把陌生人做成同伴。"},{"en":"Integer is 'untouched, whole', built from in- 'not' plus the root of tangere 'to touch'.","cn":"integer 是「未受触动、完整」，由 in-「不」加 tangere「触碰」的词根构成。"},{"en":"The family runs social, society, sociable, integrate, integral, integrity, integration.","cn":"同族词包括 social、society、sociable、integrate、integral、integrity、integration。"},{"en":"Fixed phrases mark the public sense: promote social integration, barriers to social integration.","cn":"固定搭配标出公共义：促进社会融合、社会融合的障碍。"},{"en":"Its opposite in policy talk is segregation, the separating of groups that integration would join.","cn":"政策话语中的反义是 segregation，即把本应联合的群体分开。"}],"abstract":[{"en":"Picture two tables pushed together until the seam is too narrow to see.","cn":"想象两张桌子被推到接缝窄得看不见。"},{"en":"Picture a torn map rejoined, with the crease still faintly visible.","cn":"想象一张撕开的地图被重新拼合，折痕仍隐约可见。"},{"en":"Picture a bridge that joins two villages yet belongs to neither of them.","cn":"想象一座桥把两个村子连起来，却不属于任何一村。"}]},"examples":[{"en":"The city funded evening classes as a tool of social integration.","cn":"该市资助夜间课程，把它作为社会融合的工具。"},{"en":"High-rise estates can slow social integration when they isolate newcomers.","cn":"高层住宅区若把新来者隔离开，会拖慢社会融合。"},{"en":"Surveys that measure social integration must distinguish contact from trust.","cn":"测量社会融合的调查必须把接触与信任区分开。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"social（社会的）+ integration（整合）＝ 社会整合；记「陌生人先在长桌旁同坐，再在同一套规则里同住」。","word":"social integration"},"root":"拉丁 socius「同伴、同盟」（通行词源资料与 sequi「跟随」相联系）+ 拉丁 integer「完整、未受触动」＝ in-「不」+ tangere「触碰」，经 integrare「使完整」；短语在 19 世纪末社会学文献中逐步定型。","sensesIntro":{"en":"Eight senses follow one movement: strangers meet, meet again under shared rules, are counted as members, and finally the meeting itself is turned into a score.","cn":"八个义项沿同一个运动展开：陌生人相遇、在共享规则下反复相遇、被算作成员，最后连这场相遇本身也被折算成分数。"},"semanticMap":{"core":{"en":"CORE IMAGE: two groups around one long table, with the boundary between them fading as ordinary contact repeats.","cn":"核心意象：两组人围在同一张长桌旁，随着日常接触反复发生，他们之间的界线逐渐消失。"},"chain":["STRANGERS","CONTACT","RECOGNITION","SHARED RULES","ONE WHOLE","MEASURED SCORE"],"branches":[{"senses":"01","en":"DAILY CONTACT: the phrase begins with ordinary encounters between newcomers and established residents.","cn":"日常接触：短语从新来者与原住户的普通相遇开始。"},{"senses":"02 · 03","en":"TIE AND FITTED PARTS: sociology measures the collective bond, while institutions are the parts being fitted into one system.","cn":"联结与装配：社会学测量集体的黏合，机构则是被装进同一系统的部件。"},{"senses":"04 · 05","en":"TWO DOORS: the classroom and the workplace are where repeated contact turns into membership.","cn":"两扇门：课堂与职场是反复接触转变为成员身份的地方。"},{"senses":"06 · 07","en":"TWO SURFACES: shared streets and shared screens give the same process a place to happen.","cn":"两个表面：共享的街道与共享的屏幕给同一过程提供发生之处。"},{"senses":"08","en":"THE SCORE: what was a process becomes a number that policy can compare across regions.","cn":"分数：原本是过程的东西变成一个可在地区间比较的数字。"}]},"affixes":{"intro":{"en":"Both halves of the phrase are Latin nouns built from a root and a suffix, and both roots also build large English families, so the phrase can be read morpheme by morpheme.","cn":"短语的两半都是词根加后缀构成的拉丁名词，两个词根还各构成一个英语大词族，因此可以按语素逐个读出。"},"latinIntro":{"en":"Latin socius and socialis supply the social half; integer, integrare and integratio supply the integration half. The prefix in- in integer is negative, not the in- of 'into'.","cn":"拉丁 socius 与 socialis 提供 social 这一半；integer、integrare 与 integratio 提供 integration 这一半。integer 中的 in- 是否定前缀，不是表示「进入」的 in-。"},"items":[{"word":"socius","structure":"socius (Latin noun, second declension, 'companion')","meaning":"companion; ally","meaningCN":"同伴；同盟者","example":"The root names the person one travels with.","exampleCN":"这个词根指与自己同行的人。"},{"word":"socialis","structure":"socialis (Late Latin adjective, from socius)","meaning":"of companions; of alliance","meaningCN":"同伴的；结盟的","example":"The adjective moved the root from persons to relations.","exampleCN":"这个形容词把词根从人转向关系。"},{"word":"societas","structure":"societas (Latin noun, third declension)","meaning":"association; partnership; society","meaningCN":"联合；伙伴关系；社会","example":"The abstract noun names the whole formed by companions.","exampleCN":"这个抽象名词指同伴们形成的整体。"},{"word":"integer","structure":"integer (Latin adjective, in- 'not' + tag- 'touch')","meaning":"whole; untouched; intact","meaningCN":"完整的；未受触动的","example":"What is not touched remains whole.","exampleCN":"未被触碰的东西保持完整。"},{"word":"tangere","structure":"tangere (Latin verb, third conjugation)","meaning":"to touch","meaningCN":"触碰","example":"Its root supplies intact and contact as well.","exampleCN":"它的词根还给出 intact 与 contact。"},{"word":"integrare","structure":"integrare (Latin verb, first conjugation)","meaning":"to make whole; to renew","meaningCN":"使完整；更新","example":"The verb turns wholeness into an action.","exampleCN":"这个动词把「完整」变成动作。"},{"word":"integratio","structure":"integratio (Late Latin noun, -tio action suffix)","meaning":"a making whole; a renewal","meaningCN":"使完整；更新","example":"The action suffix names the process rather than the actor.","exampleCN":"动作后缀命名的是过程，而不是施动者。"},{"word":"social","structure":"social (English adjective, from Old French social)","meaning":"of companions or society","meaningCN":"同伴的；社会的","example":"The adjective describes the human side of the union.","exampleCN":"这个形容词描述联结中属于人的一面。"},{"word":"integration","structure":"integrate + -ion (English action noun)","meaning":"the act or result of making whole","meaningCN":"使完整的行为或结果","example":"The noun names both the work and its outcome.","exampleCN":"这个名词既指工作，也指结果。"},{"word":"integrationist","structure":"integration + -ist (person or advocate)","meaning":"one who advocates integration","meaningCN":"主张融合的人","example":"The suffix marks a person who takes a side.","exampleCN":"这个后缀标记采取某一立场的人。"}],"latinEntries":[{"word":"socius","structure":"socius, socii (m., second declension)","meaning":"companion, ally, associate","meaningCN":"同伴；同盟者；伙伴"},{"word":"socialis","structure":"socialis, sociale (adj., third declension)","meaning":"of companions, of alliance","meaningCN":"同伴的；结盟的"},{"word":"societas","structure":"societas, societatis (f., third declension)","meaning":"association, partnership, society","meaningCN":"联合；伙伴关系；社会"},{"word":"integer","structure":"integer, integra, integrum (adj., first and second declension)","meaning":"whole, untouched, intact","meaningCN":"完整的；未受触动的"},{"word":"integrare","structure":"integrare, integravi, integratum (verb, first conjugation)","meaning":"to make whole, renew, restore","meaningCN":"使完整；更新；恢复"},{"word":"integratio","structure":"integratio, integrationis (f., third declension)","meaning":"a making whole, a renewal","meaningCN":"使完整；更新"}]}},{"word":"psychologist","ipa_uk":"/saɪˈkɒlədʒɪst/","ipa_us":"/saɪˈkɑːlədʒɪst/","definition_zh":"心理学家；心理学工作者：以科学方法研究心智与行为的人，也指从事心理咨询、心理测验或组织应用的执业者","definition_en":"a person trained in the scientific study of the mind and behaviour, or one who applies that training in counselling, testing or organisations","core_image":"隔着单向玻璃的观察室里，一个人记录受试者按键前的停顿，纸上画满一格一格的时间刻度","scene":"隔着一面单向玻璃，研究者记录受试者按键前的停顿，把每一次犹豫都标在时间轴上。The clinic hired a psychologist to treat those pauses as data rather than noise.","sceneCN":"这里指受过训练、以观察与测量研究心智与行为的人（第 1 个义项：心理学家这一职业身份）；句意为诊所请了一位心理学家，把这些停顿当作数据而非噪声。","pos":[{"tag":"n.","zh":"心理学家；心理学研究者"},{"tag":"n.","zh":"心理师；心理咨询或心理治疗执业者"}],"collocations":[{"phrase":"clinical psychologist","zh":"临床心理师"},{"phrase":"school psychologist","zh":"学校心理师"},{"phrase":"educational psychologist","zh":"教育心理学家"},{"phrase":"industrial psychologist","zh":"工业心理学家"},{"phrase":"consult a psychologist","zh":"咨询心理师"},{"phrase":"a licensed psychologist","zh":"持照心理师"}],"forms":[{"label":"单数","form":"psychologist"},{"label":"复数","form":"psychologists"},{"label":"所属学科（名词）","form":"psychology"},{"label":"形容词","form":"psychological"},{"label":"副词","form":"psychologically"}],"derivatives":[{"word":"psychology","pos":"n.","zh":"psycho-（心智） + -logy（学科）→ 研究心智与行为的学科"},{"word":"psychological","pos":"adj.","zh":"psychology + -ical（属于……的）→ 属于心理或心理学的"},{"word":"psychologically","pos":"adv.","zh":"psychological + -ly（方式副词）→ 从心理层面"},{"word":"psychologize","pos":"v.","zh":"psychology + -ize（使动）→ 用心理学的语言解释，语义偏移为「做心理分析」"},{"word":"psychologism","pos":"n.","zh":"psychology + -ism（主义、倾向）→ 把一切问题化约为心理问题的倾向"}],"senses":[{"no":"01","title":"A researcher of mind and behaviour","titleCN":"研究心智与行为的研究者","definition":"a person who studies mental processes and behaviour by experiment, observation or measurement","definitionCN":"以实验、观察或测量研究心理过程与行为的人","example":"The psychologist ran the memory task with two hundred volunteers.","exampleCN":"这位心理学家让两百名志愿者做了记忆任务。","why":"psychologist is psychology plus -ist 'one who practises', so the word names the person before it names any particular job.","whyCN":"psychologist 是 psychology 加表示「从事者」的 -ist，因此这个词先指人，再指具体岗位。"},{"no":"02","title":"A clinical or counselling practitioner","titleCN":"临床或咨询心理师","definition":"a licensed professional who assesses and treats emotional or behavioural difficulties through talk-based methods","definitionCN":"以谈话等方法评估并处理情绪或行为困难的持照专业人员","example":"A clinical psychologist saw him weekly for a year.","exampleCN":"一位临床心理师每周为他看诊，持续了一年。","why":"the same training was applied to illness, so the title expanded from the laboratory to the consulting room.","whyCN":"同样的训练被用于疾病，头衔便从实验室扩展到诊室。"},{"no":"03","title":"A school psychologist","titleCN":"学校心理师","definition":"a professional employed by a school to assess learning difficulties and support pupils and teachers","definitionCN":"受雇于学校，评估学习困难并支持学生与教师的专业人员","example":"The school psychologist tested the pupil for a reading difficulty.","exampleCN":"学校心理师为这名学生做了阅读困难评估。","why":"schools need measurement and advice on learning, which is a natural home for the applied title.","whyCN":"学校需要测量与学习建议，这正是这个应用头衔的自然落点。"},{"no":"04","title":"An educational psychologist","titleCN":"教育心理学家","definition":"a specialist who studies how people learn and advises on teaching, curriculum and assessment","definitionCN":"研究人如何学习，并就教学、课程与评估提供建议的专家","example":"An educational psychologist redesigned the spelling programme.","exampleCN":"一位教育心理学家重新设计了拼写课程。","why":"the discipline has a branch for learning, and its practitioner carries the branch name.","whyCN":"这门学科有专门研究学习的分支，从业者便带着该分支的名字。"},{"no":"05","title":"An industrial and organisational psychologist","titleCN":"工业与组织心理学家","definition":"a specialist who applies psychology to hiring, teamwork, performance and workplace well-being","definitionCN":"把心理学用于招聘、团队、绩效与职场福祉的专家","example":"An industrial psychologist audited the hiring tests for bias.","exampleCN":"一位工业心理学家审查了招聘测试中的偏见。","why":"wherever people work in groups, measurement and behaviour study can be sold as a service, and the title follows the market.","whyCN":"只要人们成群工作，测量与行为研究就能作为服务出售，头衔便跟着市场走。"},{"no":"06","title":"A tester who administers assessments","titleCN":"实施与解释心理测评的人","definition":"a person who administers standardised tests and interprets the scores for schools, clinics or courts","definitionCN":"为学校、诊所或法庭实施标准化测验并解释分数的人","example":"The psychologist administered the standardised test under timed conditions.","exampleCN":"心理师在计时条件下实施了标准化测验。","why":"testing is the oldest applied skill of the field, and the person who administers a test is still called by the same title.","whyCN":"测评是这一领域最古老的应用技能，实施测验的人仍用同一头衔。"},{"no":"07","title":"A sport psychologist","titleCN":"运动心理师","definition":"a specialist who works with athletes on attention, arousal, routine and competitive stress","definitionCN":"帮助运动员处理注意、唤醒水平、赛前程序与竞赛压力的专家","example":"The sport psychologist taught the sprinter a pre-race routine.","exampleCN":"运动心理师教给短跑选手一套赛前程序。","why":"performance under pressure is a measurable behaviour, so a branch of practice grew around it.","whyCN":"压力下的表现是一种可测量的行为，围绕它便长出一个实践分支。"},{"no":"08","title":"A forensic or legal psychologist","titleCN":"司法心理师","definition":"a specialist who assesses memory, risk or competence for courts and legal proceedings","definitionCN":"为法庭与法律程序评估记忆、风险或行为能力的人","example":"A forensic psychologist warned the court about false eyewitness confidence.","exampleCN":"一位司法心理师提醒法庭注意目击者的虚假自信。","why":"courts need evidence about perception and decision, which puts the title inside the courtroom.","whyCN":"法庭需要关于知觉与决策的证据，这个头衔因此进了审判庭。"},{"no":"09","title":"The older student of the soul","titleCN":"早期研究「灵魂」的人","definition":"a scholar of the soul or mind in the period before psychology became an experimental science","definitionCN":"在心理学成为实验科学之前研究灵魂或心智的学者","example":"Eighteenth-century psychologists argued about the seat of the soul.","exampleCN":"十八世纪的心理学家争论灵魂的居所。","why":"the Greek root psykhe meant 'breath, life, soul', so the earliest bearer of the title studied the soul, not behaviour.","whyCN":"希腊词根 psykhe 意为「气息、生命、灵魂」，最早带这个头衔的人研究的是灵魂，而非行为。"}],"etymology":{"intro":{"en":"Psychologist is psychology plus the agent suffix -ist. Psychology is a New Latin coinage joining Greek psykhe 'breath, life, soul' and logos 'word, account, reason'. Dates are approximate.","cn":"psychologist 是 psychology 加表施动者的后缀 -ist。psychology 是新拉丁语造词，把希腊语 psykhe「气息、生命、灵魂」与 logos「言说、论述、理性」合在一起。年代为约数。"},"items":[{"era":"GREEK PSYKHE","en":"Psykhe meant 'breath, life, soul', the breath that marks a living being; the related verb psychein meant 'to breathe'. The word could also name the departed spirit.","cn":"psykhe 意为「气息、生命、灵魂」，是标记活物的那口气；相关动词 psychein 意为「呼吸」。这个词也可指离体的亡灵。"},{"era":"GREEK LOGOS","en":"Logos meant 'word, speech, account, reason'. In compound names of disciplines, -logia meant 'the study or systematic account of'.","cn":"logos 意为「言词、叙述、道理、理性」。在学科复合名称中，-logia 意为「对……的研究或系统论述」。"},{"era":"NEW LATIN","en":"The compound psychologia appeared in sixteenth-century academic Latin for the study of the soul, before any experimental method existed.","cn":"复合词 psychologia 在 16 世纪的学术拉丁语中出现，指对灵魂的研究，当时还没有任何实验方法。"},{"era":"ENGLISH PSYCHOLOGY","en":"Psychology entered English in the seventeenth century as the study of the soul; the modern scientific sense dates from the nineteenth century, when laboratories and measurement were established.","cn":"psychology 在 17 世纪进入英语，指对灵魂的研究；现代科学义始于 19 世纪，那时实验室与测量方法已经建立。"},{"era":"AGENT SUFFIX -IST","en":"Greek -istes 'one who practises' passed through Latin -ista into English -ist, so psychologist names the person who practises psychology.","cn":"希腊语 -istes「从事者」经拉丁语 -ista 进入英语成为 -ist，因此 psychologist 指从事心理学的人。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first coiner and first English use): several sixteenth-century authors used psychologia independently, and the exact first English use of psychologist is not settled; the date given here is approximate.","cn":"来源不确定（首创者与英语首见）：16 世纪有数位作者各自使用 psychologia，psychologist 的确切英语首见亦无定论；此处年代为约数。"}]},"similar":{"note":{"en":"Group one holds titles built on the same psych- stem that name different roles; group two holds people who also sit with a client but are trained differently.","cn":"第一组是同出 psych- 词干、却指不同角色的头衔；第二组是同样与来访者对坐、但训练路径不同的人。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"psychiatrist","ipa":"/saɪˈkaɪətrɪst/","tag":"medical doctor","definition":"A physician who has completed medical training and may prescribe drugs; a psychologist normally cannot prescribe.","definitionCN":"完成医学训练的医生，可以开药；心理学家通常不能开药。"},{"word":"psychoanalyst","ipa":"/ˌsaɪkəʊˈænəlɪst/","tag":"one school only","definition":"A practitioner trained in the Freudian or related analytic tradition, not in academic psychology as a whole.","definitionCN":"受弗洛伊德或相关分析传统训练的人，而非接受整个学术心理学训练的人。"},{"word":"psychometrician","ipa":"/ˌsaɪkəʊməˈtrɪʃən/","tag":"test specialist","definition":"A specialist in the construction and statistical validation of tests; the role is narrower than the general title.","definitionCN":"专做测验编制与统计验证的人，角色比通称更窄。"}]},{"heading":"NEAR MEANING","entries":[{"word":"therapist","ipa":"/ˈθerəpɪst/","tag":"treatment focus","definition":"A general title for one who treats mental or physical difficulties; many therapists lack a psychology degree.","definitionCN":"处理心理或身体困难者的通称；许多治疗师并没有心理学学位。"},{"word":"counsellor","ipa":"/ˈkaʊnsələ/","tag":"advice and support","definition":"A practitioner who offers structured listening and advice, often in schools or community services.","definitionCN":"提供有结构的倾听与建议的从业者，常见于学校或社区服务。"},{"word":"clinician","ipa":"/ˈklɪnɪʃən/","tag":"bedside work","definition":"Anyone who works directly with patients, including physicians and nurses; the word marks setting, not discipline.","definitionCN":"任何直接接触病人的人，包括医生与护士；这个词标记工作场所，不标记学科。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real compounds and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实复合词与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"psykhe 'soul' plus logos 'account': an account of the soul, later an account of behaviour.","cn":"psykhe「灵魂」加 logos「论述」：关于灵魂的论述，后来变成关于行为的论述。"},{"en":"-ist marks the person, so psychologist is the one who practises what psychology studies.","cn":"-ist 标记人，因此 psychologist 就是从事心理学所研究之事的人。"},{"en":"The family runs psychology, psychological, psychologically, psychologize, psychologism.","cn":"同族词包括 psychology、psychological、psychologically、psychologize、psychologism。"},{"en":"Job titles pin the branches: clinical, school, educational, industrial, sport and forensic.","cn":"岗位头衔钉住各分支：临床、学校、教育、工业、运动与司法。"},{"en":"The oldest sense is the soul, which is why the spelling begins with psych- and not with behav-.","cn":"最古老的义项是灵魂，这正是拼写以 psych- 开头而不是以 behav- 开头的原因。"}],"abstract":[{"en":"Picture a person who watches a key press and writes down a number instead of a feeling.","cn":"想象一个人盯着一次按键，写下的是一个数字，而不是一种感受。"},{"en":"Picture two rooms separated by glass: one person performs, the other measures.","cn":"想象被玻璃隔开的两间屋子：一间里的人在表现，另一间的人在测量。"},{"en":"Picture an old manuscript titled 'on the soul' slowly acquiring a stopwatch.","cn":"想象一册题为「论灵魂」的旧手稿，慢慢多了一只秒表。"}]},"examples":[{"en":"The psychologist compared reaction times across age groups.","cn":"这位心理学家比较了不同年龄组的反应时。"},{"en":"A psychologist may not prescribe drugs unless trained as a physician.","cn":"心理学家除非受过医学训练，否则不能开药。"},{"en":"The school hired a psychologist to review its assessment policy.","cn":"学校聘请了一位心理师来审查评估政策。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"psycho（心智）+ log（研究）+ ist（人）＝ 研究心智的人；记「玻璃两侧：一侧表现，一侧测量」。","word":"psychologist"},"root":"希腊 psykhe「气息、生命、灵魂」+ logos「言说、论述、理性」，经新拉丁 psychologia「灵魂之学」加 -istes「从事者」；更深词源无定论，psykhe 与「呼吸」的联系为通行解释。","sensesIntro":{"en":"Nine senses follow one trained observer: first the researcher, then the clinic, the school, the classroom, the office, the test room, the track, the court, and finally the older student of the soul.","cn":"九个义项沿着同一个受过训练的观察者展开：先是研究者，再依次是诊室、学校、课堂、办公室、测评室、赛场、法庭，最后回到早期研究灵魂的人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a trained observer on one side of glass, recording a measurable act on the other side.","cn":"核心意象：受过训练的观察者站在玻璃一侧，记录另一侧可测量的行为。"},"chain":["SOUL","STUDY","MEASURE","EXPLAIN","TREAT","APPLY"],"branches":[{"senses":"01","en":"THE RESEARCHER: the title begins as the person who studies and measures mind and behaviour.","cn":"研究者：这个头衔最初指研究并测量心智与行为的人。"},{"senses":"02 · 03","en":"THE HELPING ROOMS: clinic and school take the same training into assessment and care.","cn":"助人的房间：诊室与学校把同一套训练带进评估与照护。"},{"senses":"04 · 05","en":"THE INSTITUTIONS: learning and work each grow a branch with its own title.","cn":"机构：学习与工作各自长出一个带专属头衔的分支。"},{"senses":"06 · 07","en":"THE TEST AND THE TRACK: administering a score and shaping a routine are both applied measurement.","cn":"测评与赛场：给分与塑造赛前程序，都是应用性的测量。"},{"senses":"08 · 09","en":"THE COURT AND THE SOUL: the title reaches legal evidence at one end and the old study of the soul at the other.","cn":"法庭与灵魂：这个头衔一端抵达法律证据，另一端回到古老的灵魂之学。"}]},"affixes":{"intro":{"en":"Psychologist can be read as two Greek roots plus two suffixes: psykhe and logos build the discipline, -logia names it, and -ist names the person.","cn":"psychologist 可以读作两个希腊词根加两个后缀：psykhe 与 logos 构成学科，-logia 命名学科，-ist 命名人。"},"latinIntro":{"en":"The discipline name is New Latin, coined from Greek elements; Latin supplies the shape of the suffixes -logia and -ista, which English shortened to -logy and -ist.","cn":"学科名是新拉丁语，用希腊成分造出；拉丁语提供了 -logia 与 -ista 后缀的外形，英语将其缩短为 -logy 与 -ist。"},"items":[{"word":"psykhe","structure":"psykhe (Greek noun, 'breath, life, soul')","meaning":"breath; life; soul","meaningCN":"气息；生命；灵魂","example":"The root names what early writers thought left the body at death.","exampleCN":"这个词根指早期作者认为死亡时离开身体的东西。"},{"word":"logos","structure":"logos (Greek noun, 'word, account, reason')","meaning":"word; account; reason","meaningCN":"言词；论述；理性","example":"The root turns a subject into a field of study.","exampleCN":"这个词根把一个主题变成一门研究领域。"},{"word":"-logia","structure":"-logia (Greek suffix, 'study of')","meaning":"the study or systematic account of","meaningCN":"对……的研究或系统论述","example":"The suffix appears in biology, geology and psychology alike.","exampleCN":"这个后缀同样出现在 biology、geology 与 psychology 中。"},{"word":"psychologia","structure":"psychologia (New Latin noun, sixteenth century)","meaning":"the study of the soul","meaningCN":"灵魂之学","example":"The New Latin noun predates any laboratory.","exampleCN":"这个新拉丁名词早于任何实验室。"},{"word":"psychology","structure":"psycho- + -logy (English noun)","meaning":"the study of mind and behaviour","meaningCN":"研究心智与行为的学科","example":"The English noun narrowed from soul to behaviour.","exampleCN":"这个英语名词从灵魂收窄到行为。"},{"word":"psychological","structure":"psychology + -ical (adjective)","meaning":"relating to the mind or to psychology","meaningCN":"与心智或心理学有关的","example":"The adjective describes what the noun studies.","exampleCN":"这个形容词描述这门学科所研究的东西。"},{"word":"psychologist","structure":"psychology + -ist (person who practises)","meaning":"one who practises psychology","meaningCN":"从事心理学的人","example":"The suffix marks the practitioner rather than the field.","exampleCN":"这个后缀标记从业者，而非领域。"},{"word":"psychologize","structure":"psychology + -ize (verb-forming)","meaning":"to explain in psychological terms","meaningCN":"用心理学术语解释","example":"The verb often carries a note of criticism.","exampleCN":"这个动词常带一点批评意味。"},{"word":"-ist","structure":"-ista (Latin, from Greek -istes, agent suffix)","meaning":"one who practises or follows","meaningCN":"从事者；信奉者","example":"It also builds biologist, economist and therapist.","exampleCN":"它也构成 biologist、economist 与 therapist。"}],"latinEntries":[{"word":"psychologia","structure":"psychologia (New Latin, from Greek psykhe + -logia)","meaning":"the study of the soul","meaningCN":"灵魂之学"},{"word":"psychologicus","structure":"psychologicus, psychologica, psychologicum (New Latin adjective)","meaning":"of the study of the soul","meaningCN":"属于灵魂之学的"}]}},{"word":"behaviorism","ipa_uk":"/bɪˈheɪvjərɪzəm/","ipa_us":"/bɪˈheɪvjərɪzəm/","definition_zh":"行为主义：主张心理学只研究可观察、可测量的行为，并以刺激、反应与环境塑造解释行为的学派","definition_en":"the school of psychology that studies only observable behaviour and explains it through stimulus, response and environmental shaping","core_image":"迷宫角落里的小鼠反复撞上同一面墙，实验者只在纸上画下它转向的次数，不写任何关于「想法」的句子","scene":"迷宫里的老鼠每撞到同一面墙就折返，实验者只记下折返次数与耗时，不写它「在想什么」。The laboratory's early behaviorism refused to speculate about anything hidden inside the animal's head.","sceneCN":"这里指只研究可观察行为、拒绝推测内部心理的学派立场（第 1 个义项：行为主义的一般定义）；句意为该实验室早期的行为主义拒绝推测动物头脑里隐藏的东西。","pos":[{"tag":"n.","zh":"行为主义（不可数，指心理学学派与立场）"}],"collocations":[{"phrase":"classical behaviorism","zh":"经典行为主义"},{"phrase":"operant behaviorism","zh":"操作性行为主义"},{"phrase":"the rise of behaviorism","zh":"行为主义的兴起"},{"phrase":"behaviorism in education","zh":"教育中的行为主义"},{"phrase":"a critique of behaviorism","zh":"对行为主义的批评"},{"phrase":"behaviorism and cognitivism","zh":"行为主义与认知主义"}],"forms":[{"label":"不可数名词","form":"behaviorism"},{"label":"英式拼写","form":"behaviourism"},{"label":"形容词","form":"behavioristic"},{"label":"另一形容词","form":"behavioral"},{"label":"副词","form":"behaviorally"}],"derivatives":[{"word":"behaviorist","pos":"n./adj.","zh":"behavior + -ist（从事者）→ 行为主义者；行为主义取向的"},{"word":"behavioristic","pos":"adj.","zh":"behaviorist + -ic（属于……的）→ 属于行为主义方法的"},{"word":"behavioral","pos":"adj.","zh":"behavior + -al（与……有关的）→ 与行为有关的，语义已脱离学派"},{"word":"behaviorally","pos":"adv.","zh":"behavioral + -ly（方式副词）→ 从行为层面"},{"word":"behavior","pos":"n.","zh":"behave + -ior（状态名词）→ 表现出的举止，是 -ism 的构词基础"}],"senses":[{"no":"01","title":"The school that studies only behaviour","titleCN":"只研究可观察行为的心理学学派","definition":"the view that psychology should study only what can be observed and measured, and should not speculate about inner states","definitionCN":"主张心理学只研究可观察、可测量之物，不推测内部状态的观点","example":"Behaviorism pushed psychology toward the laboratory and away from introspection.","exampleCN":"行为主义把心理学推向实验室，远离内省。","why":"behavior plus -ism names a doctrine about behaviour, so the word is the name of a school before it is the name of a method.","whyCN":"behavior 加 -ism 命名一种关于行为的学说，因此这个词先是学派名，再是方法名。"},{"no":"02","title":"Classical behaviorism after Watson","titleCN":"华生式的经典行为主义","definition":"the early twentieth-century programme that made observable response the only admissible subject matter of psychology","definitionCN":"20 世纪初把可观察反应定为心理学唯一合法题材的纲领","example":"Classical behaviorism banned the word 'image' from its laboratory reports.","exampleCN":"经典行为主义禁止在实验报告里使用「意象」一词。","why":"the school needed a manifesto, and its first version was the strictest: if it cannot be seen, it cannot be studied.","whyCN":"这个学派需要一份宣言，最早版本最为严格：看不见的就不能研究。"},{"no":"03","title":"Operant behaviorism after Skinner","titleCN":"斯金纳式的操作性行为主义","definition":"the programme that explains behaviour by its consequences, using reinforcement and punishment to shape what is repeated","definitionCN":"以后果解释行为，用强化与惩罚塑造哪些动作被重复的纲领","example":"Operant behaviorism described learning as a change in the rate of a response.","exampleCN":"操作性行为主义把学习描述为反应速率的变化。","why":"consequences are observable, so the school could keep its rule while gaining a powerful account of voluntary action.","whyCN":"后果是可观察的，学派因此能守住原则，同时得到一套解释自愿动作的有力说法。"},{"no":"04","title":"A stimulus-response research stance","titleCN":"刺激—反应的研究取向","definition":"the practice of describing behaviour as a link between a presented stimulus and a measured response","definitionCN":"把行为描述为呈现的刺激与测得的反应之间的联结","example":"The stimulus-response stance reduced a complex task to a chain of measured links.","exampleCN":"刺激—反应取向把复杂任务化为一条由测量联结组成的链。","why":"once inner states are excluded, what remains is a pairing, and the pairing becomes the unit of analysis.","whyCN":"内部状态一旦被排除，剩下的就是配对，配对便成为分析单位。"},{"no":"05","title":"Behaviorism in curriculum design","titleCN":"课程设计中的行为主义","definition":"the use of behavioural objectives, small steps and immediate feedback to build teaching programmes","definitionCN":"用行为目标、小步子与即时反馈来编写教学程序","example":"Programmed instruction carried behaviorism into ordinary classrooms.","exampleCN":"程序教学把行为主义带进普通课堂。","why":"if learning is a measurable change, then teaching can be engineered as a sequence of measurable steps.","whyCN":"如果学习是可测量的变化，教学就能被工程化为一系列可测量的步骤。"},{"no":"06","title":"Behaviour modification and therapy","titleCN":"行为矫正与行为治疗","definition":"the clinical application of reinforcement schedules to increase or decrease specific behaviours","definitionCN":"把强化程式用于增加或减少特定行为的临床应用","example":"Behaviorism supplied the schedules used in token economies.","exampleCN":"行为主义提供了代币制中使用的强化程式。","why":"a clinic needs a method that can be applied one behaviour at a time, which is exactly what the school offered.","whyCN":"诊所需要能逐个行为应用的方法，而这正是该学派提供的东西。"},{"no":"07","title":"The animal-laboratory tradition","titleCN":"动物实验传统的取向","definition":"the tradition of generalising from controlled animal experiments to principles of behaviour","definitionCN":"从受控动物实验推广出行为原理的传统","example":"Behaviorism treated the rat's lever press as a model of human choice.","exampleCN":"行为主义把老鼠按杠杆当作人类选择的模型。","why":"animals cannot report inner states, so a science of behaviour found its natural subject in the animal laboratory.","whyCN":"动物无法报告内部状态，因此行为科学在动物实验室里找到了天然对象。"},{"no":"08","title":"Neo-behaviorism and the cognitive turn","titleCN":"新行为主义与认知转向中的折中","definition":"later versions that admitted intervening variables or cognitive maps while keeping behavioural measurement","definitionCN":"允许中间变量或认知地图、但保留行为测量的后期版本","example":"Neo-behaviorism quietly let a 'map' back into the rat's head.","exampleCN":"新行为主义悄悄让「地图」回到老鼠脑中。","why":"measurement could be kept while hidden processes were readmitted as intervening variables, so the school bent rather than broke.","whyCN":"测量可以保留，隐藏过程能作为中间变量被重新接纳，学派因此弯折而没有断裂。"},{"no":"09","title":"The critical label for a mechanical view","titleCN":"批评义：把人看作反应机制","definition":"a critical use for any approach that treats people as passive machines responding to external control","definitionCN":"批评性地指任何把人当作被动机械、只对外部控制作出反应的取向","example":"Critics used behaviorism as a warning label for policy built on rewards alone.","exampleCN":"批评者把行为主义当作警示标签，指向只靠奖励建立的政策。","why":"because the school began by excluding inner life, its name became a shorthand for treating people as input-output devices.","whyCN":"由于该学派从排除内在生活开始，它的名字就成了把人当输入输出装置的简称。"}],"etymology":{"intro":{"en":"Behaviorism joins behave, an English verb of Germanic origin, with the doctrinal suffix -ism. The word is a twentieth-century coinage in psychology. Dates are approximate.","cn":"behaviorism 由英语动词 behave（日耳曼语来源）与表示学说的后缀 -ism 组成。这个词是 20 世纪心理学的造词。年代为约数。"},"items":[{"era":"OLD ENGLISH HABBAN","en":"Behave is be- plus have, from Old English habban 'to hold, possess'. The early sense was 'to hold or carry oneself in a certain way', not 'to act well'.","cn":"behave 由 be- 加 have 构成，have 来自古英语 habban「持有、拥有」。早期义为「以某种方式自持、举止」，并非「表现良好」。"},{"era":"MIDDLE ENGLISH BEHAVOUR","en":"The noun behavour, later behavior, named a manner of conducting oneself; it widened to cover the observable actions of animals and machines.","cn":"名词 behavour（后作 behavior）指自我举止的方式，后来扩展到动物与机器的可观察动作。"},{"era":"SUFFIX -ISM","en":"-Ism reached English through Latin -ismus from Greek -ismos, a suffix for systems, doctrines and practices.","cn":"-ism 经拉丁 -ismus 从希腊 -ismos 进入英语，是标记体系、学说与实践的后缀。"},{"era":"TWENTIETH-CENTURY COINAGE","en":"Behaviorism appeared in English in the early twentieth century, and Watson's 1913 manifesto made it the name of a school that excluded introspection.","cn":"behaviorism 在 20 世纪初出现于英语，华生 1913 年的宣言使它成为排除内省的学派之名。"},{"era":"REFLEXOLOGY AND OPERANT TURNS","en":"Russian reflexology supplied the stimulus-response frame, and Skinner's operant work from the 1930s supplied the second major version of the school.","cn":"俄国反射学提供了刺激—反应框架，斯金纳自 1930 年代起的操作性研究提供了该学派的第二个主要版本。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (exact coiner and first use): the noun appeared in print shortly before Watson's manifesto and several writers used it independently, so no single first use is established.","cn":"来源不确定（确切首创者与首见）：这个名词在华生宣言前不久已见于印刷品，数位作者各自使用，没有公认的首次使用。"}]},"similar":{"note":{"en":"Group one holds forms built on the same behave stem that are easily swapped; group two holds rival schools and approaches that also explain behaviour.","cn":"第一组是同出 behave 词干、极易张冠李戴的形式；第二组是同样解释行为的对立学派与取向。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"behaviorist","ipa":"/bɪˈheɪvjərɪst/","tag":"person, not school","definition":"The person or the adjective; behaviorism is the doctrine itself, so the two cannot replace each other in a sentence.","definitionCN":"指人或形容词；behaviorism 才是学说本身，两者在句中不能互换。"},{"word":"behavioral","ipa":"/bɪˈheɪvjərəl/","tag":"general adjective","definition":"Simply 'relating to behaviour'; it carries no commitment to the school and is used in medicine and economics.","definitionCN":"只表示「与行为有关的」，不含对学派的承诺，医学与经济学也用。"},{"word":"behaviourism","ipa":"/bɪˈheɪvjərɪzəm/","tag":"British spelling","definition":"The same word in British spelling; the difference is orthographic, not conceptual.","definitionCN":"同一个词的英式拼写，差别在正字法，不在概念。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cognitivism","ipa":"/ˈkɒɡnɪtɪvɪzəm/","tag":"the rival","definition":"The school that explains behaviour through internal representations and processing; it arose partly as a reaction against behaviorism.","definitionCN":"用内部表征与加工解释行为的学派，部分正是作为对行为主义的反弹而兴起。"},{"word":"functionalism","ipa":"/ˈfʌŋkʃənəlɪzəm/","tag":"earlier school","definition":"An earlier American school that asked what mental processes are for; it studied purpose rather than measurable response.","definitionCN":"更早的美国学派，追问心理过程有何用处，研究目的而非可测量的反应。"},{"word":"reflexology","ipa":"/ˌriːfleksˈɒlədʒi/","tag":"Russian frame","definition":"The Russian tradition that explained behaviour through reflexes; it supplied behaviorism's stimulus-response vocabulary.","definitionCN":"用反射解释行为的俄国传统，为行为主义提供了刺激—反应的词汇。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real historical labels and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实历史标签与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"be- 'about' plus have 'hold': behaviour is the way one holds oneself.","cn":"be-「围绕」加 have「持有」：行为就是一个人自持的方式。"},{"en":"-ism marks a doctrine, so behaviorism is a doctrine about behaviour, not behaviour itself.","cn":"-ism 标记学说，因此 behaviorism 是关于行为的学说，不是行为本身。"},{"en":"The family runs behave, behavior, behavioral, behaviorist, behavioristic, behaviorally.","cn":"同族词包括 behave、behavior、behavioral、behaviorist、behavioristic、behaviorally。"},{"en":"Fixed phrases mark the history: classical behaviorism, operant behaviorism, the rise of behaviorism.","cn":"固定搭配标出历史：经典行为主义、操作性行为主义、行为主义的兴起。"},{"en":"Its rival is cognitivism, which put the hidden processes back into the account.","cn":"它的对手是 cognitivism，把被排除的隐藏过程重新放回解释里。"}],"abstract":[{"en":"Picture a rat in a maze and a sheet of paper with nothing on it but tally marks.","cn":"想象迷宫里的老鼠，以及一张只画着计数刻痕的纸。"},{"en":"Picture a door with a sign reading 'no inner states admitted'.","cn":"想象一扇门，上面写着「内部状态不得入内」。"},{"en":"Picture a person reduced to a switch that is either pressed or not pressed.","cn":"想象一个人被化简成一个开关，要么被按下，要么没有被按下。"}]},"examples":[{"en":"Behaviorism dominated American psychology between the two world wars.","cn":"两次世界大战之间，行为主义主导了美国心理学。"},{"en":"The teacher rejected behaviorism because it ignored what pupils imagined.","cn":"这位教师拒绝行为主义，因为它忽略学生想象的内容。"},{"en":"Modern behaviorism survives mainly in applied behavior analysis.","cn":"现代行为主义主要存活于应用行为分析之中。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"behavior（行为）+ ism（主义）＝ 行为主义；记「只数转向次数，不问它在想什么」。","word":"behaviorism"},"root":"英语 behave（be- + 古英语 habban「持有」，原义「自持、举止」）+ 希腊经由拉丁的 -ismos／-ismus「学说、体系」；20 世纪初在心理学中定型，与华生 1913 年宣言相关。","sensesIntro":{"en":"Nine senses follow one refusal: inner states are excluded, so behaviour becomes a pairing, then a rate, then a technology, and finally a warning label.","cn":"九个义项沿着同一次拒绝展开：内部状态被排除，行为于是先成为配对，再成为速率、技术，最后成为警示标签。"},"semanticMap":{"core":{"en":"CORE IMAGE: an observer at a maze wall, tallying turns and writing nothing about what the animal thinks.","cn":"核心意象：观察者站在迷宫墙边，只记录转向次数，不写动物在想什么。"},"chain":["REFUSAL","OBSERVABLE ACT","PAIRING","CONSEQUENCE","SHAPING","WARNING"],"branches":[{"senses":"01","en":"THE DOCTRINE: the school begins by refusing to study anything that cannot be observed.","cn":"学说：这个学派从拒绝研究不可观察之物开始。"},{"senses":"02 · 03","en":"TWO VERSIONS: Watson's strict exclusion and Skinner's account through consequences are the two poles of the school.","cn":"两个版本：华生的严格排除与斯金纳用后果解释，是这一学派的两极。"},{"senses":"04 · 05","en":"PAIRING AND PROGRAMME: stimulus-response becomes the unit, and teaching becomes a sequence of such units.","cn":"配对与程序：刺激—反应成为单位，教学成为这些单位的序列。"},{"senses":"06 · 07","en":"CLINIC AND CAGE: the same schedules shape behaviour in token economies and in animal laboratories.","cn":"诊所与笼子：同一套程式在代币制与动物实验室里塑造行为。"},{"senses":"08 · 09","en":"BENDING AND BLAME: neo-behaviorism readmitted hidden variables, while critics kept the name as a warning.","cn":"弯折与责难：新行为主义重新接纳隐藏变量，批评者则把这个名字留作警示。"}]},"affixes":{"intro":{"en":"Behaviorism is an English compound of a Germanic verb and a Greek-derived suffix, so it can be read as 'the doctrine of conduct' without any Latin root.","cn":"behaviorism 是日耳曼语动词与希腊来源后缀构成的英语复合词，因此可以读作「关于举止的学说」，其中没有拉丁词根。"},"latinIntro":{"en":"No Latin root stands behind behave; only the suffix travelled through Latin, from Greek -ismos to Latin -ismus and then to English -ism.","cn":"behave 背后没有拉丁词根；只有后缀经拉丁语旅行，从希腊 -ismos 到拉丁 -ismus，再到英语 -ism。"},"items":[{"word":"be-","structure":"be- (Old English prefix, 'around, about')","meaning":"around; about","meaningCN":"围绕；关于","example":"The prefix turns a verb of holding into a verb of conducting oneself.","exampleCN":"这个前缀把「持有」的动词变成「自持」的动词。"},{"word":"habban","structure":"habban (Old English verb, 'to hold, have')","meaning":"to hold; to have","meaningCN":"持有；拥有","example":"The old verb survives inside modern have.","exampleCN":"这个古动词活在现代 have 之中。"},{"word":"behave","structure":"be- + have (English verb)","meaning":"to conduct oneself","meaningCN":"举止；表现","example":"The verb covers conduct that others can see.","exampleCN":"这个动词覆盖他人看得见的举止。"},{"word":"behavior","structure":"behave + -ior (English noun of state)","meaning":"observable conduct","meaningCN":"可观察的举止","example":"The noun is what the doctrine is named after.","exampleCN":"这个名词正是学说命名的依据。"},{"word":"-ism","structure":"-ismos (Greek suffix, via Latin -ismus)","meaning":"system, doctrine, practice","meaningCN":"体系；学说；实践","example":"The suffix also builds realism and socialism.","exampleCN":"这个后缀也构成 realism 与 socialism。"},{"word":"behaviorism","structure":"behavior + -ism","meaning":"the doctrine of behaviour","meaningCN":"关于行为的学说","example":"The compound names a school, not a single method.","exampleCN":"这个复合词命名一个学派，而非单一方法。"},{"word":"behaviorist","structure":"behavior + -ist (person or adjective)","meaning":"one who follows the doctrine","meaningCN":"信奉该学说的人","example":"The suffix shifts the name from doctrine to person.","exampleCN":"这个后缀把名字从学说转向人。"},{"word":"behavioristic","structure":"behaviorist + -ic (adjective)","meaning":"of the behaviorist method","meaningCN":"属于行为主义方法的","example":"The adjective describes a style of explanation.","exampleCN":"这个形容词描述一种解释风格。"},{"word":"behaviorally","structure":"behavioral + -ly (adverb)","meaning":"in terms of behaviour","meaningCN":"从行为层面","example":"The adverb marks the level of measurement.","exampleCN":"这个副词标记测量的层次。"}],"latinEntries":[]}},{"word":"behaviorist","ipa_uk":"/bɪˈheɪvjərɪst/","ipa_us":"/bɪˈheɪvjərɪst/","definition_zh":"行为主义者；行为主义心理学家；行为分析从业者；也作形容词，指行为主义取向的","definition_en":"a person who follows or practises behaviorism, or the adjective describing an approach that studies observable behaviour only","core_image":"实验台前只摆着秒表、计数表与几只开关，记录者从不递给受试者一张询问感受的问卷","scene":"实验台前只摆着秒表、计数表和几只开关，记录者不问受试者感觉如何。The lab's behaviorist reads every answer as a change in observable conduct.","sceneCN":"这里指信奉并实践行为主义的研究者（第 1 个义项：行为主义心理学家）；句意为该实验室的行为主义者把每一个回答都读成可观察行为的变化。","pos":[{"tag":"n.","zh":"行为主义者；行为主义心理学家"},{"tag":"adj.","zh":"行为主义取向的（如 behaviorist approach）"}],"collocations":[{"phrase":"a strict behaviorist","zh":"严格的行为主义者"},{"phrase":"behaviorist approach","zh":"行为主义取向的方法"},{"phrase":"behaviorist theory","zh":"行为主义理论"},{"phrase":"behaviorist explanation","zh":"行为主义式解释"},{"phrase":"train as a behaviorist","zh":"接受行为主义训练"},{"phrase":"behaviorist psychologist","zh":"行为主义心理学家"}],"forms":[{"label":"单数","form":"behaviorist"},{"label":"复数","form":"behaviorists"},{"label":"英式拼写","form":"behaviourist"},{"label":"形容词（方法论的）","form":"behavioristic"},{"label":"学说名","form":"behaviorism"}],"derivatives":[{"word":"behaviorism","pos":"n.","zh":"behavior + -ism（学说）→ 行为主义，是 -ist 所指的学说基础"},{"word":"behavioristic","pos":"adj.","zh":"behaviorist + -ic（属于……的）→ 属于行为主义方法的"},{"word":"behavioral","pos":"adj.","zh":"behavior + -al（与……有关的）→ 与行为有关的，已不带学派立场"},{"word":"behaviorally","pos":"adv.","zh":"behavioral + -ly（方式副词）→ 从行为层面"},{"word":"behavior","pos":"n.","zh":"behave + -ior（状态名词）→ 可观察的举止"}],"senses":[{"no":"01","title":"A psychologist of the behaviorist school","titleCN":"行为主义学派的心理学家","definition":"a psychologist who holds that only observable behaviour should be studied and who works within that programme","definitionCN":"主张只研究可观察行为、并在这一纲领内工作的心理学家","example":"As a behaviorist, she counted responses instead of asking for reports.","exampleCN":"作为行为主义者，她数反应次数，而不索取自我报告。","why":"behaviorism plus -ist names the person who holds the doctrine, just as socialism plus -ist names the person who holds that doctrine.","whyCN":"behaviorism 加 -ist 指持有该学说的人，正如 socialism 加 -ist 指持有那种学说的人。"},{"no":"02","title":"A follower of the doctrine","titleCN":"行为主义的信奉者","definition":"anyone who accepts the doctrine that behaviour should be explained without reference to inner states","definitionCN":"接受「解释行为时不援引内部状态」这一学说的人","example":"The new teacher was a behaviorist before she discovered cognitive psychology.","exampleCN":"这位新教师在她接触认知心理学之前是行为主义者。","why":"the suffix can mark adherence rather than profession, so a student or teacher can be called a behaviorist too.","whyCN":"这个后缀可以标记信奉而非职业，因此学生或教师也能被称为行为主义者。"},{"no":"03","title":"An applied behavior analyst","titleCN":"应用行为分析的从业者","definition":"a practitioner who uses reinforcement schedules to change specific behaviours in clinics, schools or homes","definitionCN":"在诊所、学校或家庭中用强化程式改变特定行为的从业者","example":"The behaviorist designed a reward schedule for the child's morning routine.","exampleCN":"这位行为分析从业者为孩子的早晨流程设计了奖励程式。","why":"the clinical wing of the school needed a name for its practitioners, and it took the shortest available label.","whyCN":"学派的临床分支需要给从业者一个名字，于是取了最短的现成标签。"},{"no":"04","title":"A designer of behaviour modification","titleCN":"行为矫正方案的设计者","definition":"a person who plans token systems, prompts and consequences to alter conduct in an institution","definitionCN":"在机构中设计代币制、提示与后果以改变行为的人","example":"The behaviorist rewrote the ward's token system after the audit.","exampleCN":"审查之后，这位行为矫正设计者改写了病房的代币制。","why":"modification is engineering rather than explaining, and the engineer of consequences is still called by the school's name.","whyCN":"矫正是工程而非解释，设计后果的工程师仍用该学派的名字。"},{"no":"05","title":"An animal-behaviour researcher","titleCN":"研究动物行为的人","definition":"a researcher who generalises principles of behaviour from controlled experiments with animals","definitionCN":"从受控动物实验推广行为原理的研究者","example":"The behaviorist trained pigeons to peck at coloured keys.","exampleCN":"这位行为研究者训练鸽子去啄彩色按键。","why":"animals cannot report inner states, so the doctrine's cleanest cases were always animal cases.","whyCN":"动物无法报告内部状态，因此该学说最干净的案例始终是动物案例。"},{"no":"06","title":"The adjective for a behaviorist approach","titleCN":"形容词：行为主义取向的","definition":"describing an explanation, design or reading that attends only to observable conduct","definitionCN":"描述一种只关注可观察行为的解释、设计或解读","example":"A behaviorist reading of the lesson ignored what pupils felt.","exampleCN":"对这节课的行为主义式解读忽略了学生的感受。","why":"English lets the same form serve as noun and adjective, so the person's label also labels the method.","whyCN":"英语允许同一形式兼作名词与形容词，因此指人的标签也标记方法。"},{"no":"07","title":"A programmer of instruction","titleCN":"程序教学的设计者","definition":"a curriculum designer who breaks learning into small steps with immediate feedback","definitionCN":"把学习拆成小步并配以即时反馈的课程设计者","example":"The behaviorist built a teaching machine with one step per frame.","exampleCN":"这位程序教学设计师造了一台每帧一步的教学机。","why":"if learning is a measurable change, the person who arranges the measures is a behaviorist by method.","whyCN":"如果学习是可测量的变化，那么安排这些测量的人按方法说就是行为主义者。"},{"no":"08","title":"The critical label for a mechanical observer","titleCN":"贬义：只看见反应的人","definition":"a critical use for someone who treats people as input-output devices and ignores their inner life","definitionCN":"批评性地指把人当输入输出装置、忽略其内在生活的人","example":"The novelist called the administrator a behaviorist who counted smiles.","exampleCN":"小说家把那位管理者称作只会数微笑的行为主义者。","why":"a label born from excluding inner life turns into an insult when applied to someone who ought to care about it.","whyCN":"从排除内在生活诞生的标签，用在理应关心内在生活的人身上时，就变成了侮辱。"}],"etymology":{"intro":{"en":"Behaviorist is behave plus -ist, built on the same stem as behaviorism. The verb is Germanic in origin and the suffix reached English through Latin from Greek. Dates are approximate.","cn":"behaviorist 是 behave 加 -ist，与 behaviorism 同用一个词干。动词源自日耳曼语，后缀则经拉丁语从希腊语进入英语。年代为约数。"},"items":[{"era":"OLD ENGLISH HABBAN","en":"Behave is be- plus have, from Old English habban 'to hold, possess'. The original sense was 'to hold oneself in a certain manner'.","cn":"behave 是 be- 加 have，have 来自古英语 habban「持有、拥有」。原义为「以某种方式自持」。"},{"era":"MIDDLE ENGLISH BEHAVIOUR","en":"The noun behavour named conduct, and the spelling behavior became standard in American English.","cn":"名词 behavour 指举止，拼写 behavior 后来成为美式标准。"},{"era":"AGENT SUFFIX -IST","en":"Greek -istes 'one who practises' became Latin -ista and English -ist, a suffix for persons who follow a practice or doctrine.","cn":"希腊 -istes「从事者」变为拉丁 -ista 与英语 -ist，是标记从事某种实践或信奉某种学说之人的后缀。"},{"era":"COINING IN PSYCHOLOGY","en":"Behaviorist appeared alongside behaviorism in the early twentieth century, when Watson's manifesto gave the school a public name.","cn":"behaviorist 与 behaviorism 在 20 世纪初同时出现，华生的宣言给了这个学派一个公开的名字。"},{"era":"APPLIED BRANCHES","en":"From the mid-twentieth century the title spread to applied behavior analysis, behaviour modification and programmed instruction.","cn":"从 20 世纪中期起，这个头衔扩展到应用行为分析、行为矫正与程序教学。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first use of the title): the noun and the doctrine name appeared close together in print, and the earliest attested use of behaviorist is not settled.","cn":"来源不确定（该头衔的首见）：名词与学说名在印刷品中邻近出现，behaviorist 最早的确切书证没有定论。"}]},"similar":{"note":{"en":"Group one holds the same stem in forms that are constantly swapped; group two holds other practitioners of behavioural work.","cn":"第一组是同词干、最常被张冠李戴的几种形式；第二组是从事行为工作的其他从业者。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"behaviorism","ipa":"/bɪˈheɪvjərɪzəm/","tag":"the doctrine","definition":"The school or doctrine itself; behaviorist is the person or the adjective, so the two name different things.","definitionCN":"指学派或学说本身；behaviorist 指人或形容词，两者命名对象不同。"},{"word":"behavioral","ipa":"/bɪˈheɪvjərəl/","tag":"neutral adjective","definition":"Simply 'relating to behaviour'; it does not commit the writer to the school, unlike the adjective behaviorist.","definitionCN":"只表示「与行为有关的」，不像形容词 behaviorist 那样表明学派立场。"},{"word":"behaviourist","ipa":"/bɪˈheɪvjərɪst/","tag":"British spelling","definition":"The same word in British spelling; the difference is only orthographic.","definitionCN":"同一个词的英式拼写，差别只在正字法。"}]},{"heading":"NEAR MEANING","entries":[{"word":"analyst","ipa":"/ˈænəlɪst/","tag":"narrower job title","definition":"In this context, a practitioner certified in applied behavior analysis; the title is narrower and regulated.","definitionCN":"在此语境中指取得应用行为分析认证的从业者，头衔更窄且受监管。"},{"word":"therapist","ipa":"/ˈθerəpɪst/","tag":"treatment, not doctrine","definition":"One who treats difficulties; a therapist may use behavioural methods without adopting the whole doctrine.","definitionCN":"处理困难的人；治疗师可以使用行为方法，而不必接受整套学说。"},{"word":"experimental psychologist","ipa":"/ɪkˌsperɪˈmentəl saɪˈkɒlədʒɪst/","tag":"method, not school","definition":"A researcher who runs controlled studies; the label names a method, while behaviorist names a theoretical stance.","definitionCN":"做受控研究的人，这个标签命名方法，而 behaviorist 命名理论立场。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real job titles and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实岗位名与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"-ist always marks a person here, so behaviorist is the one who holds or applies the doctrine.","cn":"这里的 -ist 始终标记人，因此 behaviorist 是持有或应用该学说的人。"},{"en":"be- 'about' plus have 'hold': the person studies how people hold themselves.","cn":"be-「围绕」加 have「持有」：这个人研究人如何自持。"},{"en":"The family runs behavior, behavioral, behaviorism, behavioristic, behaviorally.","cn":"同族词包括 behavior、behavioral、behaviorism、behavioristic、behaviorally。"},{"en":"Job phrases pin the role: strict behaviorist, behaviorist approach, behaviorist psychologist.","cn":"岗位搭配钉住角色：严格的行为主义者、行为主义方法、行为主义心理学家。"},{"en":"The contrast to keep in mind is cognitivist, who insists that inner processes be counted.","cn":"要记住的对照是 cognitivist，坚持把内部过程算进来的人。"}],"abstract":[{"en":"Picture a person with a tally sheet and no questionnaire.","cn":"想象一个人只拿计数表，不拿问卷。"},{"en":"Picture someone who answers 'how are you' by counting how often you blink.","cn":"想象有人用数你眨眼的次数来回答「你怎么样」。"},{"en":"Picture a trainer who sees only the pressed key, never the intention behind it.","cn":"想象一位训练者只看见被按下的键，从不看按键背后的意图。"}]},"examples":[{"en":"The behaviorist refused to infer motives from the interview.","cn":"这位行为主义者拒绝从访谈中推断动机。"},{"en":"As a behaviorist, he preferred three clear measures to one long discussion.","cn":"作为行为主义者，他宁可要三项清楚的计量，也不要一场长谈。"},{"en":"The clinic employs a behaviorist to supervise its reward schedules.","cn":"该诊所雇了一位行为分析从业者来监督奖励程式。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"behavior（行为）+ ist（人）＝ 只研究行为的人；记「秒表、计数表、开关，唯独没有问卷」。","word":"behaviorist"},"root":"英语 behave（be- + 古英语 habban「持有」）+ 希腊经拉丁的 -istes／-ista「从事者」；与 behaviorism 同干，20 世纪初在心理学中定型。","sensesIntro":{"en":"Eight senses follow one person: the researcher, the believer, the clinician, the engineer of consequences, the animal trainer, the method adjective, the curriculum designer, and finally the insult.","cn":"八个义项沿着同一个人展开：研究者、信奉者、临床从业者、后果的工程师、动物训练者、方法形容词、课程设计者，最后是那句骂人的话。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person at a bench with a stopwatch and a tally sheet, deliberately without a questionnaire.","cn":"核心意象：一个人守在实验台前，带着秒表与计数表，刻意不带问卷。"},"chain":["DOCTRINE","PERSON","PRACTICE","CONTROL","ANIMAL","LABEL"],"branches":[{"senses":"01","en":"THE RESEARCHER: the title begins as the psychologist who works inside the doctrine.","cn":"研究者：这个头衔最初指在该学说内部工作的心理学家。"},{"senses":"02 · 03","en":"BELIEF AND PRACTICE: a follower may only agree, while an applied analyst must change behaviour.","cn":"信奉与实践：信奉者只需同意，应用分析者则必须改变行为。"},{"senses":"04 · 05","en":"TWO CONTROLS: institutions are engineered through consequences, and animals are trained in the laboratory.","cn":"两种控制：机构通过后果被工程化，动物在实验室里被训练。"},{"senses":"06 · 07","en":"METHOD AND CURRICULUM: the label becomes an adjective, and then a way of arranging instruction.","cn":"方法与课程：标签变成形容词，再变成安排教学的方式。"},{"senses":"08","en":"THE INSULT: a doctrine built by excluding inner life becomes a name for someone who ignores it.","cn":"责骂：一个靠排除内在生活建立的学说，成了忽略内在生活者的名字。"}]},"affixes":{"intro":{"en":"Behaviorist is a Germanic verb stem plus a Greek-derived agent suffix, with no Latin root behind the stem, so most of its structure can be read in English alone.","cn":"behaviorist 是日耳曼语动词词干加希腊来源的施动后缀，词干背后没有拉丁词根，因此其结构大半可以只在英语内部读出。"},"latinIntro":{"en":"Latin contributes only the shape of the suffix: Greek -istes became Latin -ista and then English -ist.","cn":"拉丁语只贡献了后缀的外形：希腊 -istes 变为拉丁 -ista，再变为英语 -ist。"},"items":[{"word":"be-","structure":"be- (Old English prefix, 'around, about')","meaning":"around; about","meaningCN":"围绕；关于","example":"The prefix makes the verb reflexive in sense: to carry oneself.","exampleCN":"这个前缀使动词在语义上回指自身：自持。"},{"word":"habban","structure":"habban (Old English verb, 'to hold, have')","meaning":"to hold; to have","meaningCN":"持有；拥有","example":"It survives as modern have.","exampleCN":"它作为现代 have 留存下来。"},{"word":"behave","structure":"be- + have (English verb)","meaning":"to conduct oneself","meaningCN":"举止；表现","example":"The verb describes conduct others can watch.","exampleCN":"这个动词描述他人能看见的举止。"},{"word":"behavior","structure":"behave + -ior (English noun of state)","meaning":"observable conduct","meaningCN":"可观察的举止","example":"The noun supplies the stem for the whole family.","exampleCN":"这个名词为整个词族提供词干。"},{"word":"behaviorism","structure":"behavior + -ism (doctrine)","meaning":"the doctrine of behaviour","meaningCN":"关于行为的学说","example":"The doctrine name is the base for the person name.","exampleCN":"学说名是人名的构词基础。"},{"word":"behaviorist","structure":"behavior + -ist (agent suffix)","meaning":"one who practises or follows","meaningCN":"从事者或信奉者","example":"The suffix turns a doctrine into a person.","exampleCN":"这个后缀把学说变成人。"},{"word":"behavioristic","structure":"behaviorist + -ic (adjective)","meaning":"of the behaviorist method","meaningCN":"属于行为主义方法的","example":"The adjective marks a style of explanation.","exampleCN":"这个形容词标记一种解释风格。"},{"word":"behavioral","structure":"behavior + -al (adjective)","meaning":"relating to behaviour","meaningCN":"与行为有关的","example":"It is the neutral member of the family.","exampleCN":"它是词族中立场中立的一员。"},{"word":"-ist","structure":"-ista (Latin, from Greek -istes)","meaning":"person who practises","meaningCN":"从事者","example":"It also builds biologist and economist.","exampleCN":"它也构成 biologist 与 economist。"}],"latinEntries":[]}},{"word":"cognitive psychology","ipa_uk":"/ˌkɒɡnɪtɪv saɪˈkɒlədʒi/","ipa_us":"/ˌkɑːɡnɪtɪv saɪˈkɑːlədʒi/","definition_zh":"认知心理学：研究知觉、记忆、注意、语言与推理等心智过程的心理学分支，常以信息加工模型解释心智","definition_en":"the branch of psychology that studies perception, memory, attention, language and reasoning, often modelling the mind as information processing","core_image":"一串字符先落在视网膜上，被切成片段、贴上标签、存进记忆抽屉，最后从口中重新拼成一句话","scene":"一串字符先落在视网膜上，被切成片段、贴上标签、存进记忆抽屉，最后从口中重新拼成一句话。Modern cognitive psychology treats that route as a set of testable stages.","sceneCN":"这里指研究知觉、记忆、语言等心智过程的学科分支（第 1 个义项：认知心理学作为学科）；句意为现代认知心理学把这条路线当作一组可检验的阶段。","pos":[{"tag":"n.","zh":"认知心理学（不可数，学科分支名）"}],"collocations":[{"phrase":"cognitive psychology research","zh":"认知心理学研究"},{"phrase":"a cognitive psychology approach","zh":"认知心理学取向"},{"phrase":"the cognitive psychology of memory","zh":"记忆的认知心理学研究"},{"phrase":"cognitive psychology and education","zh":"认知心理学与教育"},{"phrase":"a course in cognitive psychology","zh":"认知心理学课程"},{"phrase":"cognitive psychology experiments","zh":"认知心理学实验"}],"forms":[{"label":"学科名（不可数）","form":"cognitive psychology"},{"label":"从业者形式","form":"cognitive psychologist"},{"label":"核心形容词","form":"cognitive"},{"label":"核心名词（认知）","form":"cognition"},{"label":"副词","form":"cognitively"}],"derivatives":[{"word":"cognition","pos":"n.","zh":"cognitio + -ion（动作或结果）→ 认知这一过程或其能力"},{"word":"cognitive","pos":"adj.","zh":"cognitus + -ive（具有……性质的）→ 具有认知性质的"},{"word":"cognitively","pos":"adv.","zh":"cognitive + -ly（方式副词）→ 从认知层面"},{"word":"cognitivism","pos":"n.","zh":"cognitive + -ism（学说）→ 以内部表征解释行为的立场"},{"word":"metacognition","pos":"n.","zh":"meta-（超越） + cognition → 对自身认知过程的认知"}],"senses":[{"no":"01","title":"The branch that studies mental processes","titleCN":"研究心智过程的心理学分支","definition":"the branch of psychology that studies perception, attention, memory, language, reasoning and problem solving","definitionCN":"研究知觉、注意、记忆、语言、推理与问题解决的心理学分支","example":"Cognitive psychology asks how a sentence is understood in real time.","exampleCN":"认知心理学追问一句话是如何被实时理解的。","why":"cognitive marks mental processes and psychology marks the discipline, so the phrase names the branch that studies those processes.","whyCN":"cognitive 标记心智过程，psychology 标记学科，短语因此指研究这些过程的分支。"},{"no":"02","title":"The information-processing stance","titleCN":"信息加工的研究取向","definition":"the approach that describes the mind as a system that encodes, stores and retrieves information","definitionCN":"把心智描述为编码、存储与提取信息的系统的取向","example":"The information-processing stance gave memory a measurable architecture.","exampleCN":"信息加工取向给了记忆一个可测量的结构。","why":"the branch needed a model that could be tested stage by stage, and the computer supplied one.","whyCN":"这个分支需要一个能逐阶段检验的模型，计算机提供了这个模型。"},{"no":"03","title":"The study of perception and attention","titleCN":"知觉与注意的研究","definition":"the part of the field that asks how sensory input is selected, grouped and recognised","definitionCN":"研究感官输入如何被选择、分组与识别的那部分","example":"Cognitive psychology showed that attention filters before recognition.","exampleCN":"认知心理学表明注意在识别之前就进行筛选。","why":"before anything can be remembered it must be selected, so perception and attention sit at the entrance of the model.","whyCN":"任何东西在被记住之前必须先被选中，因此知觉与注意位于模型的入口。"},{"no":"04","title":"The study of memory","titleCN":"记忆研究","definition":"the study of encoding, storage, forgetting and retrieval, including working and long-term memory","definitionCN":"研究编码、存储、遗忘与提取，包括工作记忆与长时记忆","example":"Cognitive psychology split working memory into separate stores.","exampleCN":"认知心理学把工作记忆拆成几个独立的存储。","why":"a processing model needs a place to put information, and memory is that place.","whyCN":"加工模型需要一个存放信息的地方，记忆就是那个地方。"},{"no":"05","title":"The study of language processing","titleCN":"语言加工研究","definition":"the study of how sounds, words and sentences are recognised and produced in real time","definitionCN":"研究语音、词与句子如何被实时识别与产出","example":"Cognitive psychology mapped the moment a listener resolves an ambiguous word.","exampleCN":"认知心理学标出了听者解决歧义词的那一刻。","why":"language is the most finely timed mental skill, so it became a test case for the whole model.","whyCN":"语言是时间精度最高的心智技能，因此成为整个模型的试验案例。"},{"no":"06","title":"The study of reasoning and decision","titleCN":"推理与决策研究","definition":"the study of how people draw inferences, weigh options and fall into systematic errors","definitionCN":"研究人如何推断、权衡选项并落入系统性错误","example":"Cognitive psychology documented the bias that survives formal training.","exampleCN":"认知心理学记录了经受正式训练仍存活的偏见。","why":"if perception and memory can be modelled, the same stage logic can be turned toward judgement.","whyCN":"如果知觉与记忆可以被建模，同样的阶段逻辑也能转向判断。"},{"no":"07","title":"Cognitive load and learning design","titleCN":"认知负荷与学习设计","definition":"the application of memory limits to the design of explanations, texts and interfaces for learners","definitionCN":"把记忆容量限制用于学习者所用的讲解、文本与界面设计","example":"Cognitive psychology persuaded the textbook to remove decorative diagrams.","exampleCN":"认知心理学说服教材删掉了装饰性图表。","why":"once working memory has a limit, teaching can be designed to stay under it.","whyCN":"工作记忆一旦有了上限，教学就能被设计得不越过这个上限。"},{"no":"08","title":"Human-computer interaction","titleCN":"人机交互中的应用","definition":"the use of attention, memory and motor limits to evaluate screens, menus and response times","definitionCN":"用注意、记忆与动作限制评估屏幕、菜单与响应时间","example":"Cognitive psychology explained why the third menu level lost every user.","exampleCN":"认知心理学解释了为什么第三层菜单让所有用户迷路。","why":"an interface is a stream of stimuli, so the branch's measurements transfer directly to design.","whyCN":"界面是一串刺激流，因此这个分支的测量可直接转移到设计上。"},{"no":"09","title":"Its place within cognitive science","titleCN":"在认知科学中的位置","definition":"the psychological member of the wider cognitive science group, alongside linguistics, computer science and neuroscience","definitionCN":"更宽的认知科学群体中的心理学成员，与语言学、计算机科学和神经科学并列","example":"Cognitive psychology shares its questions with cognitive science but keeps behaviour as its test.","exampleCN":"认知心理学与认知科学共享问题，但以行为作为检验。","why":"the branch is narrower than the whole field, since it keeps psychology's methods while sharing the field's questions.","whyCN":"这个分支比整个领域窄，因为它保留心理学的方法，却共享领域的问题。"}],"etymology":{"intro":{"en":"Cognitive psychology joins a Latin adjective with a Greek-derived discipline name. Cognitive goes back to Latin cognoscere 'to get to know'; psychology goes back to Greek psykhe and logos. Dates are approximate.","cn":"cognitive psychology 由拉丁形容词与希腊来源的学科名组合而成。cognitive 追溯至拉丁 cognoscere「认识、得知」；psychology 追溯至希腊 psykhe 与 logos。年代为约数。"},"items":[{"era":"LATIN COGNOSCERE","en":"Cognoscere 'to get to know, to recognise' was built from com- 'together, fully' and gnoscere 'to know', a variant of noscere.","cn":"cognoscere「认识、得知」由 com-「共同、彻底」与 gnoscere「知道」构成，gnoscere 是 noscere 的变体。"},{"era":"LATIN COGNITIO","en":"The noun cognitio meant 'a getting to know, knowledge, recognition', and the Late Latin adjective cognitivus meant 'relating to knowledge'.","cn":"名词 cognitio 意为「认识、知识、识别」，晚期拉丁形容词 cognitivus 意为「与知识有关的」。"},{"era":"GREEK PSYKHE AND LOGOS","en":"Psychology joins psykhe 'breath, life, soul' with logos 'account, reason'; -logia named the study of a subject.","cn":"psychology 把 psykhe「气息、生命、灵魂」与 logos「论述、理性」结合起来；-logia 命名对某一主题的研究。"},{"era":"ENGLISH COGNITIVE","en":"Cognitive entered English in the seventeenth century from Latin cognitivus, first as a philosophical word for knowledge and recognition.","cn":"cognitive 在 17 世纪从拉丁 cognitivus 进入英语，最初是哲学术语，指知识与识别。"},{"era":"THE COGNITIVE TURN","en":"From the 1950s and 1960s the phrase cognitive psychology named the approach that studied internal processing with behavioural tests, in reaction against behaviorism.","cn":"从 1950 至 1960 年代起，cognitive psychology 指用行为检验研究内部加工的取向，是对行为主义的反弹。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first use of the exact phrase): the label spread through conferences and textbooks in the 1960s and 1970s, so no single first citation is settled; the link of gnoscere to the Indo-European root for 'know' is a reconstruction.","cn":"来源不确定（确切短语的首见）：这个标签在 1960 至 1970 年代经会议与教科书扩散，没有公认的首次书证；gnoscere 与印欧语「知道」词根的联系属重构。"}]},"similar":{"note":{"en":"Group one holds neighbouring labels built on cognitive that cover different scopes; group two holds disciplines that study the same questions with different tools.","cn":"第一组是同出 cognitive、覆盖范围不同的邻近标签；第二组是用不同工具研究同一批问题的学科。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"cognitive science","ipa":"/ˌkɒɡnɪtɪv ˈsaɪəns/","tag":"wider field","definition":"The interdisciplinary field covering psychology, linguistics, artificial intelligence, philosophy and neuroscience; cognitive psychology is one member.","definitionCN":"覆盖心理学、语言学、人工智能、哲学与神经科学的交叉领域，认知心理学只是其中一员。"},{"word":"cognitive neuroscience","ipa":"/ˌkɒɡnɪtɪv ˌnjʊərəʊˈsaɪəns/","tag":"brain measures","definition":"The study of cognitive processes through brain imaging and physiology rather than through behaviour alone.","definitionCN":"通过脑成像与生理指标而非仅靠行为来研究认知过程。"},{"word":"cognitivism","ipa":"/ˈkɒɡnɪtɪvɪzəm/","tag":"a stance, not a branch","definition":"A theoretical position that explains behaviour through internal representations; it can appear inside several disciplines.","definitionCN":"以内部表征解释行为的理论立场，可以出现在多个学科内部。"}]},{"heading":"NEAR MEANING","entries":[{"word":"neuropsychology","ipa":"/ˌnjʊərəʊsaɪˈkɒlədʒi/","tag":"brain and behaviour","definition":"The study of how brain structure and damage affect behaviour and cognition; it starts from the organ.","definitionCN":"研究脑结构与损伤如何影响行为与认知，出发点是有机体器官。"},{"word":"psycholinguistics","ipa":"/ˌsaɪkəʊlɪŋˈɡwɪstɪks/","tag":"language only","definition":"The study of language as a mental process; it overlaps with cognitive psychology but is confined to language.","definitionCN":"把语言作为心理过程来研究，与认知心理学重叠，但范围限于语言。"},{"word":"information processing","ipa":"/ˌɪnfəˈmeɪʃən ˈprəʊsesɪŋ/","tag":"the model, not the field","definition":"The specific model of encoding, storage and retrieval; it is a framework used by the field rather than the field itself.","definitionCN":"指编码、存储、提取这一具体模型，是领域使用的框架，而非领域本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real model names and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实模型名与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"com- 'fully' plus gnoscere 'know': cognition is a full getting-to-know.","cn":"com-「彻底」加 gnoscere「知道」：认知就是彻底地认识。"},{"en":"The family runs cognition, cognitive, cognitively, cognitivism, metacognition.","cn":"同族词包括 cognition、cognitive、cognitively、cognitivism、metacognition。"},{"en":"The second half is the same psychology seen in clinical and school psychology.","cn":"后半部分就是临床与学校心理学中见到的同一个 psychology。"},{"en":"Fixed phrases mark the field: cognitive psychology of memory, cognitive psychology experiments.","cn":"固定搭配标出领域：记忆的认知心理学、认知心理学实验。"},{"en":"Its rival in the twentieth century was behaviorism, which refused to model the inner stage.","cn":"它在 20 世纪的对手是行为主义，后者拒绝为内部阶段建模。"}],"abstract":[{"en":"Picture a sentence entering the eye and leaving the mouth as a rebuilt copy.","cn":"想象一句话从眼睛进入，又从口中作为重建的副本出来。"},{"en":"Picture a mind drawn as boxes joined by arrows, with a clock beside each arrow.","cn":"想象心智被画成方框与箭头，每个箭头旁都有一只钟。"},{"en":"Picture a drawer labelled 'words' that opens only when the right cue arrives.","cn":"想象一只标着「词」的抽屉，只在正确提示到来时打开。"}]},"examples":[{"en":"Cognitive psychology replaced the black box with a stage model.","cn":"认知心理学用阶段模型取代了黑箱。"},{"en":"Her thesis applied cognitive psychology to menu design.","cn":"她的论文把认知心理学应用于菜单设计。"},{"en":"Cognitive psychology and neuroscience now share most of their methods.","cn":"认知心理学与神经科学如今共享大部分方法。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"cognitive（认知的）+ psychology（心理学）＝ 认知心理学；记「字符进眼、切块贴签、入抽屉、再出口」。","word":"cognitive psychology"},"root":"拉丁 com-「共同、彻底」+ gnoscere「知道」（noscere 的变体）→ cognoscere「认识」，其形容词 cognitivus；加希腊 psykhe「灵魂」+ logos「论述」。短语在 20 世纪中叶定型。","sensesIntro":{"en":"Nine senses follow one stream of information: it enters as sensory input, is selected, stored, retrieved, used in language and judgement, then designed for in classrooms and on screens.","cn":"九个义项沿着同一股信息流展开：它作为感官输入进入，被选择、存储、提取，用于语言与判断，最后在课堂与屏幕上被设计。"},"semanticMap":{"core":{"en":"CORE IMAGE: a string of characters entering the eye, broken into pieces, filed in drawers, and rebuilt into speech.","cn":"核心意象：一串字符进入眼睛，被切成片段、归档进抽屉，再被重建成言语。"},"chain":["INPUT","SELECTION","STORAGE","RETRIEVAL","USE","DESIGN"],"branches":[{"senses":"01","en":"THE FIELD: the phrase names the branch that studies these stages as a whole.","cn":"领域：短语指整体研究这些阶段的学科分支。"},{"senses":"02 · 03","en":"THE MODEL AND THE GATE: information processing supplies the architecture, and attention guards its entrance.","cn":"模型与入口：信息加工提供结构，注意守着入口。"},{"senses":"04 · 05","en":"TWO STORES: memory holds what is kept, and language shows it being taken out and reassembled.","cn":"两个仓库：记忆保存被留下的东西，语言则展示它被取出并重新组装。"},{"senses":"06 · 07","en":"JUDGEMENT AND TEACHING: the same stages explain bias and set the limits for instruction.","cn":"判断与教学：同一套阶段既解释偏见，也为教学设定上限。"},{"senses":"08 · 09","en":"SCREENS AND THE WIDER FIELD: the model moves into interface design and sits beside linguistics and neuroscience.","cn":"屏幕与更宽的领域：模型进入界面设计，并与语言学和神经科学并列。"}]},"affixes":{"intro":{"en":"The phrase combines a Latin-derived adjective with a Greek-derived discipline name, so both a Latin root and a Greek root can be read inside it.","cn":"这个短语由拉丁来源的形容词与希腊来源的学科名组合，因此其中可读出拉丁词根与希腊词根各一。"},"latinIntro":{"en":"Latin cognoscere, cognitio and cognitivus supply the first word; Greek psykhe, logos and -logia supply the second.","cn":"拉丁 cognoscere、cognitio 与 cognitivus 提供第一个词；希腊 psykhe、logos 与 -logia 提供第二个词。"},"items":[{"word":"com-","structure":"com- (Latin prefix, 'together, fully')","meaning":"together; fully","meaningCN":"共同；彻底","example":"The prefix intensifies the act of knowing.","exampleCN":"这个前缀强化「知道」这一动作。"},{"word":"gnoscere","structure":"gnoscere (Latin verb variant of noscere, 'to know')","meaning":"to know; to recognise","meaningCN":"知道；认出","example":"The root also gives notice and notion.","exampleCN":"这个词根还给出 notice 与 notion。"},{"word":"cognoscere","structure":"com- + gnoscere (Latin verb, third conjugation)","meaning":"to get to know, to recognise","meaningCN":"认识；得知；认出","example":"The verb stresses a completed act of knowing.","exampleCN":"这个动词强调认识动作的完成。"},{"word":"cognitio","structure":"cognitio (Latin noun, -tio action suffix)","meaning":"knowledge; recognition","meaningCN":"知识；识别","example":"The noun names both the act and its result.","exampleCN":"这个名词既指动作，也指结果。"},{"word":"cognitivus","structure":"cognitivus (Late Latin adjective)","meaning":"relating to knowledge","meaningCN":"与知识有关的","example":"The adjective reached English as cognitive.","exampleCN":"这个形容词进入英语成为 cognitive。"},{"word":"psykhe","structure":"psykhe (Greek noun, 'breath, life, soul')","meaning":"breath; life; soul","meaningCN":"气息；生命；灵魂","example":"It supplies the first element of psychology.","exampleCN":"它提供 psychology 的第一个成分。"},{"word":"logos","structure":"logos (Greek noun, 'account, reason')","meaning":"account; reason","meaningCN":"论述；理性","example":"It supplies the second element of psychology.","exampleCN":"它提供 psychology 的第二个成分。"},{"word":"-logia","structure":"-logia (Greek suffix, 'study of')","meaning":"the study of","meaningCN":"对……的研究","example":"The suffix appears in biology and geology.","exampleCN":"这个后缀出现在 biology 与 geology 中。"},{"word":"cognitive","structure":"cognitivus + English adjective ending","meaning":"relating to cognition","meaningCN":"与认知有关的","example":"The adjective marks the mental side of the phrase.","exampleCN":"这个形容词标记短语中属于心智的一面。"}],"latinEntries":[{"word":"cognoscere","structure":"cognoscere, cognovi, cognitum (verb, third conjugation)","meaning":"to get to know, recognise, learn","meaningCN":"认识；认出；得知"},{"word":"cognitio","structure":"cognitio, cognitionis (f., third declension)","meaning":"knowledge, recognition","meaningCN":"知识；识别"},{"word":"cognitus","structure":"cognitus, cognita, cognitum (perfect participle)","meaning":"known, recognised","meaningCN":"已知的；被认出的"},{"word":"cognitivus","structure":"cognitivus, cognitiva, cognitivum (Late Latin adjective)","meaning":"relating to knowledge","meaningCN":"与知识有关的"}]}},{"word":"stimulus","ipa_uk":"/ˈstɪmjələs/","ipa_us":"/ˈstɪmjələs/","definition_zh":"刺激；刺激物；激励因素：引起反应或推动行动的外在作用，也指实验或生理学中呈现的刺激信号","definition_en":"an external event or agent that arouses a response or drives action, especially a signal presented in an experiment","core_image":"一根细尖的刺棒轻碰牲畜后腿，动物向前迈步；刺棒本身停在原处，动作由被碰的一方发出","scene":"细尖的刺棒轻碰牲畜后腿，动物立刻向前迈了一步，刺棒却始终停在原处。In the experiment, a brief light flash served as the stimulus that started every trial.","sceneCN":"这里指引起反应的外在作用（第 1 个义项：刺激的一般定义）；句意为实验中一次短暂闪光充当启动每一轮的刺激。","pos":[{"tag":"n.","zh":"刺激；刺激物（可数，复数 stimuli）"},{"tag":"n.","zh":"激励因素；促进因素（抽象用法）"}],"collocations":[{"phrase":"respond to a stimulus","zh":"对刺激作出反应"},{"phrase":"sensory stimulus","zh":"感官刺激"},{"phrase":"an economic stimulus","zh":"经济刺激措施"},{"phrase":"a stimulus to growth","zh":"对增长的刺激"},{"phrase":"present a stimulus","zh":"呈现一个刺激"},{"phrase":"stimulus and response","zh":"刺激与反应"}],"forms":[{"label":"单数","form":"stimulus"},{"label":"复数（拉丁规则变化）","form":"stimuli"},{"label":"动词","form":"stimulate"},{"label":"名词（刺激作用）","form":"stimulation"},{"label":"形容词（刺激性的）","form":"stimulative"},{"label":"名词（刺激物、兴奋剂）","form":"stimulant"}],"derivatives":[{"word":"stimulate","pos":"v.","zh":"stimulus + -ate（动词化）→ 施加刺激，使产生反应"},{"word":"stimulation","pos":"n.","zh":"stimulate + -ion（动作或结果）→ 刺激作用或其过程"},{"word":"stimulative","pos":"adj.","zh":"stimulate + -ive（具有……性质的）→ 具有刺激作用的"},{"word":"stimulant","pos":"n./adj.","zh":"stimulare + -ant（施动者）→ 使人兴奋的物质，语义偏移为「兴奋剂」"},{"word":"stimulator","pos":"n.","zh":"stimulate + -or（施动者或装置）→ 发出刺激的人或装置"}],"senses":[{"no":"01","title":"An external event that arouses a response","titleCN":"引起反应的外在作用","definition":"an event, object or change in the environment that produces a response in a person, animal or system","definitionCN":"在人、动物或系统中引起反应的事件、对象或环境变化","example":"A loud noise is a stimulus that makes the heart rate rise.","exampleCN":"巨响是一种使心率上升的刺激。","why":"Latin stimulus was the goad that made an animal move, so the core is 'something that starts motion in another'.","whyCN":"拉丁 stimulus 是驱赶牲畜前进的刺棒，核心义是「使另一方动起来的东西」。"},{"no":"02","title":"A concrete stimulus object","titleCN":"具体的刺激物","definition":"a particular thing presented to the senses, such as a light, a sound or a touch","definitionCN":"呈现给感官的某一具体之物，如光、声或触碰","example":"The red square was the stimulus; the button press was the response.","exampleCN":"红色方块是刺激物，按键是反应。","why":"the abstract event and the physical thing are the same role seen twice, so the noun covers both.","whyCN":"抽象事件与物理对象是同一角色的两种看法，因此名词兼指两者。"},{"no":"03","title":"A signal in an experiment","titleCN":"实验中的刺激信号","definition":"a controlled cue presented on a schedule so that responses can be timed and counted","definitionCN":"按程序呈现的受控提示，使反应能被计时与计数","example":"Each trial began with a visual stimulus held for half a second.","exampleCN":"每一轮都以一个持续半秒的视觉刺激开始。","why":"a laboratory needs the goad to be exactly repeatable, so stimulus became the word for the timed cue.","whyCN":"实验室需要刺棒能精确重复，于是 stimulus 成了计时提示的词。"},{"no":"04","title":"Sensory input","titleCN":"感官刺激","definition":"light, sound, smell, taste or touch that reaches a sense organ and can be detected","definitionCN":"到达感觉器官并可被察觉的光、声、气味、味道或触感","example":"The retina needs a minimum level of light stimulus to register anything.","exampleCN":"视网膜需要最低限度的光刺激才能记录任何东西。","why":"physiology narrowed the word to whatever the senses can take in, whether or not a person notices.","whyCN":"生理学把这个词收窄到感官能接收的东西，无论人是否注意到。"},{"no":"05","title":"Electrical stimulation of nerves","titleCN":"对神经的电刺激","definition":"a controlled electrical pulse applied to a nerve or muscle to evoke a response","definitionCN":"施加于神经或肌肉以引发反应的受控电脉冲","example":"A brief electrical stimulus made the frog's leg twitch.","exampleCN":"一次短暂的电刺激使蛙腿抽动。","why":"electricity let experimenters apply the goad directly to tissue, and the word followed the method.","whyCN":"电让实验者能把刺棒直接加在组织上，词也跟着方法走。"},{"no":"06","title":"A policy or economic incentive","titleCN":"政策或经济上的刺激措施","definition":"a measure such as spending or a tax cut intended to make an economy or market act","definitionCN":"支出或减税等旨在使经济或市场行动起来的手段","example":"The government offered a stimulus to small builders.","exampleCN":"政府向小型建筑商提供了刺激措施。","why":"the image of prodding an animal transfers easily to prodding an economy into motion.","whyCN":"驱赶动物的形象很容易转移到驱赶经济使其动起来。"},{"no":"07","title":"A spur to action or thought","titleCN":"促使人行动或思考的因素","definition":"something that incites a person or group to act, create or think further","definitionCN":"促使个人或群体行动、创造或进一步思考的东西","example":"The exhibition was the stimulus for a decade of new work.","exampleCN":"这场展览成了此后十年新创作的刺激。","why":"the figurative Latin sense 'that which incites' survived alongside the physical one.","whyCN":"拉丁语中「激起者」的比喻义与物理义一同存活下来。"},{"no":"08","title":"An environmental trigger in biology","titleCN":"生物学中的环境触发因素","definition":"a change such as temperature, light or food that triggers a behavioural or physiological response","definitionCN":"温度、光照或食物等触发行为或生理反应的变化","example":"Shortening days are the stimulus for the birds' migration.","exampleCN":"白昼变短是鸟类迁徙的触发因素。","why":"ecology adopted the word because an organism's action always begins with something outside it.","whyCN":"生态学采用这个词，因为生物的行动总由外部某物开始。"},{"no":"09","title":"A provocation to reflection","titleCN":"引发思考的契机","definition":"a question, image or event that sets off thought without requiring a physical reaction","definitionCN":"引发思考、但不要求身体反应的问题、图像或事件","example":"The teacher used one odd photograph as a stimulus for discussion.","exampleCN":"老师用一张古怪的照片作为讨论的刺激。","why":"when the response is mental rather than muscular, the same word still names what set it going.","whyCN":"当反应是心理的而非肌肉的，同一个词仍指那个让它启动的东西。"}],"etymology":{"intro":{"en":"Stimulus is a Latin noun that English borrowed whole. Its first image is a pointed stick used to prod animals, and the figurative sense of 'incitement' came with it. Dates are approximate.","cn":"stimulus 是英语整体借入的拉丁名词。它最初的形象是驱赶牲畜的尖头棒，「激励、激起」的比喻义也随之而来。年代为约数。"},"items":[{"era":"LATIN STIMULUS","en":"Stimulus meant 'a goad, a prick, a spur', the pointed stick that made a draft animal move forward. The word named the tool, not the animal's reaction.","cn":"stimulus 意为「刺棒、尖刺、马刺」，即使役畜前进的尖头棒。这个词命名工具，而非动物的反应。"},{"era":"LATIN STIMULARE","en":"The verb stimulare meant 'to goad, prick, urge on', and its participle could describe a person driven to act.","cn":"动词 stimulare 意为「驱赶、刺、催促」，其分词可以描述被驱动而行动的人。"},{"era":"FIGURATIVE LATIN","en":"Latin prose already used stimulus for 'that which incites or provokes', so the mental sense is not a modern invention.","cn":"拉丁散文已用 stimulus 指「激起或挑动之物」，因此心理层面的意思并非近代发明。"},{"era":"ENGLISH BORROWING","en":"English took stimulus in the seventeenth century, first in learned prose about bodies, spirits and whatever sets them in motion.","cn":"英语在 17 世纪借入 stimulus，最初用于论身体、精气以及使之运动的因素的学术散文。"},{"era":"PHYSIOLOGY AND PSYCHOLOGY","en":"In the nineteenth century physiology and psychology made stimulus a technical term for input that evokes a response, and the plural stimuli was kept as a Latin plural.","cn":"19 世纪生理学与心理学把 stimulus 变成指「引起反应的输入」的术语，复数 stimuli 则保留拉丁复数形式。"},{"era":"RECONSTRUCTED ROOT","en":"Reconstructed form (deeper root): the connection of the Latin noun to an Indo-European root for 'to prick, goad' is a hypothesis, and every form proposed for that root is a reconstruction; the noun itself and its verb stimulare are documented in Latin.","cn":"重构形式（更深词根）：把这个拉丁名词与印欧语「刺、扎」词根相连只是假说，为该词根提出的形式全是重构；这个名词本身及其动词 stimulare 在拉丁语中有书证。"}]},"similar":{"note":{"en":"Group one holds forms from the same stem that are often confused; group two holds words that also push someone to act but come from different roots.","cn":"第一组是同词干、常被混淆的形式；第二组是同样促使人行动、但词根不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"stimulant","ipa":"/ˈstɪmjələnt/","tag":"a substance, not an input","definition":"A drug or drink that raises activity in the body; it is a substance taken, while a stimulus is an event presented.","definitionCN":"提高身体活动的药物或饮料，是被摄入的物质；stimulus 是被呈现的事件。"},{"word":"stimulate","ipa":"/ˈstɪmjəleɪt/","tag":"the verb","definition":"The action of applying a stimulus; the noun names the cause, the verb names the causing.","definitionCN":"施加刺激的动作；名词指原因，动词指施加。"},{"word":"stimuli","ipa":"/ˈstɪmjəlaɪ/","tag":"the plural","definition":"The Latin plural of stimulus; using it for a single event is a common error.","definitionCN":"stimulus 的拉丁复数；用它指单一事件是常见错误。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cue","ipa":"/kjuː/","tag":"a signal to begin","definition":"A signal that tells someone when or what to do; it is usually intentional, while a stimulus may be merely present.","definitionCN":"告诉人何时或做什么的信号，通常是有意发出的；stimulus 可以只是存在着。"},{"word":"incentive","ipa":"/ɪnˈsentɪv/","tag":"reward-shaped motive","definition":"Something offered to make people want to act, usually a reward; it works through desire, not through direct evocation.","definitionCN":"为让人愿意行动而提供的东西，通常是奖励；它通过欲望起作用，而非直接引发反应。"},{"word":"trigger","ipa":"/ˈtrɪɡə/","tag":"the releasing cause","definition":"The immediate cause that sets off an already prepared response, as a trigger releases a spring.","definitionCN":"引发已准备好之反应的直接原因，如扳机松开弹簧。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real scientific collocations and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实科学搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Picture the goad before the animal moves: the word names the prod, not the step.","cn":"先想象牲畜移动之前的刺棒：这个词命名的是那一下刺，而不是那一步。"},{"en":"The family runs stimulate, stimulation, stimulative, stimulant, stimulator.","cn":"同族词包括 stimulate、stimulation、stimulative、stimulant、stimulator。"},{"en":"Fixed pairs mark the science: stimulus and response, sensory stimulus, present a stimulus.","cn":"固定搭配标出科学用法：刺激与反应、感官刺激、呈现刺激。"},{"en":"The plural is Latin: one stimulus, two stimuli, with the -us changing to -i.","cn":"复数是拉丁式：一个 stimulus，两个 stimuli，-us 变为 -i。"},{"en":"The policy phrase economic stimulus keeps the old image of prodding something into motion.","cn":"政策短语 economic stimulus 保留了「把某物戳动起来」的旧形象。"}],"abstract":[{"en":"Picture a finger tapping a sleeping animal and stepping back.","cn":"想象一根手指轻点睡着的动物，然后退开。"},{"en":"Picture a switch on the outside of a machine, never inside it.","cn":"想象一个装在机器外部的开关，从不在内部。"},{"en":"Picture a spark that lights a fuse and then disappears.","cn":"想象一点火星点燃引线，随后自己消失。"}]},"examples":[{"en":"The same stimulus produced different responses in different subjects.","cn":"同一个刺激在不同受试者身上产生了不同反应。"},{"en":"Without a stimulus, the reflex cannot be observed at all.","cn":"没有刺激，反射根本无法被观察到。"},{"en":"Economists argued about how large the stimulus should be.","cn":"经济学家争论刺激措施应该多大。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"stimulus 原指驱赶牲畜的尖刺棒；记「刺棒不动，被刺的一方动」。","word":"stimulus"},"root":"拉丁 stimulus「刺棒、尖刺、马刺」，动词 stimulare「驱赶、刺、催促」；更早来源不确定，与印欧语「刺、扎」词根的联系仅为假说，所拟形式属重构。","sensesIntro":{"en":"Nine senses follow one goad: it is a physical prod, then a presented object, a timed cue, a sensory input, an electric pulse, a policy measure, a spur to thought, an environmental trigger and a provocation to reflection.","cn":"九个义项沿着同一根刺棒展开：它是物理的刺、被呈现的物件、计时提示、感官输入、电脉冲、政策手段、思考的推动、环境触发因素，最后是引发反思的契机。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pointed stick touching an animal's flank; the stick stays still, the step belongs to the animal.","cn":"核心意象：尖头棒碰到牲畜肋侧；棒子不动，迈出的那一步属于牲畜。"},"chain":["PROD","CONTACT","DETECTION","RESPONSE","CONTROL","INCITEMENT"],"branches":[{"senses":"01","en":"THE CAUSE: one event outside the organism sets a response going.","cn":"原因：有机体之外的某一事件使反应启动。"},{"senses":"02 · 03","en":"THE OBJECT AND THE CUE: the same role can be a physical thing or a timed signal in a trial.","cn":"物件与提示：同一角色可以是一个实物，也可以是实验中计时的信号。"},{"senses":"04 · 05","en":"TWO ENERGIES: light reaching an eye and current reaching a nerve are both input.","cn":"两种能量：到达眼睛的光与到达神经的电流都是输入。"},{"senses":"06 · 07","en":"THE ECONOMY AND THE MIND: a budget measure and a striking image both prod something into motion.","cn":"经济与心智：一项预算措施与一个醒目的图像，都在把某物戳动起来。"},{"senses":"08 · 09","en":"NATURE AND REFLECTION: a change of season triggers migration, and a question triggers thought.","cn":"自然与反思：季节变化触发迁徙，一个问题触发思考。"}]},"affixes":{"intro":{"en":"Stimulus is a Latin noun with a small but productive English family, all built on the same stem with verb, noun and adjective suffixes.","cn":"stimulus 是一个拉丁名词，带有一个小而多产的英语词族，全部由同一词干加动词、名词与形容词后缀构成。"},"latinIntro":{"en":"Latin stimulus and stimulare supply the stem; the suffix -atio later gives stimulation, and -ant gives stimulant.","cn":"拉丁 stimulus 与 stimulare 提供词干；后缀 -atio 后来给出 stimulation，-ant 给出 stimulant。"},"items":[{"word":"stimulus","structure":"stimulus (Latin noun, second declension)","meaning":"goad; prick; spur","meaningCN":"刺棒；尖刺；马刺","example":"The noun named the tool before it named the reaction.","exampleCN":"这个名词先命名工具，后命名反应。"},{"word":"stimulare","structure":"stimulare (Latin verb, first conjugation)","meaning":"to goad; to urge on","meaningCN":"驱赶；催促","example":"The verb turns the stick into an action.","exampleCN":"这个动词把棒子变成动作。"},{"word":"stimulatio","structure":"stimulatio (Late Latin noun, -tio action suffix)","meaning":"a goading; a stimulation","meaningCN":"驱赶；刺激","example":"The action noun supplies the English -tion form.","exampleCN":"这个动作名词提供英语的 -tion 形式。"},{"word":"stimulate","structure":"stimulus + -ate (English verb)","meaning":"to apply a stimulus","meaningCN":"施加刺激","example":"The verb is the everyday member of the family.","exampleCN":"这个动词是词族中最日常的一员。"},{"word":"stimulation","structure":"stimulate + -ion (noun of action)","meaning":"the act or result of stimulating","meaningCN":"刺激的行为或结果","example":"The noun is common in physiology and electronics.","exampleCN":"这个名词常见于生理学与电子学。"},{"word":"stimulative","structure":"stimulate + -ive (adjective)","meaning":"tending to stimulate","meaningCN":"有刺激作用的","example":"The adjective often describes policy.","exampleCN":"这个形容词常描述政策。"},{"word":"stimulant","structure":"stimulare + -ant (agent noun)","meaning":"a substance that stimulates","meaningCN":"起刺激作用的物质","example":"The noun narrowed to drugs and drinks.","exampleCN":"这个名词收窄到药物与饮料。"},{"word":"stimulator","structure":"stimulate + -or (agent or device)","meaning":"one or a device that stimulates","meaningCN":"施加刺激的人或装置","example":"The device sense is common in medicine.","exampleCN":"装置义在医学中常见。"},{"word":"stimuli","structure":"stimulus, stimuli (second declension plural)","meaning":"goads; several stimuli","meaningCN":"多根刺棒；多个刺激","example":"The Latin plural survives in scientific English.","exampleCN":"拉丁复数在科学英语中留存。"}],"latinEntries":[{"word":"stimulus","structure":"stimulus, stimuli (m., second declension)","meaning":"goad, prick, spur","meaningCN":"刺棒；尖刺；马刺"},{"word":"stimulare","structure":"stimulare, stimulavi, stimulatum (verb, first conjugation)","meaning":"to goad, prick, urge on","meaningCN":"驱赶；刺；催促"},{"word":"stimulatio","structure":"stimulatio, stimulationis (f., third declension)","meaning":"a goading, a stimulation","meaningCN":"驱赶；刺激"},{"word":"stimulans","structure":"stimulans, stimulantis (present participle)","meaning":"goading, stimulating","meaningCN":"正在驱赶的；刺激的"}]}},{"word":"stimuli","ipa_uk":"/ˈstɪmjəlaɪ/","ipa_us":"/ˈstɪmjəlaɪ/","definition_zh":"刺激的复数形式：多个刺激或一组刺激系列，用于实验心理学、神经科学与经济刺激措施的复数表达","definition_en":"the plural of stimulus, naming several stimuli or a series of them in experiments, neuroscience and policy","core_image":"实验屏同时亮起三种颜色的方块，每种颜色对应一次不同的按键，记录纸上并排出现三列计数","scene":"屏幕同时亮起三种颜色的方块，每种颜色对应一次不同按键，记录纸上并排列出三列。The task delivered visual and auditory stimuli at fixed intervals.","sceneCN":"这里指同时呈现的多个刺激（第 2 个义项：实验中的多重刺激系列）；句意为任务按固定间隔给出视觉与听觉刺激。","pos":[{"tag":"n.","zh":"刺激的复数（stimulus 的规则复数）"}],"collocations":[{"phrase":"visual and auditory stimuli","zh":"视觉与听觉刺激"},{"phrase":"a series of stimuli","zh":"一系列刺激"},{"phrase":"competing stimuli","zh":"相互竞争的刺激"},{"phrase":"respond to stimuli","zh":"对刺激作出反应"},{"phrase":"external stimuli","zh":"外部刺激"},{"phrase":"paired stimuli","zh":"成对呈现的刺激"}],"forms":[{"label":"单数（原形）","form":"stimulus"},{"label":"复数（拉丁规则变化）","form":"stimuli"},{"label":"英式读音","form":"/ˈstɪmjʊlaɪ/"},{"label":"美式读音","form":"/ˈstɪmjəlaɪ/"},{"label":"动词形式","form":"stimulate"}],"derivatives":[{"word":"stimulus","pos":"n.","zh":"stimuli 的基础词 stimulus + 拉丁第二变格法 -us 变 -i（复数词尾替换）→ 由单数转为复数形式"},{"word":"stimulate","pos":"v.","zh":"stimulus + -ate（动词化）→ 施加刺激"},{"word":"stimulation","pos":"n.","zh":"stimulate + -ion（动作或结果）→ 刺激作用"},{"word":"stimulant","pos":"n.","zh":"stimulare + -ant（施动者）→ 起刺激作用的物质，语义偏移为「兴奋剂」"},{"word":"stimulative","pos":"adj.","zh":"stimulate + -ive（具有……性质的）→ 有刺激作用的"}],"senses":[{"no":"01","title":"The regular plural of stimulus","titleCN":"stimulus 的规则复数形式","definition":"the form used for more than one stimulus, keeping the Latin second-declension pattern -us to -i","definitionCN":"指一个以上刺激时使用的形式，保留拉丁第二变格法 -us 变 -i 的规律","example":"One stimulus was faint, but the paired stimuli were easy to detect.","exampleCN":"单个刺激很微弱，但成对的刺激很容易被察觉。","why":"English borrowed the whole Latin noun and kept its plural, so the form is grammar rather than a new word.","whyCN":"英语整体借入这个拉丁名词并保留其复数，因此这个形式属于语法变化，而非新词。"},{"no":"02","title":"A series of stimuli in an experiment","titleCN":"实验中成系列呈现的多个刺激","definition":"several controlled cues presented in sequence so that responses can be compared across trials","definitionCN":"按顺序呈现的多个受控提示，使各轮反应可以比较","example":"The programme presented stimuli in random order to prevent guessing.","exampleCN":"程序随机呈现刺激，以防受试者猜测。","why":"an experiment rarely uses one cue, so the plural became the normal unit of a trial list.","whyCN":"实验很少只用一个提示，因此复数形式成了试次清单的常规单位。"},{"no":"03","title":"Sensory inputs taken together","titleCN":"被一起接收的多种感官输入","definition":"the combined light, sound, smell, taste and touch reaching the senses at one time","definitionCN":"同一时间到达感官的光、声、气味、味道与触感的总体","example":"The brain must separate relevant stimuli from background noise.","exampleCN":"大脑必须把相关刺激从背景噪声中分出来。","why":"senses never receive one channel at a time, so the plural names the ordinary condition.","whyCN":"感官从不同时只接收一个通道，因此复数命名的才是常态。"},{"no":"04","title":"Multichannel stimulation in neuroscience","titleCN":"神经科学中的多通道刺激","definition":"several electrical or sensory channels activated together in a controlled pattern","definitionCN":"按受控模式同时激活的多个电或感官通道","example":"Electrode arrays delivered stimuli to several sites at once.","exampleCN":"电极阵列同时向多个位点施加刺激。","why":"modern equipment can address many channels, and the Latin plural was already available.","whyCN":"现代设备能同时作用于多个通道，而拉丁复数早已现成。"},{"no":"05","title":"Several policy stimuli","titleCN":"多项经济刺激措施","definition":"more than one measure, such as spending and tax cuts, intended to move an economy","definitionCN":"支出与减税等一项以上的措施，旨在推动经济","example":"The budget combined fiscal and monetary stimuli.","exampleCN":"预算把财政与货币刺激组合起来。","why":"economists treat each measure as a prod, so a package is naturally plural.","whyCN":"经济学家把每项措施当作一次戳动，因此一揽子措施自然用复数。"},{"no":"06","title":"Several spurs to action","titleCN":"多种促使人行动的因素","definition":"multiple things that incite a person or group to act, create or think","definitionCN":"促使个人或群体行动、创造或思考的多个事物","example":"Awards and travel grants were the stimuli behind the new programme.","exampleCN":"奖项与差旅资助是新项目背后的多重推动。","why":"the figurative sense also pluralises, because motives rarely come one at a time.","whyCN":"比喻义同样有复数，因为动机很少一次只来一个。"},{"no":"07","title":"A stimulus array in methods","titleCN":"研究方法术语中的刺激阵列","definition":"a defined set of stimuli treated as one display or one block in a study","definitionCN":"研究中被当作一个显示或一个区组的既定刺激集合","example":"The stimulus array contained forty faces and twenty houses.","exampleCN":"刺激阵列包含四十张面孔与二十座房屋。","why":"method writers needed a name for the whole set, and the plural supplied it.","whyCN":"方法学作者需要给整个集合一个名字，复数形式正好提供。"},{"no":"08","title":"The spelling and pronunciation to watch","titleCN":"复数拼写与读音的用法提醒","definition":"the plural is written stimuli and pronounced with a final long i, never as a singular","definitionCN":"复数写作 stimuli，词尾读长音 i，不可当作单数使用","example":"Writing 'a stimuli' is a common error in student reports.","exampleCN":"在学生的报告里写 a stimuli 是常见错误。","why":"because the Latin ending is unusual, the plural is often mistaken for a singular, which is why the usage point belongs here.","whyCN":"由于这个拉丁词尾不常见，复数常被误当作单数，因此这条用法提醒也应算一个义项。"}],"etymology":{"intro":{"en":"Stimuli is not a separate coinage but the Latin plural of stimulus, kept intact in technical English. Dates are approximate.","cn":"stimuli 不是另造的单词，而是 stimulus 的拉丁复数，在技术英语中整体保留。年代为约数。"},"items":[{"era":"LATIN SECOND DECLENSION","en":"Masculine nouns ending in -us normally take -i in the nominative plural, so stimulus 'goad' becomes stimuli 'goads'.","cn":"以 -us 结尾的阳性名词，主格复数通常把词尾变为 -i，因此 stimulus「刺棒」的复数是 stimuli「多根刺棒」。"},{"era":"LATIN STIMULUS","en":"The singular named a goad or spur, a pointed tool for driving animals, and by extension anything that incites.","cn":"单数指刺棒或马刺，即驱赶牲畜的尖头工具，并引申为任何激起行动之物。"},{"era":"LATIN STIMULARE","en":"The verb stimulare 'to goad, urge on' belongs to the same family and gave English stimulate.","cn":"动词 stimulare「驱赶、催促」属于同一词族，并给出英语 stimulate。"},{"era":"TECHNICAL BORROWING","en":"Scientific English of the seventeenth to nineteenth centuries kept Latin plurals for learned nouns, which is how stimuli survived beside the English word.","cn":"17 至 19 世纪的科学英语为学术名词保留拉丁复数，stimuli 因此与英语词并存。"},{"era":"MODERN SPECIALISED USE","en":"Psychology, physiology and economics made stimuli routine: paired stimuli in a trial list, multichannel stimuli in a laboratory, fiscal stimuli in a budget.","cn":"心理学、生理学与经济学使 stimuli 成为常规用法：试次清单里的成对刺激、实验室里的多通道刺激、预算里的财政刺激。"},{"era":"RECONSTRUCTED ROOT","en":"Reconstructed form (deeper root of the singular): the link to an Indo-European root for 'to prick' is a hypothesis, and every form proposed for that root is a reconstruction; the plural ending itself follows a documented Latin declension.","cn":"重构形式（单数形式的更深词根）：与印欧语「刺、扎」词根的联系只是假说，为该词根提出的形式全是重构；复数词尾本身则遵循有书证的拉丁变格法。"}]},"similar":{"note":{"en":"Group one holds the singular and the near-spellings that are often swapped for the plural; group two holds other plural nouns of input and inducement.","cn":"第一组是单数与常被误换成复数的近形词；第二组是同样表示输入与诱因的其他复数名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"stimulus","ipa":"/ˈstɪmjələs/","tag":"singular, not plural","definition":"The singular form for one cue; using it where several are meant is the commonest error in the pair.","definitionCN":"指单个提示的单数形式；在该用复数处用它，是这一对词里最常见的错误。"},{"word":"stimulant","ipa":"/ˈstɪmjələnt/","tag":"a substance","definition":"A drug or drink that raises bodily activity; it is consumed, while stimuli are presented.","definitionCN":"提高身体活动的药物或饮料，是被摄入的；stimuli 是被呈现的。"},{"word":"stimulate","ipa":"/ˈstɪmjəleɪt/","tag":"the verb","definition":"The verb meaning 'to apply a stimulus'; it cannot stand where a plural noun is required.","definitionCN":"意为「施加刺激」的动词，不能用在需要复数名词的位置。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cues","ipa":"/kjuːz/","tag":"intentional signals","definition":"Signals that tell someone when or what to do; cues are usually deliberate, while stimuli may simply occur.","definitionCN":"告诉人何时或做什么的信号；提示通常是有意的，而刺激可以只是发生。"},{"word":"inputs","ipa":"/ˈɪnpʊts/","tag":"system language","definition":"Whatever enters a system, machine or process; the word is neutral about whether a response follows.","definitionCN":"进入系统、机器或过程的一切；这个词不保证随后会有反应。"},{"word":"incentives","ipa":"/ɪnˈsentɪvz/","tag":"offered rewards","definition":"Rewards offered to make people act; they work through desire rather than through direct evocation.","definitionCN":"为让人行动而提供的奖励，通过欲望起作用，而非直接引发反应。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphology, real experimental collocations and real word relatives, not invented rhymes.","cn":"正常联想：真实的形态变化、真实实验搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"One -us becomes many -i: the ending itself carries the plural.","cn":"一个 -us 变成多个 -i：词尾本身就带着复数信息。"},{"en":"The singular is the goad, and the plural is several goads at once.","cn":"单数是那根刺棒，复数是同时落下的几根。"},{"en":"The family runs stimulus, stimuli, stimulate, stimulation, stimulant.","cn":"同族词包括 stimulus、stimuli、stimulate、stimulation、stimulant。"},{"en":"Fixed phrases mark the laboratory: paired stimuli, competing stimuli, visual and auditory stimuli.","cn":"固定搭配标出实验室用法：成对刺激、相互竞争的刺激、视觉与听觉刺激。"},{"en":"In policy talk the plural is normal: fiscal and monetary stimuli.","cn":"政策话语里复数很常见：财政与货币刺激。"}],"abstract":[{"en":"Picture three coloured squares lighting at once and three columns of tallies appearing.","cn":"想象三个彩色方块同时亮起，三列计数同时出现。"},{"en":"Picture many small taps arriving on one skin at the same moment.","cn":"想象许多轻触在同一刻落到同一块皮肤上。"},{"en":"Picture a single switch multiplied into a panel of switches.","cn":"想象一个开关扩展成一整块开关面板。"}]},"examples":[{"en":"The infants were shown paired stimuli until their gaze shifted.","cn":"研究者给婴儿看成对的刺激，直到他们的注视转移。"},{"en":"Competing stimuli made the task far harder than the pilot study.","cn":"相互竞争的刺激使任务比预试困难得多。"},{"en":"The central bank announced two separate stimuli within one quarter.","cn":"央行在一个季度内宣布了两项独立的刺激措施。"}],"dict_mnemonic":{"note":"形态记忆 · 非词源","text":"stimulus 的复数按拉丁第二变格法变 -us 为 -i；记「一根刺棒，一把刺棒」。","word":"stimuli"},"root":"拉丁 stimulus「刺棒、尖刺」的复数 stimuli；拉丁第二变格法阳性名词 -us 变 -i，英语技术文献整体保留该复数。更早词源不确定，与印欧语「刺、扎」词根的联系仅为假说。","sensesIntro":{"en":"Eight senses follow one plural form: grammar first, then series in experiments, sensory streams, multichannel stimulation, policy packages, several motives, arrays in methods and a usage warning.","cn":"八个义项沿着同一个复数形式展开：先是语法，再是实验中的系列、感官流、多通道刺激、政策组合、多重动机、方法学阵列，最后是一条用法提醒。"},"semanticMap":{"core":{"en":"CORE IMAGE: one goad multiplied into a panel of goads arriving together.","cn":"核心意象：一根刺棒扩展成一整块同时落下的刺棒面板。"},"chain":["SINGULAR","LATIN PLURAL","SERIES","CHANNELS","PACKAGE","ARRAY"],"branches":[{"senses":"01","en":"THE FORM: the plural exists first as Latin grammar, not as a new meaning.","cn":"形式：这个复数首先作为拉丁语法存在，而不是新的意义。"},{"senses":"02 · 03","en":"TRIALS AND SENSES: a list of cues and a stream of sensory input are both plural by nature.","cn":"试次与感官：提示清单与感官输入流在本质上都是复数。"},{"senses":"04 · 07","en":"LABORATORY SETS: multichannel stimulation and a defined stimulus array are the same plural seen as equipment and as method.","cn":"实验室集合：多通道刺激与既定刺激阵列，是同一复数在设备与方法两个层面的表现。"},{"senses":"05 · 06","en":"MEASURES AND MOTIVES: a policy package and several spurs to action both prod more than once.","cn":"措施与动机：一揽子政策与多重推动，都不止戳动一次。"},{"senses":"08","en":"THE WARNING: because the ending is Latin, the plural is often misread as a singular.","cn":"提醒：由于词尾是拉丁式，复数常被误读作单数。"}]},"affixes":{"intro":{"en":"Stimuli has no separate suffixes of its own; it is the plural inflection of stimulus, so the family is read through the singular stem.","cn":"stimuli 本身没有独立后缀，它是 stimulus 的复数屈折形式，因此整个词族要经由单数词干来读。"},"latinIntro":{"en":"Latin stimulus and stimulare supply the stem, and the second-declension ending -i supplies the plural; English then added -ate, -ion, -ive and -ant.","cn":"拉丁 stimulus 与 stimulare 提供词干，第二变格法词尾 -i 提供复数；英语随后加了 -ate、-ion、-ive 与 -ant。"},"items":[{"word":"stimulus","structure":"stimulus (Latin noun, second declension)","meaning":"goad; spur","meaningCN":"刺棒；马刺","example":"The singular is the base of the whole family.","exampleCN":"单数是整个词族的基础。"},{"word":"-i","structure":"-i (Latin second-declension nominative plural ending)","meaning":"plural marker","meaningCN":"复数标记","example":"The ending alone tells a reader that several are meant.","exampleCN":"仅这个词尾就告诉读者所指的是多个。"},{"word":"stimulare","structure":"stimulare (Latin verb, first conjugation)","meaning":"to goad; to urge on","meaningCN":"驱赶；催促","example":"The verb supplies the English verb forms.","exampleCN":"这个动词提供英语的动词形式。"},{"word":"stimulate","structure":"stimulus + -ate (English verb)","meaning":"to apply a stimulus","meaningCN":"施加刺激","example":"The verb is built on the same stem as the plural.","exampleCN":"这个动词与复数形式同干。"},{"word":"stimulation","structure":"stimulate + -ion (action noun)","meaning":"the act of stimulating","meaningCN":"刺激的行为","example":"The noun often names a laboratory procedure.","exampleCN":"这个名词常指一种实验室操作。"},{"word":"stimulant","structure":"stimulare + -ant (agent noun)","meaning":"a stimulating substance","meaningCN":"起刺激作用的物质","example":"The noun narrowed to drugs and drinks.","exampleCN":"这个名词收窄到药物与饮料。"},{"word":"stimulative","structure":"stimulate + -ive (adjective)","meaning":"tending to stimulate","meaningCN":"有刺激作用的","example":"The adjective is frequent in policy writing.","exampleCN":"这个形容词在政策写作中常见。"},{"word":"stimulator","structure":"stimulate + -or (agent or device)","meaning":"one or a device that stimulates","meaningCN":"施加刺激的人或装置","example":"Medical devices often carry this name.","exampleCN":"医疗装置常用这个名称。"},{"word":"stimulatio","structure":"stimulatio (Late Latin action noun)","meaning":"a goading","meaningCN":"驱赶；刺激","example":"The Latin noun is the model for the English action noun.","exampleCN":"这个拉丁名词是英语动作名词的模板。"}],"latinEntries":[{"word":"stimulus","structure":"stimulus, stimuli (m., second declension)","meaning":"goad, prick, spur","meaningCN":"刺棒；尖刺；马刺"},{"word":"stimuli","structure":"stimuli (nominative plural of stimulus)","meaning":"goads, spurs","meaningCN":"多根刺棒；多个马刺"},{"word":"stimulare","structure":"stimulare, stimulavi, stimulatum (verb, first conjugation)","meaning":"to goad, urge on","meaningCN":"驱赶；催促"},{"word":"stimulatio","structure":"stimulatio, stimulationis (f., third declension)","meaning":"a goading, a stimulation","meaningCN":"驱赶；刺激"}]}},{"word":"response","ipa_uk":"/rɪˈspɒns/","ipa_us":"/rɪˈspɑːns/","definition_zh":"回答；反应；响应；回函；应和：对言语、刺激、事件或系统输入作出的答复或输出","definition_en":"an answer or reaction to a question, stimulus, event or system input, whether spoken, bodily, written or mechanical","core_image":"门铃响了一声，屋里的人放下杯子走到门口，铃声与开门之间隔着短短几秒","scene":"门铃只响了一声，屋里的人放下杯子走到门口，中间隔了几秒。Her response came faster when the bell was rung twice.","sceneCN":"这里指对某一信号作出的行为反应（第 2 个义项：对刺激的生理或行为反应）；句意为门铃响两次时，她的反应来得更快。","pos":[{"tag":"n.","zh":"回答；答复（可数）"},{"tag":"n.","zh":"反应；响应（对刺激或输入）"},{"tag":"n.","zh":"回函；应和（正式或礼仪用法）"}],"collocations":[{"phrase":"in response to","zh":"作为对……的回应"},{"phrase":"a quick response","zh":"迅速的反应"},{"phrase":"response time","zh":"响应时间"},{"phrase":"an immune response","zh":"免疫反应"},{"phrase":"response rate","zh":"应答率"},{"phrase":"a written response","zh":"书面答复"}],"forms":[{"label":"单数","form":"response"},{"label":"复数","form":"responses"},{"label":"动词","form":"respond"},{"label":"形容词（有回应的）","form":"responsive"},{"label":"名词（应答者）","form":"respondent"}],"derivatives":[{"word":"respond","pos":"v.","zh":"respondere 去词尾 → 作出回答或反应"},{"word":"responsive","pos":"adj.","zh":"response + -ive（具有……性质的）→ 反应迅速的；有回应的"},{"word":"respondent","pos":"n.","zh":"respond + -ent（施动者）→ 回答者，语义偏移为「调查受访者、被告」"},{"word":"responsiveness","pos":"n.","zh":"responsive + -ness（性质名词）→ 反应灵敏的程度"},{"word":"responsory","pos":"n.","zh":"response + -ory（礼拜用语）→ 礼拜中轮流应和的短诗"}],"senses":[{"no":"01","title":"A spoken or written answer","titleCN":"口头或书面的回答","definition":"an answer given to a question, letter, request or accusation","definitionCN":"对问题、来信、请求或指责给出的答复","example":"His response to the question was a long silence.","exampleCN":"他对这个问题的回答是一段长久的沉默。","why":"Latin respondere meant 'to promise back', so an answer is literally something returned to the speaker.","whyCN":"拉丁 respondere 意为「回以承诺」，因此回答字面上就是还给说话者的东西。"},{"no":"02","title":"A bodily reaction to a stimulus","titleCN":"身体对刺激的反应","definition":"a physiological or behavioural change produced by a stimulus, such as a reflex, an allergy or a movement","definitionCN":"由刺激引起的生理或行为变化，如反射、过敏或动作","example":"The pupil's response to light was slow but present.","exampleCN":"瞳孔对光的反应虽慢但存在。","why":"physiology borrowed the word because a body also returns something to what touched it.","whyCN":"生理学借用这个词，因为身体也会对触碰它的东西给出回返。"},{"no":"03","title":"The output of a system","titleCN":"系统或装置的输出响应","definition":"the output produced by a device or program after receiving an input or signal","definitionCN":"装置或程序在收到输入或信号后产生的输出","example":"The microphone's response was flat across the whole range.","exampleCN":"这只麦克风的响应在整个频段内是平坦的。","why":"engineering kept the same structure of input and return, with a machine as the one that answers.","whyCN":"工程学保留同样的「输入—回返」结构，只是作出回答的换成了机器。"},{"no":"04","title":"Public or market reaction","titleCN":"公众或市场的反响","definition":"the collective reaction of audiences, customers or voters to an event or product","definitionCN":"受众、顾客或选民对事件或产品的集体反应","example":"The film's response in the provinces was warmer than in the capital.","exampleCN":"这部电影在外省的反响比在首都更热烈。","why":"a public also answers, even when nobody asks it a direct question.","whyCN":"公众同样在作答，即使没有人直接提问。"},{"no":"05","title":"A formal written reply","titleCN":"正式的书面回函","definition":"an official written answer to a complaint, application or consultation","definitionCN":"对投诉、申请或咨询的正式书面答复","example":"The ministry's response arrived three months after the petition.","exampleCN":"请愿书提交三个月后，该部的回函才到。","why":"institutions needed a countable document, so the abstract answer became a piece of paper.","whyCN":"机构需要一份可计数的文件，抽象的回答因此变成一张纸。"},{"no":"06","title":"A courtesy reply to an invitation","titleCN":"对邀请或问候的礼仪性应答","definition":"a polite reply indicating whether one will attend or how one receives a greeting","definitionCN":"礼貌地说明是否出席，或如何回应问候的答复","example":"Her response to the invitation came by post.","exampleCN":"她对邀请的答复是寄来的。","why":"social ritual requires an answer even when the content is only yes or no.","whyCN":"社交礼俗要求一个回答，即使内容只有「是」或「否」。"},{"no":"07","title":"A versicle answered in worship","titleCN":"礼拜中轮流应和的短句","definition":"a short sentence said or sung by the congregation in answer to the officiant","definitionCN":"会众回应主礼者而念或唱的短句","example":"The choir's response filled the small chapel.","exampleCN":"唱诗班的应和声充满这座小教堂。","why":"liturgy is built on call and answer, and the answering half is called the response.","whyCN":"礼仪建立在呼与应之上，应的那一半就叫 response。"},{"no":"08","title":"A dose-response relation","titleCN":"剂量与反应的关系","definition":"the measured relation between the size of a dose and the strength of the effect it produces","definitionCN":"剂量大小与其产生的效应强度之间的测量关系","example":"The study plotted the response against four dose levels.","exampleCN":"该研究把反应对四个剂量水平作图。","why":"pharmacology needed a word for the effect side of an experiment, and response was the natural half of the pair.","whyCN":"药理学需要给实验中效应一侧一个词，response 是这一对里自然的那一半。"},{"no":"09","title":"An answering phrase in music","titleCN":"音乐中的对答乐句","definition":"a phrase that answers an opening phrase, completing a call-and-response pattern","definitionCN":"回应开头乐句的句子，完成呼—应结构","example":"The second violin carried the response to the opening call.","exampleCN":"第二小提琴承担对开头呼唤的应答。","why":"music uses the same call-and-answer shape, so the word crosses from speech into sound.","whyCN":"音乐使用同样的呼—应形状，这个词因此从言语跨进声音。"}],"etymology":{"intro":{"en":"Response comes from Latin responsum 'an answer', the noun of respondere 'to answer, promise in return', built on re- 'back' and spondere 'to pledge'. Dates are approximate.","cn":"response 来自拉丁 responsum「回答」，是动词 respondere「回答、回以承诺」的名词，由 re-「回」与 spondere「郑重承诺」构成。年代为约数。"},"items":[{"era":"LATIN SPONDERE","en":"Spondere meant 'to promise solemnly, to pledge', especially in a contract or a vow. Its family includes sponsio 'a pledge' and sponsor 'a surety'.","cn":"spondere 意为「郑重承诺、立誓」，尤其用于契约或誓愿。同族包括 sponsio「承诺」与 sponsor「担保人」。"},{"era":"LATIN RESPONDERE","en":"Re- 'back' plus spondere gave respondere 'to promise in return, to answer'. The answer is conceived as something given back.","cn":"re-「回」加 spondere 构成 respondere「回以承诺、回答」。回答被设想为还回去的东西。"},{"era":"LATIN RESPONSUM","en":"The neuter past participle responsum was used as a noun meaning 'an answer', and this is the direct source of the English noun.","cn":"中性过去分词 responsum 被当作名词使用，意为「回答」，这就是英语名词的直接来源。"},{"era":"OLD FRENCH AND ENGLISH","en":"Old French response carried the noun into English in the thirteenth century, first for a spoken or written answer.","cn":"古法语 response 在 13 世纪把这个名词带入英语，最初指口头或书面的回答。"},{"era":"TECHNICAL EXTENSIONS","en":"From the nineteenth century physiology, engineering and statistics extended response to bodily reactions, machine outputs and measured dose-response relations.","cn":"从 19 世纪起，生理学、工程学与统计学把 response 扩展到身体反应、机器输出与可测量的剂量—反应关系。"},{"era":"GENERAL BELIEF","en":"Generally thought (pre-Latin origin): spondere is generally thought to be linked to Greek spendein 'to pour a libation', since a pledge was accompanied by an offering, but the connecting forms are reconstructions, so no single pre-Latin source is claimed.","cn":"一般认为（拉丁语之前的来源）：一般认为 spondere 与希腊 spendein「奠酒」有关，因为立誓常伴随献祭，但连接形式属重构，因此不主张某一个确定的拉丁语之前来源。"}]},"similar":{"note":{"en":"Group one holds forms from the same respond stem that are often confused; group two holds words for other kinds of return to an event.","cn":"第一组是同出 respond 词干、常被混淆的形式；第二组是对事件作出其他种类回返的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"respond","ipa":"/rɪˈspɒnd/","tag":"the verb","definition":"The verb meaning 'to answer or react'; response is the noun, so the two occupy different slots in a sentence.","definitionCN":"意为「回答或反应」的动词；response 是名词，两者在句中占不同位置。"},{"word":"responsive","ipa":"/rɪˈspɒnsɪv/","tag":"adjective of readiness","definition":"An adjective meaning 'quick to react' or 'designed to react'; it describes a quality, not an answer.","definitionCN":"形容词，意为「反应迅速」或「设计成能作出反应的」，描述性质，而非一次答复。"},{"word":"responsibility","ipa":"/rɪˌspɒnsəˈbɪləti/","tag":"same stem, other field","definition":"A duty one is answerable for; its link to response is historical, but it names obligation rather than reply.","definitionCN":"指人须为之负责的义务；与 response 的联系是历史的，但它命名义务而非答复。"}]},{"heading":"NEAR MEANING","entries":[{"word":"reaction","ipa":"/riˈækʃən/","tag":"force returned","definition":"A reaction stresses something coming back against what acted, often with force or feeling; a response may be neutral or planned.","definitionCN":"reaction 强调有东西反作用于施动者，常带力量或情绪；response 可以是中性的或有计划的。"},{"word":"reply","ipa":"/rɪˈplaɪ/","tag":"verbal only","definition":"A verbal or written answer to a person; it does not cover reflexes, machine outputs or public moods.","definitionCN":"对人作出的口头或书面回答，不覆盖反射、机器输出或公众情绪。"},{"word":"feedback","ipa":"/ˈfiːdbæk/","tag":"information returned","definition":"Information about the result of an action, returned to adjust the next action; it is content, not a single answer.","definitionCN":"关于行动结果的信息，被回送以调整下一次行动；它是内容，而非一次答复。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real technical collocations and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实技术搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"re- 'back' plus spondere 'pledge': an answer is a pledge given back.","cn":"re-「回」加 spondere「承诺」：回答就是还回去的承诺。"},{"en":"The family runs respond, response, responsive, respondent, responsiveness.","cn":"同族词包括 respond、response、responsive、respondent、responsiveness。"},{"en":"Fixed pairs mark the laboratory: stimulus and response, response time, response rate.","cn":"固定搭配标出实验室用法：刺激与反应、响应时间、应答率。"},{"en":"The prepositional frame is fixed: in response to.","cn":"介词框架是固定的：in response to。"},{"en":"Medicine adds immune response, and pharmacology adds dose-response.","cn":"医学加上免疫反应，药理学加上剂量—反应关系。"}],"abstract":[{"en":"Picture a bell, a cup set down, and a few seconds in between.","cn":"想象一声铃、一只放下的杯子，以及中间那几秒。"},{"en":"Picture a letter sent back with the same envelope.","cn":"想象一封信用同一个信封寄回。"},{"en":"Picture a call and an answer split between two singers.","cn":"想象一句呼唤与一句应答分在两位歌者之间。"}]},"examples":[{"en":"In response to the outage, the company published a short statement.","cn":"针对这次断服，公司发布了一份简短声明。"},{"en":"The immune response began within hours of the injection.","cn":"免疫反应在注射后数小时内开始。"},{"en":"A low response rate weakened the survey's conclusions.","cn":"较低的应答率削弱了调查的结论。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"re（回）+ sponse（承诺）＝ 回以承诺，即回答、反应；记「铃响—放杯—开门」。","word":"response"},"root":"拉丁 re-「回」+ spondere「郑重承诺」→ respondere「回以承诺、回答」，其名词 responsum「回答」。spondere 与希腊 spendein「奠酒」的联系为一般假说，更早形式属重构。","sensesIntro":{"en":"Nine senses follow one return: a word comes back, a body answers a stimulus, a machine answers an input, a public answers an event, and worship and music turn the return into a shared form.","cn":"九个义项沿着同一次回返展开：一句话被还回来，身体回应刺激，机器回应输入，公众回应事件，礼拜与音乐则把这次回返变成共同的形式。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bell rings, a cup is set down, and within seconds a person reaches the door.","cn":"核心意象：门铃响起，杯子被放下，几秒之内有人走到门口。"},"chain":["CALL","RECEIPT","RETURN","FORM","RECORD","SHARED PATTERN"],"branches":[{"senses":"01","en":"THE ANSWER: the core case is a word returned to the person who asked.","cn":"回答：核心情形是还给提问者的一句话。"},{"senses":"02 · 03","en":"BODY AND MACHINE: both a reflex and a device output return something to an input.","cn":"身体与机器：反射与装置输出都对输入给出回返。"},{"senses":"04 · 05","en":"THE PUBLIC AND THE FILE: a crowd answers an event, and an institution answers on paper.","cn":"公众与文件：人群对事件作答，机构则用纸面作答。"},{"senses":"06 · 07","en":"RITUAL: an invitation and a liturgy both require a second voice.","cn":"礼俗：邀请与礼仪都要求有第二个声音。"},{"senses":"08 · 09","en":"MEASURED AND SUNG: dose-response plots the return as a curve, and music splits it between two parts.","cn":"测量与歌唱：剂量—反应把回返画成曲线，音乐则把它分给两个声部。"}]},"affixes":{"intro":{"en":"Response is a Latin noun made of a prefix, a verb root and a participial ending, and the same parts build a productive English family.","cn":"response 是由前缀、动词词根与分词词尾构成的拉丁名词，这些部分还构成一个多产的英语词族。"},"latinIntro":{"en":"Latin re- 'back' and spondere 'to pledge' build respondere, whose participle responsum gives English response; sponsio and sponsor belong to the same root.","cn":"拉丁 re-「回」与 spondere「承诺」构成 respondere，其分词 responsum 给出英语 response；sponsio 与 sponsor 同出这个词根。"},"items":[{"word":"re-","structure":"re- (Latin prefix, 'back, again')","meaning":"back; again","meaningCN":"回；再次","example":"The prefix makes the promise return to its source.","exampleCN":"这个前缀使承诺回到它的来源。"},{"word":"spondere","structure":"spondere, spopondi, sponsum (Latin verb, second conjugation)","meaning":"to promise solemnly; to pledge","meaningCN":"郑重承诺；立誓","example":"The root supplies sponsor and spouse as well.","exampleCN":"这个词根还给出 sponsor 与 spouse。"},{"word":"respondere","structure":"re- + spondere (Latin verb)","meaning":"to answer; to promise in return","meaningCN":"回答；回以承诺","example":"The verb is the direct parent of the English verb.","exampleCN":"这个动词是英语动词的直接母体。"},{"word":"responsum","structure":"responsum (Latin neuter past participle used as noun)","meaning":"an answer","meaningCN":"回答","example":"The participle became the noun with no added suffix.","exampleCN":"这个分词不加后缀就变成了名词。"},{"word":"response","structure":"response (English noun from Old French)","meaning":"an answer or reaction","meaningCN":"回答或反应","example":"The noun widened from speech to bodies and machines.","exampleCN":"这个名词从言语扩展到身体与机器。"},{"word":"respond","structure":"respond (English verb)","meaning":"to answer or react","meaningCN":"回答；作出反应","example":"The verb keeps the Latin stress on the second syllable.","exampleCN":"这个动词保留拉丁语重音在第二音节。"},{"word":"responsive","structure":"response + -ive (adjective)","meaning":"quick to react","meaningCN":"反应迅速的","example":"The suffix turns an answer into a readiness.","exampleCN":"这个后缀把一次回答变成一种敏捷。"},{"word":"respondent","structure":"respond + -ent (agent noun)","meaning":"one who answers","meaningCN":"回答者","example":"The noun narrowed to surveys and law.","exampleCN":"这个名词收窄到调查与法律。"},{"word":"responsory","structure":"response + -ory (noun of ritual)","meaning":"an answering verse in worship","meaningCN":"礼拜中的应和短诗","example":"The suffix marks a fixed liturgical item.","exampleCN":"这个后缀标记一项固定的礼仪项目。"}],"latinEntries":[{"word":"spondere","structure":"spondere, spopondi, sponsum (verb, second conjugation)","meaning":"to promise solemnly, pledge","meaningCN":"郑重承诺；立誓"},{"word":"respondere","structure":"respondere, respondi, responsum (verb, third conjugation)","meaning":"to answer, promise in return","meaningCN":"回答；回以承诺"},{"word":"responsum","structure":"responsum, responsi (n., second declension)","meaning":"an answer","meaningCN":"回答"},{"word":"sponsio","structure":"sponsio, sponsionis (f., third declension)","meaning":"a pledge, a promise","meaningCN":"承诺；誓约"}]}},{"word":"reaction","ipa_uk":"/riˈækʃən/","ipa_us":"/riˈækʃən/","definition_zh":"反应；反作用；化学反应；核反应；反动：对事件、刺激或输入作出的回应，也指物理、化学与政治中的相互作用","definition_en":"a response to an event or stimulus, or an interaction in physics, chemistry and politics in which something acts back","core_image":"两管无色液体倒进同一只烧杯，液面立刻翻起白沫并升温，杯壁摸上去发烫","scene":"两管无色液体倒进同一只烧杯，液面立刻翻起白沫，杯壁摸上去发烫。The reaction released heat so quickly that the glass had to be cooled in water.","sceneCN":"这里指化学物质之间的相互作用（第 3 个义项：化学反应）；句意为该反应放热太快，玻璃杯必须放进水里冷却。","pos":[{"tag":"n.","zh":"反应；回应（可数）"},{"tag":"n.","zh":"反作用；化学反应；核反应"}],"collocations":[{"phrase":"a chemical reaction","zh":"化学反应"},{"phrase":"an allergic reaction","zh":"过敏反应"},{"phrase":"reaction time","zh":"反应时间"},{"phrase":"a chain reaction","zh":"连锁反应"},{"phrase":"public reaction","zh":"公众反应"},{"phrase":"cause a reaction","zh":"引起反应"}],"forms":[{"label":"单数","form":"reaction"},{"label":"复数","form":"reactions"},{"label":"动词","form":"react"},{"label":"形容词（反动的）","form":"reactionary"},{"label":"名词（反应堆）","form":"reactor"}],"derivatives":[{"word":"react","pos":"v.","zh":"re- + act（行动）→ 反过来行动，即作出反应"},{"word":"reactive","pos":"adj.","zh":"react + -ive（具有……性质的）→ 容易起反应的；反应性的"},{"word":"reactor","pos":"n.","zh":"react + -or（施动者或装置）→ 发生反应的反应堆"},{"word":"reactionary","pos":"adj./n.","zh":"reaction + -ary（属于……的）→ 反对变革的，语义偏移为「反动派」"},{"word":"reactivity","pos":"n.","zh":"reactive + -ity（性质名词）→ 反应性；活泼程度"}],"senses":[{"no":"01","title":"A personal response to an event","titleCN":"人对事件的回应","definition":"what a person feels, says or does in answer to an event or piece of news","definitionCN":"一个人对事件或消息在情绪、言语或行动上的回应","example":"Her first reaction was to laugh at the absurdity of it.","exampleCN":"她的第一反应是为这件事的荒唐发笑。","why":"re- 'back' plus actio 'action' gives 'acting back', so the core is a move returned to something that moved first.","whyCN":"re-「回」加 actio「行动」构成「反着行动」，核心就是回给先动之物的一个动作。"},{"no":"02","title":"A physiological reaction","titleCN":"生理反应","definition":"a bodily change such as inflammation, swelling or shock produced by a substance or event","definitionCN":"由某种物质或事件引起的发炎、肿胀或休克等身体变化","example":"The bee sting produced a violent allergic reaction.","exampleCN":"蜂蜇引起了剧烈的过敏反应。","why":"the body acts back against what entered it, and medicine adopted the word for that return.","whyCN":"身体对进入之物作出反作用，医学便用这个词指那种回返。"},{"no":"03","title":"A chemical reaction","titleCN":"化学反应","definition":"a process in which substances interact to form new substances, often releasing or absorbing heat","definitionCN":"物质相互作用生成新物质的过程，常放热或吸热","example":"The reaction turned the clear liquid cloudy within seconds.","exampleCN":"这个反应在几秒内使澄清液体变浑浊。","why":"chemistry took the word because two substances act back on each other, and the result is something new.","whyCN":"化学采用这个词，因为两种物质彼此反作用，结果产生新东西。"},{"no":"04","title":"A nuclear reaction","titleCN":"核反应","definition":"a process in which atomic nuclei change, releasing energy or producing new elements","definitionCN":"原子核发生变化、释放能量或产生新元素的过程","example":"The reactor sustains a controlled nuclear reaction.","exampleCN":"反应堆维持受控的核反应。","why":"the same pattern of interacting parts applies at the scale of the nucleus, so no new word was needed.","whyCN":"同样的相互作用模式适用于原子核尺度，因此不需要新词。"},{"no":"05","title":"A physical reaction force","titleCN":"物理上的反作用力","definition":"the force that a body exerts back on whatever pushes or pulls it","definitionCN":"物体对推拉它的东西施加回去的力","example":"The wall's reaction balanced the push of the beam.","exampleCN":"墙的反作用力平衡了梁的推力。","why":"mechanics formalised the oldest sense: every action has a return.","whyCN":"力学把最古老的意思形式化：每一个作用都有一个回返。"},{"no":"06","title":"Political reaction","titleCN":"政治上的反动与反弹","definition":"a movement that seeks to reverse reforms and restore an earlier order","definitionCN":"试图逆转改革、恢复旧秩序的运动","example":"The reaction after the reforms swept the assembly.","exampleCN":"改革之后的反弹席卷了议会。","why":"politics borrowed the word for forces acting back against change, and it acquired a negative charge.","whyCN":"政治借用这个词指反作用于变革的力量，并带上了负面色彩。"},{"no":"07","title":"An unthinking first reaction","titleCN":"不假思索的本能反应","definition":"an immediate response made before reflection, often emotional or reflex-like","definitionCN":"在思考之前作出的即时回应，常带情绪或近似反射","example":"My reaction was to step back before I saw the car.","exampleCN":"我看见车之前就已经后退了。","why":"if an action returns before thought arrives, it is still a reaction, only a faster one.","whyCN":"如果动作在思考到达之前就回返，它仍是反应，只是更快。"},{"no":"08","title":"A market reaction","titleCN":"市场反应","definition":"the movement of prices, demand or confidence after news or a policy change","definitionCN":"消息或政策变化之后价格、需求或信心的变动","example":"The market's reaction to the announcement was mild.","exampleCN":"市场对这项公告的反应很温和。","why":"traders act back to news in measurable prices, so the word fits without metaphor.","whyCN":"交易者以可测量的价格对消息作出反作用，这个词无需比喻就适用。"},{"no":"09","title":"An emotional reaction","titleCN":"情绪反应","definition":"a feeling such as fear, anger or delight aroused by an event","definitionCN":"由事件唤起的恐惧、愤怒或喜悦等感受","example":"His reaction to the criticism was anger rather than shame.","exampleCN":"他对批评的反应是愤怒，而不是羞愧。","why":"feelings are the inward half of acting back, and the word covers them as readily as visible acts.","whyCN":"感受是反作用的内在那一半，这个词同样覆盖它们。"}],"etymology":{"intro":{"en":"Reaction joins Latin re- 'back' with actio 'action', from agere 'to do, drive'. English took the noun mainly through French. Dates are approximate.","cn":"reaction 把拉丁 re-「回」与 actio「行动」结合起来，actio 出自动词 agere「做、驱动」。英语主要通过法语借入这个名词。年代为约数。"},"items":[{"era":"LATIN AGERE","en":"Agere meant 'to do, drive, set in motion'. Its participle actus and noun actio supplied the idea of a deed or an action.","cn":"agere 意为「做、驱动、使运动」。其分词 actus 与名词 actio 提供了「行为、行动」的概念。"},{"era":"LATIN RE-","en":"The prefix re- meant 'back, again', so a compound with re- describes motion returned toward its source.","cn":"前缀 re- 意为「回、再次」，因此带 re- 的复合词描述朝来源返回的运动。"},{"era":"FRENCH RÉACTION","en":"French réaction named a return movement in physics and, from the late eighteenth century, a political force acting against revolution.","cn":"法语 réaction 指物理上的回返运动，并从 18 世纪末起指反作用于革命的政治力量。"},{"era":"ENGLISH REACTION","en":"English reaction appeared in the seventeenth century for action returned against action, and the political sense arrived with news of the French Revolution.","cn":"英语 reaction 在 17 世纪出现，指反作用于行动的行动；政治义随法国大革命的新闻一同到来。"},{"era":"SCIENTIFIC SPECIALISATION","en":"Chemistry adopted reaction for interacting substances in the late eighteenth century, and nuclear and allergic reactions followed in the twentieth.","cn":"化学在 18 世纪晚期用 reaction 指相互作用的物质，核反应与过敏反应则在 20 世纪跟进。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first Latin record of reactio): the Latin noun is rare and its earliest attestation is disputed, so the English word is better described as coming through French; its first date here is approximate.","cn":"来源不确定（reactio 的拉丁首见）：这个拉丁名词罕见，其最早书证有争议，因此英语词更宜说成经法语而来；此处年代为约数。"}]},"similar":{"note":{"en":"Group one holds forms from the same react stem that are often misused; group two holds words for other kinds of answer, each with a different pressure.","cn":"第一组是同出 react 词干、常被误用的形式；第二组是其他种类的回应，各自带有不同的力度。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"response","ipa":"/rɪˈspɒns/","tag":"answer, often planned","definition":"A response can be deliberate, spoken or written; a reaction is typically the return that the first event forces out.","definitionCN":"response 可以是有意的、口头的或书面的；reaction 通常是第一个事件逼出来的回返。"},{"word":"reactionary","ipa":"/riˈækʃənəri/","tag":"political adjective","definition":"An adjective or noun for a person who wants to undo reform; it is a political label, not a physical process.","definitionCN":"指想要撤销改革的形容词或人，是政治标签，而非物理过程。"},{"word":"reactor","ipa":"/riˈæktə/","tag":"the apparatus","definition":"The vessel or machine in which a reaction is produced; it names equipment, while reaction names the process.","definitionCN":"产生反应的容器或机器，命名设备，而 reaction 命名过程。"}]},{"heading":"NEAR MEANING","entries":[{"word":"reflex","ipa":"/ˈriːfleks/","tag":"wired-in","definition":"An automatic nervous response that needs no learning; a reaction may be learned, chosen or emotional.","definitionCN":"无需学习的自动神经反应；reaction 可以是习得的、选择的或情绪的。"},{"word":"backlash","ipa":"/ˈbæklæʃ/","tag":"hostile rebound","definition":"A strong negative reaction from a group against a change; it always carries hostility.","definitionCN":"群体对变革的强烈负面反弹，总带敌意。"},{"word":"feedback","ipa":"/ˈfiːdbæk/","tag":"information loop","definition":"Information returned to adjust a process; it is a signal about results, not an emotional or chemical answer.","definitionCN":"回送以调整过程的信息，是关于结果的信号，而非情绪或化学回应。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real scientific collocations and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实科学搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"re- 'back' plus agere 'do': to react is to do something back.","cn":"re-「回」加 agere「做」：反应就是回着做一件事。"},{"en":"The family runs react, reaction, reactive, reactor, reactivity, reactionary.","cn":"同族词包括 react、reaction、reactive、reactor、reactivity、reactionary。"},{"en":"Fixed phrases mark the laboratory: chemical reaction, chain reaction, reaction time.","cn":"固定搭配标出实验室用法：化学反应、连锁反应、反应时间。"},{"en":"Medicine adds allergic reaction, and politics adds reaction against reform.","cn":"医学加上过敏反应，政治加上对改革的反弹。"},{"en":"The physical frame is action and reaction, equal and opposite.","cn":"物理框架是作用与反作用，大小相等、方向相反。"}],"abstract":[{"en":"Picture two clear liquids meeting and turning white together.","cn":"想象两种澄清液体相遇，一同变白。"},{"en":"Picture a hand pushing a wall and the wall pushing back.","cn":"想象一只手推墙，墙也推回来。"},{"en":"Picture a crowd turning around at the same moment to face the speaker.","cn":"想象人群在同一刻转身面向说话者。"}]},"examples":[{"en":"The court's reaction to the ruling surprised both parties.","cn":"法院对这项裁决的反应让双方都感到意外。"},{"en":"A chain reaction stopped the experiment within a minute.","cn":"连锁反应在一分钟内终止了实验。"},{"en":"Reaction against the tax spread through the smaller towns.","cn":"对这项税的反弹在小城镇中蔓延。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"re（回）+ action（行动）＝ 回着行动，即反应；记「两液相遇、翻沫升温」。","word":"reaction"},"root":"拉丁 re-「回」+ agere「做、驱动」的行动名词 actio → 中世纪拉丁 reactio，英语主要经法语 réaction 借入。reactio 的拉丁首见有争议，更深来源无定论。","sensesIntro":{"en":"Nine senses follow one rebound: a person answers, a body answers, substances answer each other, a nucleus answers, a wall pushes back, politics resists, and markets, nerves and feelings all return something.","cn":"九个义项沿着同一次反弹展开：人回应，身体回应，物质彼此回应，原子核回应，墙推回来，政治抵抗，市场、神经与情绪也都还回某物。"},"semanticMap":{"core":{"en":"CORE IMAGE: two liquids meet in one beaker, foam rises and the glass grows hot.","cn":"核心意象：两种液体在同一只烧杯里相遇，泡沫翻起，杯壁变热。"},"chain":["ACTION","RETURN","INTERACTION","ENERGY","RESISTANCE","FEELING"],"branches":[{"senses":"01","en":"THE PERSON: someone acts first, and a person acts back in words or deeds.","cn":"人：有人先行动，另一个人以言语或行动反着行动。"},{"senses":"02 · 09","en":"BODY AND FEELING: inflammation and anger are both returns from inside the person.","cn":"身体与情绪：发炎与愤怒都是人内部给出的回返。"},{"senses":"03 · 04","en":"MATTER AND NUCLEUS: substances and nuclei act on each other and produce something new.","cn":"物质与原子核：物质与原子核彼此作用，产生新东西。"},{"senses":"05","en":"FORCE: mechanics states the return as an equal and opposite push.","cn":"力：力学把这种回返表述为大小相等、方向相反的一推。"},{"senses":"06 · 07 · 08","en":"RESISTANCE AND THE MARKET: politics, unthinking nerves and prices all move back against what came first.","cn":"抵抗与市场：政治、未经思考的神经与价格，都对着先来之物往回动。"}]},"affixes":{"intro":{"en":"Reaction is a Latin prefix plus a Latin action noun, and English built a compact family of verbs, adjectives and devices on the same stem.","cn":"reaction 是一个拉丁前缀加一个拉丁动作名词，英语在同一词干上建起一个紧凑的动词、形容词与装置词族。"},"latinIntro":{"en":"Latin re- 'back' and agere 'to do' build actio and reactio; the root also gives act, action, agent and agenda in English.","cn":"拉丁 re-「回」与 agere「做」构成 actio 与 reactio；这个词根在英语中还给出 act、action、agent 与 agenda。"},"items":[{"word":"re-","structure":"re- (Latin prefix, 'back, again')","meaning":"back; again","meaningCN":"回；再次","example":"The prefix turns an action into a return.","exampleCN":"这个前缀把行动变成回返。"},{"word":"agere","structure":"agere, egi, actum (Latin verb, third conjugation)","meaning":"to do; to drive","meaningCN":"做；驱动","example":"The root supplies act, action and agent.","exampleCN":"这个词根给出 act、action 与 agent。"},{"word":"actio","structure":"actio (Latin noun, -tio action suffix)","meaning":"an action; a doing","meaningCN":"行动；作为","example":"The noun is the second half of reaction.","exampleCN":"这个名词是 reaction 的后半部分。"},{"word":"reactio","structure":"reactio (Medieval Latin noun, re- + actio)","meaning":"a return action","meaningCN":"反作用；回返的行动","example":"The Latin noun is rare and its first record is disputed.","exampleCN":"这个拉丁名词罕见，最早书证有争议。"},{"word":"reaction","structure":"reaction (English noun via French)","meaning":"a response or return action","meaningCN":"反应；反作用","example":"The noun widened from physics to politics and chemistry.","exampleCN":"这个名词从物理扩展到政治与化学。"},{"word":"react","structure":"re- + act (English verb)","meaning":"to act back","meaningCN":"反着行动；作出反应","example":"The verb is the everyday member of the family.","exampleCN":"这个动词是词族中最日常的一员。"},{"word":"reactive","structure":"react + -ive (adjective)","meaning":"tending to react","meaningCN":"容易起反应的","example":"The adjective is common in chemistry.","exampleCN":"这个形容词在化学中常见。"},{"word":"reactor","structure":"react + -or (agent or device)","meaning":"a vessel or machine for a reaction","meaningCN":"产生反应的容器或机器","example":"The suffix marks the apparatus rather than the process.","exampleCN":"这个后缀标记装置，而非过程。"},{"word":"reactionary","structure":"reaction + -ary (belonging to)","meaning":"seeking to reverse change","meaningCN":"反对变革的","example":"The suffix turned a process into a political camp.","exampleCN":"这个后缀把过程变成政治阵营。"}],"latinEntries":[{"word":"agere","structure":"agere, egi, actum (verb, third conjugation)","meaning":"to do, drive, set in motion","meaningCN":"做；驱动；使运动"},{"word":"actio","structure":"actio, actionis (f., third declension)","meaning":"an action, a doing","meaningCN":"行动；作为"},{"word":"actus","structure":"actus, actus (m., fourth declension)","meaning":"a act, a deed","meaningCN":"行动；行为"},{"word":"reactio","structure":"reactio, reactionis (f., Medieval Latin)","meaning":"a return action","meaningCN":"反作用；回返的行动"}]}},{"word":"reflex","ipa_uk":"/ˈriːfleks/","ipa_us":"/ˈriːfleks/","definition_zh":"反射；反射动作；本能反应；反光式（摄影）；反射的：神经系统对刺激作出的不随意快速反应，也指光线折返的装置","definition_en":"an automatic, rapid nervous response to a stimulus, or a device that turns light back, or the adjective describing such a response","core_image":"膝头被小锤轻敲，小腿自行弹起，动作在意识跟上之前就已经完成","scene":"小锤轻敲膝头，小腿自行弹起，等意识到时动作已经完成。The doctor tapped the tendon to check that the reflex was intact.","sceneCN":"这里指神经系统对敲击作出的不随意快速反应（第 1 个义项：神经反射）；句意为医生敲击肌腱以检查反射是否完好。","pos":[{"tag":"n.","zh":"反射；反射动作（可数）"},{"tag":"adj.","zh":"反射的；反光式的"}],"collocations":[{"phrase":"a knee-jerk reflex","zh":"膝跳反射"},{"phrase":"a conditioned reflex","zh":"条件反射"},{"phrase":"reflex action","zh":"反射动作"},{"phrase":"test a reflex","zh":"检查反射"},{"phrase":"a reflex camera","zh":"反光式相机"},{"phrase":"a reflex response","zh":"反射性反应"}],"forms":[{"label":"单数","form":"reflex"},{"label":"复数","form":"reflexes"},{"label":"形容词（反身的）","form":"reflexive"},{"label":"副词（反射性地）","form":"reflexly"},{"label":"名词（反射性）","form":"reflexivity"}],"derivatives":[{"word":"reflexive","pos":"adj.","zh":"reflex + -ive（具有……性质的）→ 反身的；反射性的"},{"word":"reflexly","pos":"adv.","zh":"reflex + -ly（方式副词）→ 以反射的方式"},{"word":"reflexology","pos":"n.","zh":"reflex + -ology（学科）→ 以反射解释行为的学说，语义偏移为「反射学」"},{"word":"reflect","pos":"v.","zh":"reflectere 去词尾 → 折回；反光，是 reflex 的同源动词"},{"word":"reflection","pos":"n.","zh":"reflect + -ion（动作或结果）→ 折回；反光，语义偏移为「沉思」"}],"senses":[{"no":"01","title":"An automatic nervous response","titleCN":"神经系统的自动反应","definition":"a rapid, involuntary response of a nerve or muscle to a stimulus, mediated by a reflex arc","definitionCN":"神经或肌肉对刺激作出的快速、不随意反应，由反射弧介导","example":"The knee reflex disappeared after the nerve was damaged.","exampleCN":"神经受损后，膝反射消失了。","why":"Latin reflexus is 'bent back', because the impulse is imagined as turning back from the muscle to the cord.","whyCN":"拉丁 reflexus 意为「折回」，因为冲动被想象为从肌肉折回脊髓。"},{"no":"02","title":"An unthinking reaction","titleCN":"不假思索的本能反应","definition":"an immediate response made before reflection, often emotional or habitual","definitionCN":"在思考之前作出的即时回应，常带情绪或习惯性","example":"Apology was a reflex, not a considered decision.","exampleCN":"道歉是本能反应，不是经过考虑的决定。","why":"the bodily image transferred to conduct: an answer that comes back before thought does.","whyCN":"身体形象转移到举止上：回答在思考之前就回来了。"},{"no":"03","title":"A reflex movement","titleCN":"反射性动作","definition":"a movement produced by a reflex rather than by intention, such as blinking or withdrawing a hand","definitionCN":"由反射而非意图产生的动作，如眨眼或缩手","example":"The withdrawal reflex moved his hand before he saw the flame.","exampleCN":"他看见火焰之前，缩手反射已经把他的手移开了。","why":"the noun names the whole event, so the movement itself can be called a reflex.","whyCN":"名词命名整个事件，因此动作本身也能被称为反射。"},{"no":"04","title":"The reflex arc","titleCN":"反射弧","definition":"the neural pathway from sensory receptor through the spinal cord to the muscle that carries out the response","definitionCN":"从感受器经脊髓到执行反应肌肉的神经通路","example":"The reflex arc bypasses the brain and saves precious milliseconds.","exampleCN":"反射弧绕过大脑，省下宝贵的毫秒。","why":"physiology needed a name for the circuit, and the whole event's name was extended to its wiring.","whyCN":"生理学需要给这条回路一个名字，整个事件的名字便被扩展到它的线路。"},{"no":"05","title":"An unconditioned response in psychology","titleCN":"心理学中的无条件反射","definition":"a response that occurs naturally to a stimulus without prior learning, as salivation to food","definitionCN":"无需先前学习、对刺激自然发生的反应，如见食物分泌唾液","example":"Salivation to food is the classic unconditioned reflex.","exampleCN":"见食物流涎是经典的无条件反射。","why":"psychology borrowed the physiological term to name the unlearned half of conditioning.","whyCN":"心理学借用生理学术语，命名条件作用中未经学习的那一半。"},{"no":"06","title":"A reflex camera","titleCN":"反光式相机","definition":"a camera in which a mirror redirects the image to the viewfinder before the shot","definitionCN":"拍摄前用反光镜把影像送到取景器的相机","example":"The reflex camera let her see exactly what the lens saw.","exampleCN":"反光式相机让她准确看到镜头所见的画面。","why":"here reflex keeps its optical sense: light is turned back into the photographer's eye.","whyCN":"这里的 reflex 保留光学义：光被折回摄影者眼中。"},{"no":"07","title":"Light bent back","titleCN":"被折返的光","definition":"light or an image returned from a surface, the older optical sense of the word","definitionCN":"从表面返回的光或影像，是该词较早的光学义","example":"The reflex of the sun on the water blinded the rowers.","exampleCN":"水面反照的阳光使划船者目眩。","why":"the optical sense came first in English, and the nervous sense borrowed its name from it.","whyCN":"光学义在英语中先出现，神经义则借用了它的名字。"},{"no":"08","title":"The adjective for automatic responses","titleCN":"形容词：反射性的","definition":"describing an action that occurs automatically in answer to a stimulus","definitionCN":"描述对刺激自动发生的动作","example":"A reflex blink protected the eye from the dust.","exampleCN":"一次反射性眨眼保护了眼睛免受灰尘侵扰。","why":"English lets the noun work as an attributive adjective, so the same form labels the kind of response.","whyCN":"英语允许名词作定语形容词，因此同一形式也能标记反应的种类。"}],"etymology":{"intro":{"en":"Reflex comes from Latin reflexus, the past participle of reflectere 'to bend back'. The optical sense came first in English and the nervous sense followed in the nineteenth century. Dates are approximate.","cn":"reflex 来自拉丁 reflexus，即 reflectere「折回」的过去分词。英语中先出现光学义，神经义则在 19 世纪跟进。年代为约数。"},"items":[{"era":"LATIN FLECTERE","en":"Flectere meant 'to bend, curve, turn'. Its compounds describe bending something in a chosen direction.","cn":"flectere 意为「弯、曲、转」。其复合词描述把某物朝某个方向弯折。"},{"era":"LATIN REFLECTERE","en":"Re- 'back' plus flectere gave reflectere 'to bend back, turn back', used of light, water and the mind alike.","cn":"re-「回」加 flectere 构成 reflectere「折回、转回」，光、水面与心智都用这个词。"},{"era":"LATIN REFLEXUS","en":"The past participle reflexus meant 'bent back', and as a noun it named a bending back, including the turning back of light.","cn":"过去分词 reflexus 意为「被折回的」，作名词时指折返，包括光的折回。"},{"era":"ENGLISH OPTICAL SENSE","en":"English reflex appeared in the sixteenth century for light or an image turned back from a surface, a sense now mostly carried by reflection.","cn":"英语 reflex 在 16 世纪出现，指从表面折回的光或影像，这一义如今主要由 reflection 承担。"},{"era":"PHYSIOLOGY AND PSYCHOLOGY","en":"In the nineteenth century physiology gave reflex its nervous sense, and psychology added the conditioned reflex in the early twentieth.","cn":"19 世纪生理学赋予 reflex 神经义，心理学在 20 世纪初加上条件反射。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first physiological use in English): the term spread through nineteenth-century medical writing, and no single first citation is settled; the exact date of the camera sense is also approximate.","cn":"来源不确定（英语生理义的首见）：这个术语经 19 世纪医学写作扩散，没有公认的首次书证；相机义的确切年代亦为约数。"}]},"similar":{"note":{"en":"Group one holds forms from the same reflect stem that name different things; group two holds other automatic or involuntary responses.","cn":"第一组是同出 reflect 词干、命名不同事物的形式；第二组是其他自动或不随意的反应。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"reflection","ipa":"/rɪˈflekʃən/","tag":"light or thought","definition":"The noun for light turned back or for careful thought; it does not name a nervous response.","definitionCN":"指折回的光或深思的名词，不指神经反应。"},{"word":"reflexive","ipa":"/rɪˈfleksɪv/","tag":"grammar and logic","definition":"An adjective for words or relations that turn back on their subject; it is not the noun for a knee jerk.","definitionCN":"指回指主语的词或关系的形容词，不是指膝跳的名词。"},{"word":"reflect","ipa":"/rɪˈflekt/","tag":"the verb","definition":"The verb meaning 'to bend back' or 'to think carefully'; the noun reflex is a different part of speech.","definitionCN":"意为「折回」或「深思」的动词；名词 reflex 属于不同词类。"}]},{"heading":"NEAR MEANING","entries":[{"word":"instinct","ipa":"/ˈɪnstɪŋkt/","tag":"inborn drive","definition":"An inborn pattern of behaviour common to a species; it is broader and less mechanical than a single reflex.","definitionCN":"物种共有的先天行为模式，比单次反射更宽泛，也不那么机械。"},{"word":"reaction","ipa":"/riˈækʃən/","tag":"any return","definition":"Any response to an event, including deliberate ones; a reflex is specifically automatic and fast.","definitionCN":"对事件的任何回应，包括有意的；reflex 特指自动且快速的那一种。"},{"word":"conditioned response","ipa":"/kənˈdɪʃənd rɪˈspɒns/","tag":"learned, not innate","definition":"A response acquired through pairing; it is the learned counterpart of the unlearned reflex.","definitionCN":"通过配对习得的反应，是先天反射的学习对应物。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real medical collocations and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实医学搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"re- 'back' plus flectere 'bend': a reflex is a bend back along the same wire.","cn":"re-「回」加 flectere「弯」：反射就是沿同一根线折回去。"},{"en":"The family runs reflect, reflection, reflexive, reflexly, reflexology.","cn":"同族词包括 reflect、reflection、reflexive、reflexly、reflexology。"},{"en":"Fixed medical phrases: knee-jerk reflex, reflex action, test a reflex.","cn":"固定医学搭配：膝跳反射、反射动作、检查反射。"},{"en":"The optical sense survives in reflex camera, where a mirror turns light back.","cn":"光学义存留在 reflex camera 里，那里的反光镜把光折回。"},{"en":"The contrast is conditioned reflex, which is learned rather than wired in.","cn":"对照项是条件反射，它是学来的，而非天生接好的。"}],"abstract":[{"en":"Picture a hammer tapping a knee and the leg answering on its own.","cn":"想象小锤敲一下膝盖，腿自己作出回答。"},{"en":"Picture a wire that loops from muscle back to cord without passing the brain.","cn":"想象一根线从肌肉绕回脊髓，不经过大脑。"},{"en":"Picture a mirror in a camera turning the world back into your eye.","cn":"想象相机里的一面镜子把世界折回你的眼睛。"}]},"examples":[{"en":"The reflex was tested on both sides for comparison.","cn":"为作比较，两侧都检查了反射。"},{"en":"Years of practice had made the movement a reflex.","cn":"多年练习已使这个动作成为本能反应。"},{"en":"The reflex camera became standard for press photographers.","cn":"反光式相机成为新闻摄影的标准设备。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"re（回）+ flex（弯）＝ 折回去；记「锤敲膝盖，腿自己弹起」。","word":"reflex"},"root":"拉丁 re-「回」+ flectere「弯、转」→ reflectere「折回」，过去分词 reflexus「被折回的」；英语先用于光学，19 世纪转用于神经反应。","sensesIntro":{"en":"Eight senses follow one bend: an impulse turns back, the movement happens, the circuit is mapped, the learned version appears, and the same optical bend survives in cameras and sunlight.","cn":"八个义项沿着同一次折返展开：冲动折回、动作发生、回路被画出、学习版本出现，而同一种光学折返仍活在相机与阳光里。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hammer taps a tendon, and the leg answers before the person notices.","cn":"核心意象：小锤敲在肌腱上，腿在人察觉之前就作出回答。"},"chain":["BEND BACK","IMPULSE","MOVEMENT","CIRCUIT","LEARNING","OPTICAL RETURN"],"branches":[{"senses":"01","en":"THE NERVE: the core is a quick involuntary answer carried by a nerve.","cn":"神经：核心是由神经传导的快速不随意回答。"},{"senses":"02 · 03","en":"HABIT AND BODY: an unthinking answer in speech and a withdrawal of the hand are the same speed seen twice.","cn":"习惯与身体：言语中的不假思索与手的缩回，是同一种速度的两种表现。"},{"senses":"04 · 05","en":"WIRING AND LEARNING: the arc explains the circuit, and the unconditioned response marks what needs no training.","cn":"线路与学习：反射弧解释回路，无条件反射标记无需训练的部分。"},{"senses":"06 · 07","en":"LIGHT: a mirror in a camera and the sun on water both bend light back to the eye.","cn":"光：相机里的镜子与水面上的阳光，都把光折回眼睛。"},{"senses":"08","en":"THE ADJECTIVE: the same form labels any response that comes automatically.","cn":"形容词：同一形式标记任何自动发生的反应。"}]},"affixes":{"intro":{"en":"Reflex is a Latin participle used as an English noun and adjective, and its root builds a family through the verb reflect.","cn":"reflex 是拉丁分词，在英语中作名词与形容词，其词根通过动词 reflect 建起一个词族。"},"latinIntro":{"en":"Latin flectere 'to bend' and re- 'back' build reflectere, reflexus and reflexio; the same root appears in flexible and inflection.","cn":"拉丁 flectere「弯」与 re-「回」构成 reflectere、reflexus 与 reflexio；同一词根还出现在 flexible 与 inflection 中。"},"items":[{"word":"re-","structure":"re- (Latin prefix, 'back')","meaning":"back","meaningCN":"回；向后","example":"The prefix reverses the direction of bending.","exampleCN":"这个前缀把弯折的方向反过来。"},{"word":"flectere","structure":"flectere, flexi, flexum (Latin verb, third conjugation)","meaning":"to bend, curve, turn","meaningCN":"弯；曲；转","example":"The root also gives flexible and inflection.","exampleCN":"这个词根还给出 flexible 与 inflection。"},{"word":"reflectere","structure":"re- + flectere (Latin verb)","meaning":"to bend back, turn back","meaningCN":"折回；转回","example":"The verb covers light, water and thought.","exampleCN":"这个动词覆盖光、水面与思想。"},{"word":"reflexus","structure":"reflexus (Latin past participle and noun)","meaning":"bent back; a bending back","meaningCN":"被折回的；折返","example":"The participle is the direct source of reflex.","exampleCN":"这个分词是 reflex 的直接来源。"},{"word":"reflex","structure":"reflex (English noun and adjective)","meaning":"an automatic response or a turned-back light","meaningCN":"自动反应；折回的光","example":"English added the nervous sense in the nineteenth century.","exampleCN":"英语在 19 世纪加上神经义。"},{"word":"reflexive","structure":"reflex + -ive (adjective)","meaning":"turning back on itself","meaningCN":"回指自身的","example":"The suffix carries the grammar and logic senses.","exampleCN":"这个后缀承载语法与逻辑义。"},{"word":"reflexly","structure":"reflex + -ly (adverb)","meaning":"in a reflex manner","meaningCN":"以反射的方式","example":"The adverb is rare but regular.","exampleCN":"这个副词罕见但合乎规则。"},{"word":"reflexology","structure":"reflex + -ology (study of)","meaning":"a theory explaining behaviour by reflexes","meaningCN":"以反射解释行为的学说","example":"The word later also named foot massage, an unrelated use.","exampleCN":"这个词后来也指足部按摩，属无关用法。"},{"word":"reflection","structure":"reflect + -ion (action noun)","meaning":"a turning back of light; careful thought","meaningCN":"光的折回；深思","example":"The noun now carries most of the optical sense.","exampleCN":"这个名词如今承担大部分光学义。"}],"latinEntries":[{"word":"flectere","structure":"flectere, flexi, flexum (verb, third conjugation)","meaning":"to bend, curve, turn","meaningCN":"弯；曲；转"},{"word":"reflectere","structure":"reflectere, reflexi, reflexum (verb, third conjugation)","meaning":"to bend back, turn back","meaningCN":"折回；转回"},{"word":"reflexus","structure":"reflexus, reflexa, reflexum (past participle)","meaning":"bent back","meaningCN":"被折回的"},{"word":"reflexio","structure":"reflexio, reflexionis (f., Late Latin)","meaning":"a bending back, a reflection","meaningCN":"折返；反射"}]}},{"word":"reflexive","ipa_uk":"/rɪˈfleksɪv/","ipa_us":"/rɪˈfleksɪv/","definition_zh":"反身的（语法）；反射性的；自反的（逻辑）；自我指涉的：指动作回指自身，或某种关系适用于自身","definition_en":"describing a word, action or relation that turns back on its own subject or on itself","core_image":"一个人对着镜子系领带，镜中的手与自己的手同时抬起","scene":"一个人对着镜子系领带，镜中的手与自己的手同时抬起。In grammar, a reflexive pronoun sends the action back to the doer.","sceneCN":"这里指语法中动作回指主语自身的用法（第 1 个义项：语法上的反身）；句意为反身代词把动作送回动作的发出者。","pos":[{"tag":"adj.","zh":"反身的（语法）；反射性的"},{"tag":"adj.","zh":"自反的（逻辑）；自我指涉的"}],"collocations":[{"phrase":"a reflexive pronoun","zh":"反身代词"},{"phrase":"a reflexive verb","zh":"反身动词"},{"phrase":"a reflexive relation","zh":"自反关系"},{"phrase":"reflexive awareness","zh":"反身性觉察"},{"phrase":"a reflexive response","zh":"反射性反应"},{"phrase":"reflexive modernity","zh":"反身性现代性"}],"forms":[{"label":"原形（形容词）","form":"reflexive"},{"label":"副词","form":"reflexively"},{"label":"名词（反身性）","form":"reflexivity"},{"label":"名词（反身代词）","form":"reflexive pronoun"},{"label":"同源名词","form":"reflex"}],"derivatives":[{"word":"reflexively","pos":"adv.","zh":"reflexive + -ly（方式副词）→ 以反身或反射的方式"},{"word":"reflexivity","pos":"n.","zh":"reflexive + -ity（性质名词）→ 回指自身的性质，语义偏移为「反身性」"},{"word":"reflex","pos":"n.","zh":"reflexus 去词尾 → 反射；反射动作，是 -ive 形容词的同源名词"},{"word":"reflection","pos":"n.","zh":"reflect + -ion（动作或结果）→ 折回，语义偏移为「反思」"},{"word":"self-referential","pos":"adj.","zh":"self + refer + -ential → 指涉自身的，与 reflexive 的哲学义相近"}],"senses":[{"no":"01","title":"Reflexive in grammar","titleCN":"语法上的反身","definition":"describing a pronoun or verb whose action returns to the subject, as in 'she hurt herself'","definitionCN":"描述动作回到主语的代词或动词，如「她伤了自己」","example":"English keeps only a few truly reflexive verbs.","exampleCN":"英语只剩少数真正的反身动词。","why":"Latin grammarians called pronouns that turned the action back to the subject reflexiva, and the label passed into English grammar.","whyCN":"拉丁语法学家把使动作回到主语的代词称为 reflexiva，这个标签进入了英语语法。"},{"no":"02","title":"Reflex-like, without thought","titleCN":"反射性的、不经思考的","definition":"describing a response that happens automatically, before deliberate control","definitionCN":"描述在有意识控制之前自动发生的反应","example":"Her reflexive flinch came before the word 'sorry'.","exampleCN":"她反射性的退缩出现在「抱歉」一词之前。","why":"the same bend-back image describes a nervous loop that closes without passing through deliberation.","whyCN":"同一个折返意象描述一条不经思考就闭合的神经回路。"},{"no":"03","title":"A reflexive relation in logic","titleCN":"逻辑与数学中的自反关系","definition":"describing a relation that every element bears to itself, such as equality","definitionCN":"描述每个元素都与自身成立的关系，如相等关系","example":"Equality is reflexive, because every number equals itself.","exampleCN":"相等是自反的，因为每个数都等于自身。","why":"a relation that turns back on its own terms is literally reflexive, so logic borrowed the adjective.","whyCN":"一个回到自身项上的关系字面上就是反身的，逻辑学因此借用了这个形容词。"},{"no":"04","title":"Self-referential in philosophy and art","titleCN":"哲学与艺术中的自我指涉","definition":"describing a work, sentence or system that refers to itself","definitionCN":"描述指涉自身的作品、句子或系统","example":"The novel is reflexive: it keeps showing how novels are written.","exampleCN":"这部小说是自我指涉的：它不断展示小说如何被写出来。","why":"when a work bends back on its own making, the grammar term becomes an aesthetic one.","whyCN":"当作品折回自身的制作过程，语法术语就变成美学术语。"},{"no":"05","title":"Reflexivity in social science","titleCN":"社会科学中的反身性","definition":"the process by which knowledge about a society changes that society, so observation feeds back into its object","definitionCN":"关于社会的知识反过来改变该社会，观察回馈进对象的过程","example":"Reflexive research changes the community it studies.","exampleCN":"反身性研究改变它所研究的社群。","why":"if the observer is inside the thing observed, the loop closes on itself, which is the adjective's core shape.","whyCN":"如果观察者就在被观察之物内部，回路便闭合于自身，这正是这个形容词的核心形状。"},{"no":"06","title":"The reflexive construction","titleCN":"反身结构本身","definition":"the sentence pattern in which the object is the same person as the subject, often marked by -self","definitionCN":"宾语与主语为同一人的句式，常以 -self 标记","example":"The reflexive construction makes the agent and the affected one person.","exampleCN":"反身结构使施动者与受影响者是同一个人。","why":"the pattern is a named object of study, so the adjective also names the construction rather than only the word.","whyCN":"这个句式是被命名的研究对象，因此形容词也命名结构本身，而不只是词。"},{"no":"07","title":"The optical sense, now rare","titleCN":"较少用的光学义","definition":"describing light or an image turned back from a surface, an older technical use","definitionCN":"描述从表面折回的光或影像，属较早的技术用法","example":"The older texts speak of reflexive rays where we now say reflected.","exampleCN":"较早的文本说 reflexive rays，如今我们说 reflected。","why":"before reflection became the standard noun, the adjective carried the optical sense of the same Latin participle.","whyCN":"在 reflection 成为标准名词之前，这个形容词承载同一拉丁分词的光学义。"},{"no":"08","title":"The general adjective of self-return","titleCN":"形容词总义：回指自身的","definition":"the broad sense covering any word, act or system that returns to its own source","definitionCN":"涵盖任何回到自身来源的词、动作或系统的广义","example":"Any account that includes itself is reflexive in the broad sense.","exampleCN":"任何把自身包含在内的叙述，广义上都是反身的。","why":"the narrower senses are applications of one shape: something that bends back to where it started.","whyCN":"较窄的几个义项都是同一形状的应用：某物折回它开始的地方。"}],"etymology":{"intro":{"en":"Reflexive is the Latin adjective reflexivus, built on reflexus 'bent back'. Latin grammarians used it for pronouns that turn the action back to the subject. Dates are approximate.","cn":"reflexive 是拉丁形容词 reflexivus，建立在 reflexus「被折回的」之上。拉丁语法学家用它指使动作回到主语的反身代词。年代为约数。"},"items":[{"era":"LATIN REFLECTERE","en":"Re- 'back' plus flectere 'to bend' gave reflectere 'to bend back', whose participle reflexus supplied the whole family.","cn":"re-「回」加 flectere「弯」构成 reflectere「折回」，其分词 reflexus 提供整个词族。"},{"era":"LATIN REFLEXIVUS","en":"The Late Latin adjective reflexivus meant 'turning back', and Latin grammarians applied it to pronomina reflexiva, pronouns that reflect the action onto the subject.","cn":"晚期拉丁形容词 reflexivus 意为「折回的」，拉丁语法学家把它用于 pronomina reflexiva，即把动作反射回主语的反身代词。"},{"era":"ENGLISH GRAMMAR","en":"English grammar took reflexive in the sixteenth and seventeenth centuries for pronouns such as himself and herself.","cn":"英语语法在 16 与 17 世纪用 reflexive 指 himself、herself 这类代词。"},{"era":"LOGIC AND MATHEMATICS","en":"From the nineteenth century logic used reflexive for a relation that every element bears to itself, such as equality.","cn":"从 19 世纪起，逻辑学用 reflexive 指每个元素都与自身成立的关系，如相等。"},{"era":"SOCIAL SCIENCE","en":"In the twentieth century reflexivity named the loop by which knowledge about society re-enters and alters society.","cn":"在 20 世纪，reflexivity 指关于社会的知识重新进入并改变社会的回路。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first English grammatical use): the adjective appears in several early grammars, and no single first citation is established; the optical sense was already fading when the grammar sense arrived.","cn":"来源不确定（英语语法义的首见）：这个形容词出现在多部早期语法书中，没有公认的首次书证；语法义到来时光学义已在衰退。"}]},"similar":{"note":{"en":"Group one holds near forms from the same stem with different jobs; group two holds other words for things that point back at themselves.","cn":"第一组是同词干、分工不同的近形词；第二组是其他表示「指回自身」的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"reflective","ipa":"/rɪˈflektɪv/","tag":"thoughtful or mirroring","definition":"Describing a person given to thought or a surface that mirrors; it does not name grammar or logic.","definitionCN":"描述好深思的人或能照影的表面，不指语法或逻辑。"},{"word":"reflex","ipa":"/ˈriːfleks/","tag":"the noun","definition":"The automatic response itself; reflexive is the adjective describing what turns back.","definitionCN":"指自动反应本身；reflexive 是描述「折回」的形容词。"},{"word":"reflection","ipa":"/rɪˈflekʃən/","tag":"the noun of return","definition":"Light turned back or careful thought; it is a noun, while reflexive is an adjective.","definitionCN":"指折回的光或深思，是名词，而 reflexive 是形容词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"reciprocal","ipa":"/rɪˈsɪprəkəl/","tag":"two-way between parties","definition":"Describing an action exchanged between two parties, as mutual aid; reflexive action returns to one party only.","definitionCN":"描述两方之间的交换，如互助；反身动作只回到一方自身。"},{"word":"self-referential","ipa":"/ˌself ˌrefəˈrenʃəl/","tag":"plain compound","definition":"A transparent compound meaning 'referring to itself'; it is common in philosophy and literary criticism.","definitionCN":"透明的复合词，意为「指涉自身」，常见于哲学与文学批评。"},{"word":"automatic","ipa":"/ˌɔːtəˈmætɪk/","tag":"without control","definition":"Describing an action that happens by itself; it stresses lack of control rather than the return of an impulse.","definitionCN":"描述自行发生的动作，强调不受控制，而非冲动的回返。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real grammar terms and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实语法术语与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"re- 'back' plus flectere 'bend': the action bends back to the one who did it.","cn":"re-「回」加 flectere「弯」：动作弯回到做它的人身上。"},{"en":"The family runs reflex, reflexive, reflexively, reflexivity, reflection.","cn":"同族词包括 reflex、reflexive、reflexively、reflexivity、reflection。"},{"en":"Grammar phrases pin the first sense: reflexive pronoun, reflexive verb.","cn":"语法搭配钉住第一个义项：反身代词、反身动词。"},{"en":"Logic phrases pin the third: reflexive relation, reflexive property.","cn":"逻辑搭配钉住第三个义项：自反关系、自反性质。"},{"en":"The contrast to keep is reciprocal, which goes between two parties rather than back to one.","cn":"要记住的对照是 reciprocal，它在两方之间往返，而非回到一方自身。"}],"abstract":[{"en":"Picture a hand tying a tie while the mirror hand ties the same tie.","cn":"想象一只手系领带，镜中的手也在系同一条领带。"},{"en":"Picture an arrow that curves all the way back to its own tail.","cn":"想象一支箭头弯回自己的尾部。"},{"en":"Picture a book whose first page describes someone reading this book.","cn":"想象一本书的第一页描述某人正在读这本书。"}]},"examples":[{"en":"The reflexive pronoun is required after the preposition here.","cn":"这里的介词后必须用反身代词。"},{"en":"Her apology was reflexive rather than sincere.","cn":"她的道歉是反射性的，而非真诚的。"},{"en":"Equality is a reflexive relation on any set of numbers.","cn":"相等是任何数集上的自反关系。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"re（回）+ flex（弯）+ ive（……的）＝ 弯回自身的；记「镜中那只手与自己的手同时抬起」。","word":"reflexive"},"root":"拉丁 re-「回」+ flectere「弯」→ reflexus「被折回的」，加 -ivus 构成晚期拉丁 reflexivus「折回的」；拉丁语法家用它指反身代词。","sensesIntro":{"en":"Eight senses follow one loop: a pronoun returns the act, a nerve returns before thought, a relation returns to each element, an artwork to itself, a science to its object, and an old adjective to its optical past.","cn":"八个义项沿着同一个回路展开：代词把动作送回，神经在思考前送回，关系回到每个元素，作品回到自身，科学回到其对象，而旧形容词回到它的光学过去。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand tying a tie while its mirror image performs the same motion.","cn":"核心意象：一只手在系领带，镜中的影像同时做同一个动作。"},"chain":["SUBJECT","ACTION","RETURN","SELF","LOOP","VARIETIES"],"branches":[{"senses":"01 · 06","en":"GRAMMAR: the pronoun and the whole construction both send the verb's action back to its subject.","cn":"语法：代词与整个结构都把动词的动作送回主语。"},{"senses":"02","en":"NERVES: a flinch closes the loop before deliberation can enter.","cn":"神经：退缩在思考进入之前就闭合了回路。"},{"senses":"03","en":"LOGIC: a relation such as equality holds between each element and itself.","cn":"逻辑：相等这类关系在每个元素与自身之间成立。"},{"senses":"04 · 05","en":"ART AND SCIENCE: a work refers to its own making, and research feeds back into the community it studies.","cn":"艺术与科学：作品指涉自身的制作，研究则回馈进它所研究的社群。"},{"senses":"07 · 08","en":"THE OLD AND THE BROAD: the optical use survives in old texts, while the broad sense covers any return to source.","cn":"旧义与广义：光学用法存留于旧文本，广义则涵盖任何回到来源的回返。"}]},"affixes":{"intro":{"en":"Reflexive adds the Latin adjective suffix -ivus to the participle reflexus, so it is one bend plus one 'tending to' ending.","cn":"reflexive 在分词 reflexus 上加拉丁形容词后缀 -ivus，因此它是「一次折返」加一个「倾向于」的词尾。"},"latinIntro":{"en":"Latin flectere supplies the bend, re- supplies the return, and -ivus supplies the adjective; reflexivus is the Late Latin result.","cn":"拉丁 flectere 提供弯折，re- 提供回返，-ivus 提供形容词词尾；reflexivus 是晚期拉丁语的合成结果。"},"items":[{"word":"re-","structure":"re- (Latin prefix, 'back')","meaning":"back","meaningCN":"回；向后","example":"The prefix supplies the return in every member of the family.","exampleCN":"这个前缀为词族每个成员提供回返义。"},{"word":"flectere","structure":"flectere, flexi, flexum (Latin verb)","meaning":"to bend","meaningCN":"弯","example":"The root also builds flexible and inflection.","exampleCN":"这个词根还构成 flexible 与 inflection。"},{"word":"reflexus","structure":"reflexus (Latin past participle)","meaning":"bent back","meaningCN":"被折回的","example":"The participle is the base of the adjective.","exampleCN":"这个分词是形容词的基础。"},{"word":"reflexivus","structure":"reflexivus (Late Latin adjective, -ivus suffix)","meaning":"turning back","meaningCN":"折回的","example":"Latin grammarians used it of pronouns.","exampleCN":"拉丁语法学家用它指代词。"},{"word":"reflexive","structure":"reflexive (English adjective)","meaning":"turning back on itself","meaningCN":"回指自身的","example":"English widened it from grammar to logic and art.","exampleCN":"英语把它从语法扩展到逻辑与艺术。"},{"word":"reflexively","structure":"reflexive + -ly (adverb)","meaning":"in a returning manner","meaningCN":"以回返的方式","example":"The adverb marks automatic or self-directed action.","exampleCN":"这个副词标记自动或指向自身的动作。"},{"word":"reflexivity","structure":"reflexive + -ity (quality noun)","meaning":"the quality of turning back on itself","meaningCN":"回指自身的性质","example":"The noun became central in social theory.","exampleCN":"这个名词在社会理论中变得核心。"},{"word":"reflex","structure":"reflex (English noun and adjective)","meaning":"an automatic response","meaningCN":"自动反应","example":"It is the shorter sibling of the same stem.","exampleCN":"它是同一词干较短的兄弟词。"},{"word":"-ive","structure":"-ivus (Latin adjective suffix, 'tending to')","meaning":"tending to; having the nature of","meaningCN":"倾向于；具有……性质的","example":"The suffix also builds active and passive.","exampleCN":"这个后缀也构成 active 与 passive。"}],"latinEntries":[{"word":"flectere","structure":"flectere, flexi, flexum (verb, third conjugation)","meaning":"to bend","meaningCN":"弯"},{"word":"reflectere","structure":"reflectere, reflexi, reflexum (verb, third conjugation)","meaning":"to bend back","meaningCN":"折回"},{"word":"reflexivus","structure":"reflexivus, reflexiva, reflexivum (Late Latin adjective)","meaning":"turning back","meaningCN":"折回的"}]}},{"word":"reinforcement theory","ipa_uk":"/ˌriːɪnˈfɔːsmənt ˈθɪəri/","ipa_us":"/ˌriːɪnˈfɔːrsmənt ˈθɪri/","definition_zh":"强化理论：认为行为由其后果决定，正强化增加行为、负强化移除不快以维持行为的理论","definition_en":"the theory that behaviour is governed by its consequences, with positive reinforcement increasing an act and negative reinforcement removing discomfort to sustain it","core_image":"一只杠杆被按下，食丸落进托盘；同一动作重复得越来越快，旁边的计数纸越写越密","scene":"小鼠按下杠杆，食丸落进托盘，同一动作随之越来越频繁，计数纸越写越密。Reinforcement theory predicts that a rewarded act will be repeated more often.","sceneCN":"这里指以行为后果解释行为频率的理论（第 1 个义项：强化理论的总称）；句意为强化理论预测，受到奖赏的动作会更频繁地被重复。","pos":[{"tag":"n.","zh":"强化理论（不可数，行为主义理论名）"}],"collocations":[{"phrase":"reinforcement theory in education","zh":"教育中的强化理论"},{"phrase":"apply reinforcement theory","zh":"应用强化理论"},{"phrase":"a critique of reinforcement theory","zh":"对强化理论的批评"},{"phrase":"positive reinforcement","zh":"正强化"},{"phrase":"negative reinforcement","zh":"负强化"},{"phrase":"a reinforcement schedule","zh":"强化程式"}],"forms":[{"label":"理论名（不可数）","form":"reinforcement theory"},{"label":"核心名词","form":"reinforcement"},{"label":"动词","form":"reinforce"},{"label":"形容词","form":"reinforcing"},{"label":"从业理论名","form":"operant conditioning"}],"derivatives":[{"word":"reinforce","pos":"v.","zh":"re- + in- + force（力量）→ 再注入力量，语义偏移为「强化、增援」"},{"word":"reinforcement","pos":"n.","zh":"reinforce + -ment（动作或结果）→ 强化这一过程或其手段"},{"word":"reinforcer","pos":"n.","zh":"reinforce + -er（施动者）→ 起强化作用的刺激或事件"},{"word":"reinforcing","pos":"adj.","zh":"reinforce + -ing（现在分词形容词）→ 起强化作用的"},{"word":"theory","pos":"n.","zh":"theoria（观看、思辨）→ 系统解释，语义偏移为「理论」"}],"senses":[{"no":"01","title":"The general theory of consequences","titleCN":"以后果解释行为的理论总称","definition":"the general claim that the frequency of a behaviour is governed by the consequences that follow it","definitionCN":"主张行为频率由其后的后果决定的一般性主张","example":"Reinforcement theory explains why the habit persisted after the reward stopped.","exampleCN":"强化理论解释了为什么奖励停止后习惯仍然持续。","why":"reinforcement supplies the means and theory supplies the framework, so the phrase names a body of explanation rather than one experiment.","whyCN":"reinforcement 提供手段，theory 提供框架，因此短语命名的是一套解释，而非一次实验。"},{"no":"02","title":"Positive reinforcement","titleCN":"正强化：给予奖赏以增加行为","definition":"the procedure of adding a desirable consequence after a behaviour so that it becomes more frequent","definitionCN":"在行为之后加上令人满意的后果，使该行为更频繁的程序","example":"Positive reinforcement raised the number of completed exercises.","exampleCN":"正强化提高了完成练习的数量。","why":"positive here means adding something, not 'good': a reward is added to the situation.","whyCN":"这里的 positive 指「加上某物」，而非「好的」：奖励被加到情境中。"},{"no":"03","title":"Negative reinforcement","titleCN":"负强化：移除不快以维持行为","definition":"the procedure of removing an unpleasant condition after a behaviour so that the behaviour is maintained","definitionCN":"在行为之后移除不愉快条件，使该行为得以维持的程序","example":"Negative reinforcement ended the noise as soon as the lever was pressed.","exampleCN":"负强化在杠杆被按下时立刻终止噪声。","why":"negative means subtracting something: relief, not punishment, is what strengthens the act.","whyCN":"negative 指「减去某物」：强化行为的是解脱，而不是惩罚。"},{"no":"04","title":"Operant conditioning","titleCN":"操作性条件作用","definition":"the learning process in which a voluntary act is shaped by the consequences that follow it","definitionCN":"自愿动作被其后的后果塑造的学习过程","example":"Operant conditioning made the pigeon turn whenever the light came on.","exampleCN":"操作性条件作用使鸽子在灯亮时转身。","why":"the theory needs a learning mechanism, and operant conditioning is that mechanism in its laboratory form.","whyCN":"理论需要一个学习机制，操作性条件作用就是该机制的实验室形态。"},{"no":"05","title":"Schedules of reinforcement","titleCN":"强化程式","definition":"rules deciding when a response is rewarded, such as fixed intervals or variable ratios","definitionCN":"决定何时对反应给予奖励的规则，如固定间隔或可变比率","example":"A variable ratio schedule produced the steadiest responding.","exampleCN":"可变比率程式产生最稳定的反应。","why":"the theory's predictions depend on timing, so schedules became a distinct subject within it.","whyCN":"理论的预测取决于时机，因此程式成为其中独立的研究对象。"},{"no":"06","title":"Application in teaching","titleCN":"教学中的应用","definition":"the use of immediate feedback, small steps and earned rewards to build classroom learning","definitionCN":"用即时反馈、小步推进与应得的奖励来构建课堂学习","example":"Reinforcement theory shaped the drill software's step size.","exampleCN":"强化理论影响了练习软件每一步的大小。","why":"if consequences drive repetition, then instruction can be arranged as a sequence of consequences.","whyCN":"如果后果驱动重复，教学就能被安排成一串后果。"},{"no":"07","title":"Application in organisations","titleCN":"组织管理中的应用","definition":"the use of bonuses, recognition and removed burdens to sustain desired workplace behaviour","definitionCN":"用奖金、认可与卸除负担来维持理想职场行为的做法","example":"Reinforcement theory guided the shift from annual bonuses to weekly feedback.","exampleCN":"强化理论引导了从年度奖金到每周反馈的转变。","why":"work is a stream of repeated acts, so the same consequence logic applies to performance.","whyCN":"工作是一连串重复动作，因此同一套后果逻辑适用于绩效。"},{"no":"08","title":"Vicarious reinforcement","titleCN":"社会学习中的替代强化","definition":"the strengthening of a behaviour after seeing another person rewarded for it","definitionCN":"看到他人因某行为获奖赏后，自身该行为得到增强","example":"Vicarious reinforcement spread the new procedure through the team.","exampleCN":"替代强化使新流程在团队中扩散。","why":"the theory's logic extends to observation, since a watched reward can act as a consequence at one remove.","whyCN":"理论的逻辑延伸到观察，因为看到的奖赏可以作为隔了一层的后果起作用。"}],"etymology":{"intro":{"en":"The phrase joins reinforcement, from Latin fortis 'strong' through Old French, with theory, from Greek theoria 'a viewing'. Dates are approximate.","cn":"这个短语把 reinforcement 与 theory 组合起来；reinforcement 经古法语上溯拉丁 fortis「强壮」，theory 上溯希腊 theoria「观看」。年代为约数。"},"items":[{"era":"LATIN FORTIS","en":"Fortis meant 'strong, brave'. Old French fort 'strong' came from it, and the verb enforcir 'to strengthen' was built with the prefix en-.","cn":"fortis 意为「强壮、勇敢」。古法语 fort「强壮」由此而来，动词 enforcir「使强壮」则由前缀 en- 构成。"},{"era":"OLD FRENCH RENFORCIER","en":"Re- was added to enforcir to make renforcier 'to strengthen again, to make stronger'. The core is putting strength in, not doing something twice to a force.","cn":"enforcir 加上 re- 构成 renforcier「再使强壮、加强」。核心是「把力量注入」，而不是对一个力做两次。"},{"era":"ENGLISH REINFORCE","en":"English reinforce appeared in the fifteenth century, first for adding troops or strength to a position.","cn":"英语 reinforce 在 15 世纪出现，最初指给阵地增派兵力或加强力量。"},{"era":"GREEK THEORIA","en":"Theoria meant 'a viewing, contemplation', from theoros 'spectator', which is related to horan 'to see'. Latin borrowed theoria, and English theory came through Latin and French.","cn":"theoria 意为「观看、沉思」，来自 theoros「观看者」，与 horan「看见」相关。拉丁语借入 theoria，英语 theory 经拉丁与法语而来。"},{"era":"BEHAVIOURIST USE","en":"Psychology adopted reinforcement in the early twentieth century for the process that strengthens a response, and reinforcement theory named the framework from the mid-century.","cn":"心理学在 20 世纪初用 reinforcement 指增强反应的过程，强化理论则从 20 世纪中期起命名这一框架。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first use of the exact phrase): the label spread through textbooks and journals in the 1950s and 1960s, so no single first citation is settled; the pre-Latin origin of fortis is not established.","cn":"来源不确定（确切短语的首见）：这个标签在 1950 至 1960 年代经教科书与期刊扩散，没有公认的首次书证；fortis 在拉丁语之前的来源亦无定论。"}]},"similar":{"note":{"en":"Group one holds labels that sound like the same thing but come from different traditions; group two holds rival explanations of why behaviour repeats.","cn":"第一组是听起来像同一件事、却来自不同传统的标签；第二组是解释行为为何重复的对立说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"reinforcement learning","ipa":"/ˌriːɪnˈfɔːsmənt ˈlɜːnɪŋ/","tag":"machine learning","definition":"A computational method in which an agent learns from rewards; it borrows the vocabulary but not the psychology.","definitionCN":"智能体从奖励中学习的计算方法，借用了词汇，但不属于心理学。"},{"word":"operant conditioning","ipa":"/ˈɒpərənt kənˈdɪʃənɪŋ/","tag":"the process","definition":"The learning process itself; reinforcement theory is the explanatory framework built around it.","definitionCN":"指学习过程本身；强化理论是围绕它建立的解释框架。"},{"word":"reinforcement","ipa":"/ˌriːɪnˈfɔːsmənt/","tag":"one part of the name","definition":"The strengthening procedure or the stimulus that produces it; the phrase adds the theoretical frame.","definitionCN":"指增强程序或产生增强的刺激；短语则加上理论框架。"}]},{"heading":"NEAR MEANING","entries":[{"word":"social learning theory","ipa":"/ˌsəʊʃəl ˈlɜːnɪŋ ˈθɪəri/","tag":"observation first","definition":"The theory that people learn by watching models; it includes vicarious reinforcement but adds imitation.","definitionCN":"认为人通过观察榜样来学习的理论，包含替代强化，但加上模仿。"},{"word":"expectancy theory","ipa":"/ɪkˈspektənsi ˈθɪəri/","tag":"motivation, not repetition","definition":"A work-motivation theory based on expected outcomes; it predicts effort rather than the frequency of a learned act.","definitionCN":"基于预期结果的工作动机理论，预测努力程度，而非已学动作的频率。"},{"word":"punishment","ipa":"/ˈpʌnɪʃmənt/","tag":"the opposite consequence","definition":"A consequence that reduces a behaviour; reinforcement theory includes it, but the two are not interchangeable.","definitionCN":"减少某行为的后果；强化理论包含它，但两者不能互换。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real laboratory phrases, not invented rhymes.","cn":"正常联想：真实的构词成分、真实实验室搭配，而非编造的顺口溜。"},"normal":[{"en":"en- 'in' plus fort 'strong': reinforcement puts strength into a response.","cn":"en-「进入」加 fort「强壮」：强化就是把力量注入一个反应。"},{"en":"Theoria 'a viewing' plus -ia gives theory, so the phrase is a way of viewing consequences.","cn":"theoria「观看」加 -ia 构成 theory，因此这个短语是一种看待后果的方式。"},{"en":"The family runs reinforce, reinforcement, reinforcer, reinforcing.","cn":"同族词包括 reinforce、reinforcement、reinforcer、reinforcing。"},{"en":"Fixed pairs mark the framework: positive reinforcement, negative reinforcement, reinforcement schedule.","cn":"固定搭配标出框架：正强化、负强化、强化程式。"},{"en":"The essential contrast is punishment, which subtracts behaviour rather than adding it.","cn":"关键对照是 punishment，它削减行为，而非增加行为。"}],"abstract":[{"en":"Picture a lever, a falling food pellet and a tally sheet filling up.","cn":"想象一根杠杆、一颗落下的食丸，以及越写越密的计数纸。"},{"en":"Picture a path worn deeper each time someone walks it.","cn":"想象一条路，每有人走过就变深一点。"},{"en":"Picture a hand that removes a noise and thereby teaches a bird to sing.","cn":"想象一只手关掉噪声，却因此教会一只鸟唱歌。"}]},"examples":[{"en":"Reinforcement theory predicts that immediate rewards shape habits faster than delayed ones.","cn":"强化理论预测，即时奖励比延迟奖励更快塑造习惯。"},{"en":"The teacher applied reinforcement theory without naming it.","cn":"这位教师应用了强化理论，却没有点出它的名字。"},{"en":"Critics said reinforcement theory ignored what learners believed about the task.","cn":"批评者认为强化理论忽略了学习者对任务的看法。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"reinforcement（强化）+ theory（理论）＝ 强化理论；记「按下杠杆，食丸落下，动作越来越快」。","word":"reinforcement theory"},"root":"reinforce 经古法语 renforcier 上溯 en-（进入）+ fort（拉丁 fortis「强壮」），核心为「注入力量」；theory 经拉丁与法语上溯希腊 theoria「观看、沉思」。短语在 20 世纪中期心理学中定型。","sensesIntro":{"en":"Eight senses follow one pellet: the general claim, the two directions of adding and subtracting, the learning process, the timing rules, and the classroom, the office and the watched model.","cn":"八个义项沿着同一颗食丸展开：一般主张、加与减的两个方向、学习过程、时机规则，以及课堂、办公室与被观察的榜样。"},"semanticMap":{"core":{"en":"CORE IMAGE: a lever is pressed, a pellet falls, and the same press comes faster each minute.","cn":"核心意象：杠杆被按下，食丸落下，同一动作每一分钟都来得更快。"},"chain":["ACT","CONSEQUENCE","STRENGTH","FREQUENCY","SCHEDULE","TRANSFER"],"branches":[{"senses":"01","en":"THE CLAIM: consequences, not intentions, are said to govern how often an act returns.","cn":"主张：决定动作多久回来的是后果，而不是意图。"},{"senses":"02 · 03","en":"TWO DIRECTIONS: adding a reward and removing a burden both strengthen the act.","cn":"两个方向：加上奖励与移除负担都会强化动作。"},{"senses":"04 · 05","en":"MECHANISM AND TIMING: operant conditioning supplies the process, and schedules decide when it bites.","cn":"机制与时机：操作性条件作用提供过程，程式决定它何时起作用。"},{"senses":"06 · 07","en":"TWO WORKPLACES: classrooms and offices both arrange consequences to sustain repetition.","cn":"两个场所：课堂与办公室都安排后果以维持重复。"},{"senses":"08","en":"TRANSFER BY WATCHING: a reward seen on someone else works at one remove.","cn":"通过观察转移：在别人身上看到的奖励，隔一层也能起作用。"}]},"affixes":{"intro":{"en":"The phrase has two stems from two languages: a Germanic-rooted verb reinforced by Latin fortis, and a Greek noun for viewing.","cn":"这个短语有两个来自两种语言的词干：一个带拉丁 fortis 的日耳曼词根动词，以及一个表示「观看」的希腊名词。"},"latinIntro":{"en":"Latin fortis 'strong' gives Old French fort and enforcir, later renforcier; Greek theoria gives Latin theoria and English theory.","cn":"拉丁 fortis「强壮」给出古法语 fort 与 enforcir，后为 renforcier；希腊 theoria 给出拉丁 theoria 与英语 theory。"},"items":[{"word":"en-","structure":"en- (Old French prefix, from Latin in-)","meaning":"in; into","meaningCN":"进入；向内","example":"The prefix puts strength into the object.","exampleCN":"这个前缀把力量放进对象之中。"},{"word":"fortis","structure":"fortis, forte (Latin adjective)","meaning":"strong; brave","meaningCN":"强壮的；勇敢的","example":"The root also gives fortitude and fortify.","exampleCN":"这个词根还给出 fortitude 与 fortify。"},{"word":"enforcir","structure":"en- + fort (Old French verb)","meaning":"to strengthen","meaningCN":"使强壮；加强","example":"The verb is the base of the English word.","exampleCN":"这个动词是英语词的基底。"},{"word":"re-","structure":"re- (Old French prefix, 'again')","meaning":"again; further","meaningCN":"再次；进一步","example":"The prefix was added to enforcir, not to a noun force.","exampleCN":"这个前缀加在 enforcir 上，而不是加在名词 force 上。"},{"word":"reinforce","structure":"re- + enforcir (English verb)","meaning":"to strengthen; to give more support","meaningCN":"加强；增援","example":"The verb first described troops, then responses.","exampleCN":"这个动词先描述军队，后描述反应。"},{"word":"reinforcement","structure":"reinforce + -ment (action or result)","meaning":"the act or means of strengthening","meaningCN":"加强的行为或手段","example":"The noun became a technical term in psychology.","exampleCN":"这个名词在心理学中成为术语。"},{"word":"theoria","structure":"theoria (Greek noun, 'a viewing, contemplation')","meaning":"a viewing; contemplation","meaningCN":"观看；沉思","example":"Latin borrowed the noun unchanged in stem.","exampleCN":"拉丁语原样借入这个词干。"},{"word":"theory","structure":"theoria + English noun ending","meaning":"a systematic explanation","meaningCN":"系统的解释","example":"The noun moved from contemplation to explanation.","exampleCN":"这个名词从沉思转向解释。"},{"word":"-ment","structure":"-mentum (Latin noun suffix, via French -ment)","meaning":"action or result","meaningCN":"动作或结果","example":"The suffix turns the verb into a process noun.","exampleCN":"这个后缀把动词变成过程名词。"}],"latinEntries":[{"word":"fortis","structure":"fortis, forte (adjective, third declension)","meaning":"strong, brave","meaningCN":"强壮的；勇敢的"},{"word":"fortitudo","structure":"fortitudo, fortitudinis (f., third declension)","meaning":"strength, courage","meaningCN":"力量；勇气"},{"word":"theoria","structure":"theoria, theoriae (f., first declension, from Greek)","meaning":"a viewing, contemplation","meaningCN":"观看；沉思"},{"word":"theoreticus","structure":"theoreticus, theoretica, theoreticum (Late Latin adjective)","meaning":"contemplative, speculative","meaningCN":"沉思的；思辨的"}]}},{"word":"punishment","ipa_uk":"/ˈpʌnɪʃmənt/","ipa_us":"/ˈpʌnɪʃmənt/","definition_zh":"惩罚；刑罚；处罚；严厉对待：因过错而施加的痛苦或损失，也指行为主义中用以降低行为频率的后果","definition_en":"pain, loss or other hardship imposed for a fault, including the consequence used in behaviourism to make an act less frequent","core_image":"一只伸向热炉的手被烫得立刻缩回，炉子原地未动，退缩的是那只手","scene":"手刚碰到热炉边缘就猛地缩回，炉子原地未动。The punishment was immediate, and the child never reached for the stove again.","sceneCN":"这里指因过错而施加的痛苦后果（第 1 个义项：一般意义上的惩罚）；句意为惩罚来得即时，孩子此后再也没有伸手去碰炉子。","pos":[{"tag":"n.","zh":"惩罚；处罚（可数与不可数兼有）"},{"tag":"n.","zh":"刑罚；体罚（法律或行为主义用法）"}],"collocations":[{"phrase":"capital punishment","zh":"死刑"},{"phrase":"corporal punishment","zh":"体罚"},{"phrase":"impose a punishment","zh":"施加惩罚"},{"phrase":"a harsh punishment","zh":"严厉的惩罚"},{"phrase":"punishment and reward","zh":"惩罚与奖励"},{"phrase":"escape punishment","zh":"逃避惩罚"}],"forms":[{"label":"不可数用法","form":"punishment"},{"label":"复数（指具体处罚种类或次数）","form":"punishments"},{"label":"动词","form":"punish"},{"label":"形容词（惩罚性的）","form":"punitive"},{"label":"形容词（应受惩罚的）","form":"punishable"}],"derivatives":[{"word":"punish","pos":"v.","zh":"punire 去词尾 → 施加惩罚，语义保留「使付出代价」"},{"word":"punitive","pos":"adj.","zh":"punire + -ive（具有……性质的）→ 以惩罚为目的的"},{"word":"punishable","pos":"adj.","zh":"punish + -able（可……的）→ 可受惩罚的"},{"word":"punishing","pos":"adj.","zh":"punish + -ing（现在分词形容词）→ 令人疲惫不堪的，语义偏移为「折磨人的」"},{"word":"impunity","pos":"n.","zh":"in-（不） + poena（惩罚）→ 免受惩罚，词根相同而前缀相反"}],"senses":[{"no":"01","title":"Pain imposed for a fault","titleCN":"因过错而施加的痛苦或损失","definition":"something unpleasant imposed on a person because of a wrong or a broken rule","definitionCN":"因错误或违反规则而加在人身上的不快后果","example":"The punishment for the prank was a week without a bicycle.","exampleCN":"恶作剧的惩罚是一周不许骑车。","why":"Latin poena meant 'penalty, compensation', so punishment begins as a price paid for a wrong.","whyCN":"拉丁 poena 意为「罚金、补偿」，惩罚最初就是为过错付出的代价。"},{"no":"02","title":"A legal penalty","titleCN":"法律上的刑罚","definition":"a penalty imposed by a court for an offence, such as a fine, imprisonment or loss of rights","definitionCN":"法院对罪行施加的罚金、监禁或剥夺权利等处罚","example":"The punishment for the offence was reduced on appeal.","exampleCN":"该项罪行的刑罚在上诉后被减轻。","why":"law formalised the payment: the community takes something from the offender in return for the harm.","whyCN":"法律把这种偿付形式化：社群从违法者那里取走某物，以抵偿损害。"},{"no":"03","title":"A penalty under rules","titleCN":"规则之下的处罚","definition":"a penalty imposed within a game, school or workplace for breaking its rules","definitionCN":"在比赛、学校或工作场所内因违反规则而施加的处罚","example":"The referee's punishment was a penalty kick.","exampleCN":"裁判的处罚是一个点球。","why":"any rule-governed group needs a price for breaking rules, and the same word covers it.","whyCN":"任何受规则约束的群体都需要为违规定一个代价，同一个词便覆盖了它。"},{"no":"04","title":"Harsh treatment","titleCN":"严厉对待或虐待","definition":"rough, exhausting or cruel treatment that goes beyond any stated rule","definitionCN":"超出任何明文规则的粗暴、耗人或不人道对待","example":"The old boat took a punishment in every storm.","exampleCN":"这条旧船在每场风暴中都遭到重创。","why":"when no rule is stated, the word still names harm inflicted, and it extends to objects and bodies.","whyCN":"没有明文规则时，这个词仍指被施加的伤害，并扩展到物体与身体。"},{"no":"05","title":"The behaviourist consequence","titleCN":"行为主义中降低行为频率的后果","definition":"a consequence that makes a behaviour less likely to recur, in contrast with reinforcement","definitionCN":"使行为更不可能再次发生的后果，与强化相对","example":"The punishment reduced the number of late arrivals but also raised absenteeism.","exampleCN":"惩罚减少了迟到次数，却也提高了缺勤率。","why":"psychology needed the exact opposite of reinforcement, and it reused the everyday word for paying for a wrong.","whyCN":"心理学需要强化的精确对立面，便复用了这个表示「为过错付出代价」的日常词。"},{"no":"06","title":"Corporal punishment","titleCN":"体罚","definition":"physical punishment such as hitting, used especially of school or household discipline","definitionCN":"殴打等身体惩罚，尤指学校或家庭管教","example":"Corporal punishment was banned in the district's schools.","exampleCN":"该学区的学校禁止体罚。","why":"the body is the oldest surface on which a penalty is written, so the compound names that case directly.","whyCN":"身体是最古老的书写惩罚的表面，因此这个复合词直接命名那种情形。"},{"no":"07","title":"A financial penalty","titleCN":"经济处罚或罚款","definition":"a sum of money exacted for a violation, delay or breach of contract","definitionCN":"因违规、延误或违约而被收取的一笔钱","example":"The punishment for late filing was a fixed fee.","exampleCN":"逾期申报的处罚是一笔固定费用。","why":"poena was originally a payment, so a fine is the most literal modern descendant.","whyCN":"poena 原本就是一种付款，因此罚款是这个词最字面的现代后裔。"},{"no":"08","title":"Self-punishment","titleCN":"自我惩罚","definition":"harm a person inflicts on themselves out of guilt, shame or a sense of owed payment","definitionCN":"出于内疚、羞耻或「应当偿付」之感而对自己施加的伤害","example":"His punishment was to give up the thing he loved most.","exampleCN":"他的自我惩罚是放弃自己最爱的东西。","why":"if a wrong creates a debt, the debtor can be both the one who owes and the one who collects.","whyCN":"如果过错产生债务，欠债者与收债者可以是同一个人。"}],"etymology":{"intro":{"en":"Punishment comes from Latin poena 'penalty, compensation' through the verb punire and Old French. The ultimate source is Greek poine 'penalty, recompense'. Dates are approximate.","cn":"punishment 经动词 punire 与古法语上溯拉丁 poena「罚金、补偿」。其最终来源是希腊 poine「惩罚、报偿」。年代为约数。"},"items":[{"era":"GREEK POINE","en":"Poine meant 'penalty, recompense, blood-money'. The idea is payment for a wrong rather than correction of the offender.","cn":"poine 意为「惩罚、报偿、血金」。其观念是为过错付款，而不是矫正犯错者。"},{"era":"LATIN POENA","en":"Latin poena meant 'penalty, punishment, compensation'. It is the source of penal, penalty and impunity as well.","cn":"拉丁 poena 意为「罚金、惩罚、补偿」。它也是 penal、penalty 与 impunity 的来源。"},{"era":"LATIN PUNIRE","en":"Punire meant 'to punish, to avenge, to take vengeance for'. Its noun punitio named the act of punishing.","cn":"punire 意为「惩罚、报仇、为……复仇」。其名词 punitio 指惩罚行为。"},{"era":"OLD FRENCH","en":"Old French punir and punissement carried the legal sense into English from the twelfth century onward.","cn":"古法语 punir 与 punissement 从 12 世纪起把法律义带入英语。"},{"era":"ENGLISH PUNISHMENT","en":"English punishment covered both the legal penalty and the general infliction of pain, and later the rough wear that objects endure.","cn":"英语 punishment 兼指法律刑罚与一般施加的痛苦，后来又指物体承受的粗暴损耗。"},{"era":"RECONSTRUCTED ROOT","en":"Reconstructed form (pre-Greek root): poine is often attached to an Indo-European root for 'payment, price', but that root is a reconstruction and no single pre-Greek form is demonstrated; the Greek noun itself is attested.","cn":"重构形式（希腊语之前的词根）：poine 常被挂到印欧语「付款、价格」词根上，但该词根属重构，也没有单一的前希腊语形式得到证明；这个希腊名词本身有书证。"}]},"similar":{"note":{"en":"Group one holds legal and formal relatives that are easily confused with the general word; group two holds other imposed consequences with a different purpose.","cn":"第一组是易与通称混淆的法律与正式同族词；第二组是目的不同的其他施加性后果。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"penalty","ipa":"/ˈpenəlti/","tag":"the specific price","definition":"The specific disadvantage attached to a rule or offence, such as a fine; punishment is the wider act or institution.","definitionCN":"指规则或罪行所附的具体不利后果，如罚款；punishment 是更宽的行为或制度。"},{"word":"punitive","ipa":"/ˈpjuːnɪtɪv/","tag":"adjective of purpose","definition":"An adjective meaning 'intended to punish'; it describes the aim of a measure, not the measure itself.","definitionCN":"意为「以惩罚为目的」的形容词，描述措施的目的，而非措施本身。"},{"word":"impunity","ipa":"/ɪmˈpjuːnəti/","tag":"freedom from penalty","definition":"Exemption from punishment, built with a negative prefix on the same Latin root; it is the opposite condition.","definitionCN":"免受惩罚，在同一拉丁词根上加否定前缀，指相反的状态。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sanction","ipa":"/ˈsæŋkʃən/","tag":"official, often collective","definition":"A penalty imposed by an authority or by states; it is formal and often collective, while punishment can be personal.","definitionCN":"由权威或国家施加的处罚，正式且常为集体性；punishment 可以是个人性的。"},{"word":"retribution","ipa":"/ˌretrɪˈbjuːʃən/","tag":"payback in kind","definition":"Punishment understood as deserved payback; it stresses the balance of harm rather than the rule broken.","definitionCN":"被理解为应得报偿的惩罚，强调伤害的平衡，而非被违反的规则。"},{"word":"consequence","ipa":"/ˈkɒnsɪkwəns/","tag":"neutral outcome","definition":"Any result of an act, pleasant or not; it carries no judgment, whereas punishment implies a fault.","definitionCN":"任何行为的结果，好坏皆可，不带评判；punishment 则含有过错之意。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real legal collocations and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实法律搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"poena 'price paid': punishment is a price exacted for a wrong.","cn":"poena「付出的价钱」：惩罚就是为过错索取的价钱。"},{"en":"The family runs punish, punishment, punitive, punishable, impunity.","cn":"同族词包括 punish、punishment、punitive、punishable、impunity。"},{"en":"Legal phrases pin the formal sense: capital punishment, corporal punishment, impose a punishment.","cn":"法律搭配钉住正式义：死刑、体罚、施加惩罚。"},{"en":"The prefix in impunity is negative, so impunity is the absence of the price.","cn":"impunity 里的前缀是否定的，因此 impunity 就是没有这笔价钱。"},{"en":"The behaviourist pair is punishment and reward, moving frequency down and up.","cn":"行为主义的配对是惩罚与奖励，分别把频率往下与往上推。"}],"abstract":[{"en":"Picture a hand touching a hot stove and pulling back at once.","cn":"想象一只手碰到热炉，立刻缩回。"},{"en":"Picture a receipt handed over for a debt nobody wanted to pay.","cn":"想象一张收据，为一笔没人想付的债开出。"},{"en":"Picture a judge and an offender both holding the same coin.","cn":"想象法官与犯错者同时握着同一枚硬币。"}]},"examples":[{"en":"The punishment must fit the offence, the old principle runs.","cn":"古老的原则说，惩罚必须与罪行相称。"},{"en":"Punishment alone rarely teaches the behaviour that should replace it.","cn":"单靠惩罚很少能教会被替代的正确行为。"},{"en":"The fine was a punishment for late payment, not a fee for service.","cn":"这笔罚款是对迟付的惩罚，而非服务费。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"punish（惩罚）+ ment（名词）＝ 惩罚；记「手碰热炉，缩回的是手」。","word":"punishment"},"root":"希腊 poine「惩罚、报偿」→ 拉丁 poena「罚金、补偿」→ punire「惩罚」→ 古法语 punir／punissement。poine 的希腊语之前来源不确定，与印欧语「付款、价格」词根的联系属重构。","sensesIntro":{"en":"Eight senses follow one price: a wrong creates a debt, the court collects it, a rule collects it, a body pays it, and psychology and conscience each keep a ledger.","cn":"八个义项沿着同一笔价钱展开：过错产生一笔债，法庭来收，规则来收，身体来付，心理学与良心各自记着一本账。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand touches a hot stove, withdraws at once, and the stove has not moved.","cn":"核心意象：手碰到热炉，立刻缩回，炉子却原地未动。"},"chain":["WRONG","DEBT","COLLECTION","PAIN","REDUCTION","SELF"],"branches":[{"senses":"01","en":"THE PRICE: a fault creates something owed, and punishment is the payment demanded.","cn":"价钱：过错产生应偿之物，惩罚就是被索取的偿付。"},{"senses":"02 · 03","en":"TWO COLLECTORS: a court and a rule-governed group both exact the price.","cn":"两个收取者：法庭与受规则约束的群体都来收取这笔价钱。"},{"senses":"04 · 06","en":"THE BODY: rough treatment and corporal discipline write the penalty on a body.","cn":"身体：粗暴对待与体罚把惩罚写在身体上。"},{"senses":"05 · 07","en":"TWO LEDGERS: behaviourism lowers frequency, and a fine lowers the bank balance.","cn":"两本账：行为主义降低频率，罚款降低账户余额。"},{"senses":"08","en":"THE SELF: when the debtor and the collector are one person, the punishment turns inward.","cn":"自身：当欠债者与收债者同为一人，惩罚便转向内。"}]},"affixes":{"intro":{"en":"Punishment is a Latin root plus an English noun suffix, and the root also builds the legal family of penalty, punitive and impunity.","cn":"punishment 是拉丁词根加英语名词后缀，这个词根还构成 penalty、punitive 与 impunity 这一法律词族。"},"latinIntro":{"en":"Latin poena 'penalty' gives punire 'to punish' and punitio 'punishment'; the English suffix -ment names the act or its result.","cn":"拉丁 poena「罚金」给出 punire「惩罚」与 punitio「惩罚」；英语后缀 -ment 命名行为或其结果。"},"items":[{"word":"poena","structure":"poena (Latin noun, first declension)","meaning":"penalty; compensation","meaningCN":"罚金；补偿","example":"The noun is the root of penalty and impunity too.","exampleCN":"这个名词也是 penalty 与 impunity 的词根。"},{"word":"punire","structure":"punire, punivi, punitum (Latin verb, fourth conjugation)","meaning":"to punish; to avenge","meaningCN":"惩罚；复仇","example":"The verb carries the idea of collecting a debt.","exampleCN":"这个动词带着「收取债务」的意思。"},{"word":"punitio","structure":"punitio (Latin noun, -tio action suffix)","meaning":"a punishing","meaningCN":"惩罚行为","example":"The action noun is the Latin model behind the English word.","exampleCN":"这个动作名词是英语词背后的拉丁模板。"},{"word":"punish","structure":"punire + English verb ending","meaning":"to impose a penalty","meaningCN":"施加处罚","example":"The verb is the everyday member of the family.","exampleCN":"这个动词是词族中最日常的一员。"},{"word":"punishment","structure":"punish + -ment (action or result)","meaning":"the act or result of punishing","meaningCN":"惩罚的行为或结果","example":"The suffix turns the act into a countable thing.","exampleCN":"这个后缀把行为变成可计数之物。"},{"word":"punitive","structure":"punire + -ive (adjective)","meaning":"intended to punish","meaningCN":"以惩罚为目的的","example":"The adjective marks purpose rather than act.","exampleCN":"这个形容词标记目的，而非行为。"},{"word":"punishable","structure":"punish + -able (can be)","meaning":"liable to punishment","meaningCN":"可受惩罚的","example":"The suffix marks what the law can reach.","exampleCN":"这个后缀标记法律能触及的范围。"},{"word":"impunity","structure":"in- (not) + poena (penalty)","meaning":"freedom from punishment","meaningCN":"免受惩罚","example":"The negative prefix reverses the whole idea.","exampleCN":"否定前缀把整个观念反过来。"},{"word":"penalty","structure":"poenalis + -ty (English noun)","meaning":"a specific disadvantage for an offence","meaningCN":"对过错的具体不利后果","example":"The word is the countable cousin of punishment.","exampleCN":"这个词是 punishment 的可计数近亲。"}],"latinEntries":[{"word":"poena","structure":"poena, poenae (f., first declension)","meaning":"penalty, punishment, compensation","meaningCN":"罚金；惩罚；补偿"},{"word":"punire","structure":"punire, punivi, punitum (verb, fourth conjugation)","meaning":"to punish, avenge","meaningCN":"惩罚；复仇"},{"word":"punitio","structure":"punitio, punitionis (f., third declension)","meaning":"a punishing, punishment","meaningCN":"惩罚行为；惩罚"}]}},{"word":"reward","ipa_uk":"/rɪˈwɔːd/","ipa_us":"/rɪˈwɔːrd/","definition_zh":"奖赏；奖励；报酬；悬赏；回报：因行为或功绩而给予的酬劳，也指行为主义中增加行为频率的正强化物","definition_en":"something given in return for service, merit or a desired act, including the positive reinforcer used in behaviourism","core_image":"一只狗完成动作后得到一块肉干，尾巴立刻摇起来，下一次动作做得更快","scene":"狗完成动作后得到一块肉干，尾巴立刻摇起来，下一次动作明显更快。The trainer timed the reward so that the dog linked it to the right move.","sceneCN":"这里指因完成动作而给予的酬劳（第 1 个义项：一般意义上的奖赏）；句意为训练者把奖励的时机卡准，好让狗把它与正确的动作联系起来。","pos":[{"tag":"n.","zh":"奖赏；报酬；悬赏（可数）"},{"tag":"v.","zh":"奖赏；酬谢；给予回报"}],"collocations":[{"phrase":"a cash reward","zh":"现金奖励"},{"phrase":"offer a reward","zh":"提供悬赏"},{"phrase":"reward for effort","zh":"对努力的回报"},{"phrase":"reward and punishment","zh":"奖励与惩罚"},{"phrase":"a reward system","zh":"奖励制度"},{"phrase":"reap the rewards","zh":"收获回报"}],"forms":[{"label":"单数（名词）","form":"reward"},{"label":"复数（名词）","form":"rewards"},{"label":"动词原形","form":"reward"},{"label":"过去式","form":"rewarded"},{"label":"现在分词","form":"rewarding"},{"label":"形容词（有回报的）","form":"rewarding"}],"derivatives":[{"word":"rewarding","pos":"adj.","zh":"reward + -ing（现在分词形容词）→ 值得做的；给人满足的"},{"word":"rewardingly","pos":"adv.","zh":"rewarding + -ly（方式副词）→ 以令人有收获的方式"},{"word":"rewardable","pos":"adj.","zh":"reward + -able（可……的）→ 值得奖赏的"},{"word":"rewarder","pos":"n.","zh":"reward + -er（施动者）→ 给予奖赏的人"},{"word":"award","pos":"n./v.","zh":"同出古法语，但源词为 eswarder「审视、判定」→ 裁定给予的奖项，语义与 reward 分道"}],"senses":[{"no":"01","title":"Something given for service or merit","titleCN":"因服务或功绩而给予的奖赏","definition":"something valuable given to a person in return for work, help or good conduct","definitionCN":"为工作、帮助或良好表现而给予某人的有价值之物","example":"The neighbours gave him a small reward for finding the dog.","exampleCN":"邻居给了他一小笔奖赏，因为他找到了狗。","why":"the word began as 'regard', so a reward is first the act of looking favourably on someone, then what that look gives.","whyCN":"这个词最初是「看重」，因此奖赏先是看重某人的行为，然后才是这份看重所给的东西。"},{"no":"02","title":"Payment for work","titleCN":"劳动所得的报酬","definition":"money or goods received as payment for labour or a service","definitionCN":"作为劳动或服务报酬而收到的钱或物","example":"The reward for the whole season's work was modest.","exampleCN":"整季工作的报酬并不高。","why":"when labour is exchanged rather than honoured, the same word names the wage side of the exchange.","whyCN":"当劳动是被交换而非被表彰时，同一个词就命名交换中工资的那一面。"},{"no":"03","title":"A bounty offered","titleCN":"为寻物或缉凶提供的悬赏","definition":"a sum offered publicly to anyone who finds a lost thing, a missing person or an offender","definitionCN":"公开向找到失物、失踪者或罪犯者提供的赏金","example":"A reward of fifty pounds was posted for the missing ring.","exampleCN":"为那枚丢失的戒指悬赏五十英镑。","why":"a public offer turns the private thank-you into a contract that anyone may claim.","whyCN":"公开悬赏把私下的感谢变成任何人都可主张的契约。"},{"no":"04","title":"A return or benefit","titleCN":"抽象的回报或收益","definition":"the benefit that follows from an effort, investment or risk, not necessarily given by anyone","definitionCN":"由努力、投资或风险带来的收益，未必由某人给予","example":"The reward for patience was a far better view.","exampleCN":"耐心的回报是远更好的视野。","why":"once the giver fades, the word names whatever good comes back from what was done.","whyCN":"给予者淡出后，这个词就指所做之事换回的任何好处。"},{"no":"05","title":"A positive reinforcer","titleCN":"行为主义中的正强化物","definition":"a stimulus delivered after a behaviour that makes the behaviour more likely to recur","definitionCN":"行为之后给予的刺激，使该行为更可能再次发生","example":"The pellet was the reward that kept the lever press going.","exampleCN":"食丸是让按杠杆动作持续下去的奖励。","why":"behaviourism needed an observable thing that raises frequency, and a reward is exactly such a thing.","whyCN":"行为主义需要一个可观察、能提高频率的东西，奖励正是这样的东西。"},{"no":"06","title":"Intrinsic satisfaction","titleCN":"内在的心理满足","definition":"the pleasure or sense of worth that comes from the activity itself rather than from an external prize","definitionCN":"来自活动本身而非外部奖品的愉悦或价值感","example":"For the translator, the reward was the sentence finally working.","exampleCN":"对这位译者来说，回报是那句话终于通顺了。","why":"if a return can be internal, then no giver is required, and the word reaches the private feeling of worth.","whyCN":"如果回报可以是内在的，就不需要给予者，这个词便抵达私人的价值感。"},{"no":"07","title":"A prize or bonus","titleCN":"具体的奖品或奖金","definition":"a tangible prize, bonus or award handed over on a defined occasion","definitionCN":"在特定场合交付的有形奖品、奖金或奖励","example":"The annual reward for the best essay was a book token.","exampleCN":"最佳文章的年度奖励是一张购书券。","why":"institutions like to make the return visible, so the abstract reward becomes an object on a table.","whyCN":"机构喜欢把回报做得可见，抽象的奖赏因此变成桌上的一件实物。"},{"no":"08","title":"A requital or thank-you","titleCN":"报答或酬谢","definition":"an act of returning kindness or help, often without material value","definitionCN":"回敬善意或帮助的行为，常不含物质价值","example":"Her reward for their kindness was a standing invitation.","exampleCN":"她对他们善意的报答是一份长期有效的邀请。","why":"the oldest layer is social: a look of regard returned, which need not be counted in money.","whyCN":"最古老的一层是社交性的：回以一个看重的目光，不必用钱计算。"}],"etymology":{"intro":{"en":"Reward came into English from Old North French rewarder 'to regard, to look at', built on a Germanic root for guarding and watching. The modern sense of payment grew out of 'regard'. Dates are approximate.","cn":"reward 经古北法语 rewarder「看重、注视」进入英语，其词根是日耳曼语中表示「守护、看视」的词。现代「酬劳」义由「看重」生长出来。年代为约数。"},"items":[{"era":"FRANKISH WARDON","en":"The Germanic verb *wardon meant 'to guard, to watch over'. It also produced English ward, warden and guard, all through different routes.","cn":"日耳曼动词 *wardon 意为「守护、看视」。它还经不同路径产生英语 ward、warden 与 guard。"},{"era":"OLD NORTH FRENCH","en":"Old North French warder meant 'to guard, to watch', and rewarder added re- to mean 'to regard, to look at attentively'.","cn":"古北法语 warder 意为「守护、看视」，rewarder 加上 re- 后意为「看重、专注地看」。"},{"era":"MIDDLE ENGLISH REGARD","en":"Middle English reward first meant 'regard, attention, a look', a sense now carried by regard rather than reward.","cn":"中古英语 reward 最初意为「看重、注意、一瞥」，这一义如今由 regard 而非 reward 承担。"},{"era":"SHIFT TO RECOMPENSE","en":"From 'holding someone in regard' the word moved to 'showing that regard by a gift or payment', and by the fourteenth century the payment sense dominated.","cn":"从「看重某人」转向「以礼物或钱款表示这份看重」，到 14 世纪，酬劳义已占主导。"},{"era":"MODERN EXTENSIONS","en":"English extended reward to bounties, wages, prizes and, in the twentieth century, to the positive reinforcer of behaviourism.","cn":"英语把 reward 扩展到悬赏、工资、奖品，并在 20 世纪扩展到行为主义的正强化物。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (exact route of the sense shift): the steps from 'a look of regard' to 'a payment' are not documented in detail, and the first date of the payment sense is approximate.","cn":"来源不确定（语义转移的确切路径）：从「看重的目光」到「付款」的步骤缺乏细致书证，酬劳义的首见年代为约数。"}]},"similar":{"note":{"en":"Group one holds words that look close to reward but come from another stem or mean another thing; group two holds other returns for effort.","cn":"第一组是形近但词干不同或所指不同的词；第二组是努力换来的其他回报。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"award","ipa":"/əˈwɔːd/","tag":"a judged decision","definition":"Something granted by a judge, committee or court after deliberation; it comes from a different Old French verb meaning 'to judge'.","definitionCN":"由法官、委员会或法庭审议后授予之物，来自另一个意为「判定」的古法语动词。"},{"word":"reword","ipa":"/riːˈwɜːd/","tag":"to rephrase","definition":"To express something in different words; the re- here means 'again', and there is no connection with payment.","definitionCN":"用不同措辞表达某物；这里的 re- 意为「再次」，与酬劳无关。"},{"word":"rewarding","ipa":"/rɪˈwɔːdɪŋ/","tag":"adjective of worth","definition":"An adjective meaning 'giving satisfaction'; it describes the experience, not the thing handed over.","definitionCN":"意为「给人满足」的形容词，描述体验，而非交付之物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"prize","ipa":"/praɪz/","tag":"competition trophy","definition":"Something won in a contest or lottery; a reward may be given without any competition.","definitionCN":"在竞赛或抽奖中赢得之物；reward 可以在没有竞赛的情况下给予。"},{"word":"bonus","ipa":"/ˈbəʊnəs/","tag":"extra payment","definition":"An extra sum added to normal pay, usually for performance; it is narrower and always monetary or near-monetary.","definitionCN":"在正常报酬之外加给的一笔钱，通常因绩效而给，范围更窄且总与钱相关。"},{"word":"incentive","ipa":"/ɪnˈsentɪv/","tag":"motive offered in advance","definition":"Something offered before an act to make people choose it; a reward typically comes after the act.","definitionCN":"在行动之前提供、使人选择该行动的东西；reward 通常在行动之后到来。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real policy collocations and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实制度搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"ward 'watch' plus re- 'back': to reward is first to look back at someone with favour.","cn":"ward「看视」加 re-「回」：奖赏最初是回以赞许的目光。"},{"en":"The family runs reward, rewarding, rewardingly, rewardable, rewarder.","cn":"同族词包括 reward、rewarding、rewardingly、rewardable、rewarder。"},{"en":"Institutional phrases pin the sense: cash reward, offer a reward, a reward system.","cn":"制度搭配钉住词义：现金奖励、提供悬赏、奖励制度。"},{"en":"The pair reward and punishment moves frequency up and down.","cn":"reward 与 punishment 这一对把频率往上与往下推。"},{"en":"The look-alike to watch is award, which comes from a verb meaning 'to judge'.","cn":"要留意的形近词是 award，它来自意为「判定」的动词。"}],"abstract":[{"en":"Picture a dog finishing a trick and a piece of dried meat appearing.","cn":"想象一只狗完成动作，一块肉干随即出现。"},{"en":"Picture a smile returned across a street, with nothing bought or sold.","cn":"想象街对面回以一个微笑，没有买卖发生。"},{"en":"Picture a coin that only appears after the work is finished.","cn":"想象一枚只在工作完成后才出现的硬币。"}]},"examples":[{"en":"The company offered a reward for information about the leak.","cn":"公司为泄漏事件的相关信息提供悬赏。"},{"en":"Teaching is rewarding even when the pay is not.","cn":"教学即使报酬不高，本身也给人满足。"},{"en":"A reward delivered too late teaches nothing.","cn":"来得太晚的奖励教不会任何东西。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"re（回）+ ward（看视）＝ 回以看重，即奖赏；记「动作完成，肉干出现」。","word":"reward"},"root":"古北法语 rewarder「看重、注视」，由 re- 加 warder「守护、看视」，词根为日耳曼 *wardon；语义由「看重」转为「以财物表示看重」。无拉丁同族。","sensesIntro":{"en":"Eight senses follow one glance: regard becomes a gift, the gift becomes a wage, a public bounty, a benefit, a pellet, a private satisfaction, a prize and a thank-you.","cn":"八个义项沿着同一道目光展开：看重变成礼物，礼物变成工资、公开悬赏、收益、食丸、私人的满足、奖品与一句答谢。"},"semanticMap":{"core":{"en":"CORE IMAGE: a dog completes a trick and a piece of dried meat appears at once.","cn":"核心意象：狗完成一个动作，一块肉干立刻出现。"},"chain":["REGARD","RETURN","PAYMENT","OFFER","BENEFIT","SATISFACTION"],"branches":[{"senses":"01 · 08","en":"THE GLANCE: giving a reward begins as looking favourably on someone and returning that regard.","cn":"目光：给予奖赏始于看重某人，并把这份看重还回去。"},{"senses":"02 · 07","en":"THE OBJECT: a wage and a prize are the return made countable and visible.","cn":"实物：工资与奖品是把回返变成可计数、可见的东西。"},{"senses":"03","en":"THE PUBLIC OFFER: a bounty turns private thanks into a claim anyone may make.","cn":"公开悬赏：赏金把私下的感谢变成人人可主张的权利。"},{"senses":"04 · 06","en":"THE INWARD RETURN: benefit and satisfaction need no giver at all.","cn":"向内的回返：收益与满足根本不需要给予者。"},{"senses":"05","en":"THE PELLET: behaviourism reduces the whole idea to one observable reinforcer.","cn":"食丸：行为主义把整个观念压缩成一个可观察的强化物。"}]},"affixes":{"intro":{"en":"Reward is a Germanic root that reached English through French, so its affixes are French and Germanic rather than Latin.","cn":"reward 是经法语进入英语的日耳曼词根，因此其词缀属于法语与日耳曼语，而非拉丁语。"},"latinIntro":{"en":"There is no Latin root behind reward; the closest Latin-looking relatives in English, such as regard, came through the same French route.","cn":"reward 背后没有拉丁词根；英语中看似拉丁的近亲如 regard，也是经同一条法语路径而来。"},"items":[{"word":"*wardon","structure":"*wardon (Frankish verb, 'to guard, watch')","meaning":"to guard; to watch","meaningCN":"守护；看视","example":"The root also underlies ward, warden and guard.","exampleCN":"这个词根也支撑 ward、warden 与 guard。"},{"word":"warder","structure":"warder (Old North French verb, 'to guard')","meaning":"to guard; to watch","meaningCN":"守护；看视","example":"The French verb carried the root into English.","exampleCN":"这个法语动词把词根带入英语。"},{"word":"re-","structure":"re- (Old French prefix, 'back, again')","meaning":"back","meaningCN":"回；向后","example":"The prefix turns watching into looking back with favour.","exampleCN":"这个前缀把看视变成回以赞许的目光。"},{"word":"rewarder","structure":"re- + warder (Old North French verb)","meaning":"to regard; to look at","meaningCN":"看重；注视","example":"The French verb is the direct source of the English word.","exampleCN":"这个法语动词是英语词的直接来源。"},{"word":"reward","structure":"reward (English noun and verb)","meaning":"a return for service or merit","meaningCN":"对服务或功绩的回报","example":"The word shifted from regard to payment.","exampleCN":"这个词从「看重」转向「酬劳」。"},{"word":"rewarding","structure":"reward + -ing (adjective)","meaning":"giving satisfaction","meaningCN":"给人满足的","example":"The adjective describes the experience, not the payment.","exampleCN":"这个形容词描述体验，而非付款。"},{"word":"rewardable","structure":"reward + -able (can be)","meaning":"deserving a reward","meaningCN":"值得奖赏的","example":"The suffix marks worthiness.","exampleCN":"这个后缀标记值得。"},{"word":"rewarder","structure":"reward + -er (agent)","meaning":"one who rewards","meaningCN":"给予奖赏的人","example":"The agent noun is rare but regular.","exampleCN":"这个施动名词罕见但合乎规则。"},{"word":"ward","structure":"ward (English noun and verb, same Germanic root)","meaning":"guard; a guarded division","meaningCN":"守护；受守护的区划","example":"It shows the root without the French prefix.","exampleCN":"它展示了不带法语前缀的词根。"}],"latinEntries":[]}},{"word":"conditioned","ipa_uk":"/kənˈdɪʃənd/","ipa_us":"/kənˈdɪʃənd/","definition_zh":"条件化的；习得的；有条件的；受制约的；经调节处理的：经反复训练形成固定联结的，也指受环境或条件限制的","definition_en":"shaped by repeated training into a fixed association, or limited by conditions, or treated so as to reach a stable state","core_image":"同一盏灯亮起第三次，狗还没闻到食物就先把头转向食盆，灯光与食物在它脑中已经绑在一起","scene":"灯第三次亮起，狗还没闻到食物就把头转向食盆，灯光与食物已经绑在一起。The conditioned response appeared before any food was presented.","sceneCN":"这里指经反复配对训练形成的固定反应（第 1 个义项：条件反射的）；句意为条件反应在任何食物出现之前就已发生。","pos":[{"tag":"adj.","zh":"条件化的；习得的（经训练形成）"},{"tag":"adj.","zh":"有条件的；受制约的"},{"tag":"adj.","zh":"经调节处理的（空气、头发等）"}],"collocations":[{"phrase":"a conditioned response","zh":"条件反应"},{"phrase":"a conditioned reflex","zh":"条件反射"},{"phrase":"conditioned air","zh":"调节过的空气"},{"phrase":"conditioned hair","zh":"用过护发素的头发"},{"phrase":"socially conditioned behaviour","zh":"受社会环境制约的行为"},{"phrase":"conditioned by circumstance","zh":"受环境条件限制"}],"forms":[{"label":"原形（动词）","form":"condition"},{"label":"过去式","form":"conditioned"},{"label":"过去分词","form":"conditioned"},{"label":"现在分词","form":"conditioning"},{"label":"名词（条件）","form":"condition"}],"derivatives":[{"word":"condition","pos":"n./v.","zh":"condicio「约定、状况」→ 条件；使适应，是 -ed 形式的 base"},{"word":"conditioning","pos":"n.","zh":"condition + -ing（动名词）→ 条件作用；训练过程"},{"word":"conditioner","pos":"n.","zh":"condition + -er（施动者或制剂）→ 调节剂；护发素"},{"word":"conditional","pos":"adj.","zh":"condition + -al（与……有关的）→ 有条件的；附条件的"},{"word":"unconditioned","pos":"adj.","zh":"un-（不） + conditioned → 未经条件训练的，语义与 conditioned 相反"}],"senses":[{"no":"01","title":"Shaped into a fixed association","titleCN":"经训练形成固定联结的条件反应","definition":"describing a response that has been made to follow a new cue through repeated pairing","definitionCN":"描述经反复配对、已能跟随新提示出现的反应","example":"The conditioned response came before the food itself.","exampleCN":"条件反应在食物本身出现之前就到来了。","why":"condition here means 'to bring into a required state', so the participle describes a response that training has put into that state.","whyCN":"这里的 condition 意为「使进入某种所需状态」，因此分词描述被训练带入该状态的反应。"},{"no":"02","title":"Learned or shaped by practice","titleCN":"经练习塑造而成的","definition":"describing behaviour or a habit formed by repeated experience rather than by nature","definitionCN":"描述由反复经验而非天性形成的行为或习惯","example":"His conditioned politeness survived even in the argument.","exampleCN":"他被训练出的礼貌即使在争吵中也还在。","why":"the same idea leaves the laboratory: any repeated shaping produces a conditioned way of acting.","whyCN":"同一观念离开实验室：任何反复塑造都会产生一种被条件化的行事方式。"},{"no":"03","title":"Limited by conditions","titleCN":"有条件的、受前提限制的","definition":"dependent on stated terms, so that it holds only if certain things are true","definitionCN":"取决于明文条件，只有在某些事情成立时才有效","example":"The offer was conditioned on a two-year commitment.","exampleCN":"这项提议以两年承诺为条件。","why":"this sense comes from the noun condition as a stipulation, not from the laboratory, and the participle marks the dependency.","whyCN":"这一义来自作「约定」解的名词 condition，而非实验室，分词标记的正是这种依赖关系。"},{"no":"04","title":"Shaped by social circumstances","titleCN":"受社会或环境条件制约的","definition":"describing health, behaviour or opportunity as produced by social and material conditions","definitionCN":"描述健康、行为或机会由社会与物质条件造成","example":"The report treated obesity as a socially conditioned outcome.","exampleCN":"报告把肥胖视为受社会条件制约的结果。","why":"if circumstances are conditions, then what they produce can be described as conditioned by them.","whyCN":"如果环境是条件，那么由环境产生的东西就可以说成受这些条件制约。"},{"no":"05","title":"Air or space brought to a set state","titleCN":"经调节处理的空气或空间","definition":"describing air, a room or a building whose temperature and humidity have been regulated","definitionCN":"描述温度与湿度已被调节的空气、房间或建筑","example":"The archive was kept in conditioned air day and night.","exampleCN":"档案库昼夜保持在调节过的空气中。","why":"the technical verb condition means 'to bring to the required state', and air is one of its commonest objects.","whyCN":"技术动词 condition 意为「使达到所需状态」，空气是它最常见的对象之一。"},{"no":"06","title":"Hair or skin treated with a product","titleCN":"用护发或护肤产品处理过的","definition":"describing hair or skin that has been treated with a conditioning product to improve its feel","definitionCN":"描述用护发或护肤产品处理过、触感改善的头发或皮肤","example":"Her conditioned hair held the style far better.","exampleCN":"她用过护发素的头发更能保持发型。","why":"the cosmetic industry borrowed the technical verb and kept the same 'brought to a better state' logic.","whyCN":"化妆品行业借用了这个技术动词，保留同一套「使达到更好状态」的逻辑。"},{"no":"07","title":"A body trained to a level","titleCN":"经训练达到某种状态的身体","definition":"describing an athlete or an animal whose body has been brought to a required level of fitness","definitionCN":"描述身体已被训练到所需体能水平的运动员或动物","example":"The conditioned horse finished the long race strongly.","exampleCN":"这匹经过训练的马有力地跑完了长距离赛。","why":"training is a process of bringing a body into condition, and the participle names the result.","whyCN":"训练是把身体带入某种状态的过程，分词命名的是结果。"},{"no":"08","title":"Material brought to a stable state","titleCN":"经处理达到稳定状态的材料","definition":"describing wood, soil or another material prepared so that it will behave predictably","definitionCN":"描述经过预备、能按预期表现行动的木材、土壤或其他材料","example":"Only conditioned timber was used for the floor.","exampleCN":"地板只用了经过稳定处理的木材。","why":"the engineering sense generalises the verb: any material can be brought into a required condition.","whyCN":"工程义把动词一般化：任何材料都能被带入所需状态。"}],"etymology":{"intro":{"en":"Conditioned is the past participle of condition, from Latin condicio 'agreement, stipulation, condition'. A second Latin spelling, conditio, was confused with it. Dates are approximate.","cn":"conditioned 是 condition 的过去分词，condition 来自拉丁 condicio「约定、规定、状况」。另一个拉丁拼写 conditio 与它长期混用。年代为约数。"},"items":[{"era":"LATIN DICERE","en":"Dicere meant 'to say, declare'. In compounds it supplied the act of stating terms aloud.","cn":"dicere 意为「说、宣告」。在复合词中，它提供把条款说出口的行为。"},{"era":"LATIN CONDICERE","en":"Com- 'together' plus dicere gave condicere 'to speak together, to agree upon', hence to fix terms by agreement.","cn":"com-「共同」加 dicere 构成 condicere「共同商谈、商定」，因此指通过约定确定条款。"},{"era":"LATIN CONDICIO","en":"The noun condicio meant 'agreement, stipulation, condition, rank'. A near-homonym conditio, from condere 'to establish', was often written the same way.","cn":"名词 condicio 意为「约定、条款、状况、身份」。近音词 conditio 来自 condere「建立、安置」，常被写成同一形式。"},{"era":"OLD FRENCH AND ENGLISH","en":"Old French condition carried the noun into English in the thirteenth century, first as a stipulation and later as a state of being.","cn":"古法语 condition 在 13 世纪把名词带入英语，最初指约定条款，后来指存在状态。"},{"era":"TECHNICAL AND LEARNED USES","en":"From the seventeenth century condition was used as a verb meaning 'to bring into a required state', which produced conditioned air, conditioned hair and conditioned timber.","cn":"从 17 世纪起，condition 作动词使用，意为「使达到所需状态」，由此产生调节空气、护发与稳定木材等用法。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (relation of the two Latin nouns): the merging of condicio and conditio is disputed in detail, so the exact line from 'agreement' to 'state' is not fully documented; the first use of conditioned in the psychological sense is also approximate.","cn":"来源不确定（两个拉丁名词的关系）：condicio 与 conditio 的合并细节有争议，从「约定」到「状态」的确切线索缺乏完整书证；conditioned 心理义的首见亦为约数。"}]},"similar":{"note":{"en":"Group one holds forms of the same stem that are constantly confused; group two holds adjectives for behaviour that is shaped, fixed or restricted.","cn":"第一组是同词干、最常被混淆的形式；第二组是描述行为被塑造、固定或受限的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"conditional","ipa":"/kənˈdɪʃənəl/","tag":"dependent on terms","definition":"An adjective meaning 'depending on a condition'; it belongs to grammar, law and logic rather than to training.","definitionCN":"意为「取决于条件」的形容词，属于语法、法律与逻辑，而非训练。"},{"word":"conditioning","ipa":"/kənˈdɪʃənɪŋ/","tag":"the process","definition":"The process of training or regulating; it is a noun, while conditioned describes the result.","definitionCN":"训练或调节的过程，是名词，而 conditioned 描述结果。"},{"word":"unconditioned","ipa":"/ˌʌnkənˈdɪʃənd/","tag":"the opposite","definition":"Not produced by training, as in an unconditioned reflex; the negative prefix marks the natural response.","definitionCN":"非由训练产生的，如无条件反射；否定前缀标记天生反应。"}]},{"heading":"NEAR MEANING","entries":[{"word":"trained","ipa":"/ˈtreɪnd/","tag":"deliberate practice","definition":"Shaped by explicit instruction or drill; conditioned stresses the automatic pairing rather than the teaching.","definitionCN":"经明确指导或反复操练塑造；conditioned 强调自动联结，而非教学。"},{"word":"habitual","ipa":"/həˈbɪtjuəl/","tag":"done by habit","definition":"Done regularly until it feels normal; it names frequency, while conditioned names the cause of the association.","definitionCN":"因经常重复而显得自然，命名频率；conditioned 命名联结的成因。"},{"word":"constrained","ipa":"/kənˈstreɪnd/","tag":"held within limits","definition":"Forced or limited by external pressure; it fits the third sense of conditioned, not the laboratory one.","definitionCN":"受外部压力强迫或限制，对应 conditioned 的第三个义项，而非实验室义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real technical collocations and real word relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实技术搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"condicere 'agree upon terms': a conditioned response is one whose terms have been fixed by training.","cn":"condicere「商定条款」：条件反应就是条款被训练固定的反应。"},{"en":"The family runs condition, conditioned, conditioning, conditioner, conditional, unconditioned.","cn":"同族词包括 condition、conditioned、conditioning、conditioner、conditional、unconditioned。"},{"en":"Fixed pairs pin the laboratory: conditioned response, conditioned reflex.","cn":"固定搭配钉住实验室用法：条件反应、条件反射。"},{"en":"Everyday compounds pin the technical verb: conditioned air, conditioned hair, conditioned timber.","cn":"日常复合词钉住技术动词：调节空气、护发、稳定木材。"},{"en":"The opposite is unconditioned, the response that needed no training.","cn":"对立面是 unconditioned，即无需训练的反应。"}],"abstract":[{"en":"Picture a lamp and a food bowl joined by a thread nobody can see.","cn":"想象一盏灯与一只食盆被一根看不见的线连起来。"},{"en":"Picture a door that opens to a particular knock and to no other.","cn":"想象一扇门只对某一种敲门声打开。"},{"en":"Picture a room whose air has been taught to stay the same.","cn":"想象一间屋子的空气被教会保持不变。"}]},"examples":[{"en":"The conditioned reflex faded when the pairings stopped.","cn":"配对停止后，条件反射逐渐消退。"},{"en":"The greenhouse uses conditioned air to protect the seedlings.","cn":"温室用调节过的空气保护幼苗。"},{"en":"Her response was conditioned by years of narrow training.","cn":"她的反应被多年狭窄的训练所塑造。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"condition（条件）+ ed（被……的）＝ 被条件化的；记「灯亮第三次，狗已转向食盆」。","word":"conditioned"},"root":"拉丁 com-「共同」+ dicere「说、宣告」→ condicere「商定」，名词 condicio「约定、状况」；近音词 conditio 长期混写。英语 condition 加 -ed，17 世纪起有「使达到所需状态」的技术义。","sensesIntro":{"en":"Eight senses follow one fixing of terms: training fixes an association, then the term spreads to stipulations, social circumstances, air, hair, bodies and materials.","cn":"八个义项沿着同一次「定下条款」展开：训练固定一个联结，随后这个词扩展到约定、社会环境、空气、头发、身体与材料。"},"semanticMap":{"core":{"en":"CORE IMAGE: a lamp switches on for the third time and the dog turns to the bowl before food appears.","cn":"核心意象：灯第三次亮起，狗在食物出现之前就转向食盆。"},"chain":["TERMS","TRAINING","ASSOCIATION","AUTOMATIC","REGULATION","LIMITATION"],"branches":[{"senses":"01","en":"THE LABORATORY: repeated pairing fixes a new cue to an old response.","cn":"实验室：反复配对把新提示固定到旧反应上。"},{"senses":"02","en":"THE HABIT: the same fixing happens outside the laboratory, in manners and routines.","cn":"习惯：同一种固定也发生在实验室之外，进入举止与日常程序。"},{"senses":"03 · 04","en":"THE TERMS AND THE WORLD: a stipulation limits an offer, and social conditions limit an outcome.","cn":"条款与世界：约定限制一项提议，社会条件限制一个结果。"},{"senses":"05 · 06","en":"BROUGHT TO A STATE: air and hair are both regulated until they behave as wanted.","cn":"被带入状态：空气与头发都被调节到按所需方式表现。"},{"senses":"07 · 08","en":"BODY AND MATERIAL: a trained body and stabilised timber reach the condition required of them.","cn":"身体与材料：受过训练的身体与稳定化的木材都达到所需状态。"}]},"affixes":{"intro":{"en":"Conditioned is a Latin noun turned into an English verb and then into a participle, so the whole family can be read from one root and one ending.","cn":"conditioned 是拉丁名词变成英语动词、再变成分词的结果，因此整个词族可由一个词根与一个词尾读出。"},"latinIntro":{"en":"Latin com- and dicere build condicere and condicio; English adds -ion, -al and -ed, while un- reverses the training sense.","cn":"拉丁 com- 与 dicere 构成 condicere 与 condicio；英语加上 -ion、-al 与 -ed，而 un- 反转训练义。"},"items":[{"word":"com-","structure":"com- (Latin prefix, 'together')","meaning":"together","meaningCN":"共同","example":"The prefix marks terms agreed between parties.","exampleCN":"这个前缀标记各方共同商定的条款。"},{"word":"dicere","structure":"dicere, dixi, dictum (Latin verb, third conjugation)","meaning":"to say; to declare","meaningCN":"说；宣告","example":"The root also gives dictate and dictionary.","exampleCN":"这个词根还给出 dictate 与 dictionary。"},{"word":"condicere","structure":"com- + dicere (Latin verb)","meaning":"to agree upon, stipulate","meaningCN":"商定；规定","example":"The verb is the source of the noun condition.","exampleCN":"这个动词是名词 condition 的来源。"},{"word":"condicio","structure":"condicio (Latin noun, third declension)","meaning":"agreement; stipulation; condition","meaningCN":"约定；条款；状况","example":"A second spelling, conditio, was often confused with it.","exampleCN":"另一个拼写 conditio 常与它混用。"},{"word":"condition","structure":"condition (English noun and verb)","meaning":"a state or a stipulated term","meaningCN":"状态或规定的条款","example":"The verb sense 'to bring to a state' appears in the seventeenth century.","exampleCN":"「使达到某状态」的动词义在 17 世纪出现。"},{"word":"conditioned","structure":"condition + -ed (past participle)","meaning":"brought into a required state","meaningCN":"被带入所需状态","example":"The participle serves both the laboratory and the technical verb.","exampleCN":"这个分词兼用于实验室与技术动词。"},{"word":"conditioning","structure":"condition + -ing (gerund)","meaning":"the process of shaping or regulating","meaningCN":"塑造或调节的过程","example":"The gerund names the process behind the participle.","exampleCN":"这个动名词命名分词背后的过程。"},{"word":"conditioner","structure":"condition + -er (agent or preparation)","meaning":"a preparation that improves condition","meaningCN":"改善状态的制剂","example":"The agent suffix produced the hair product.","exampleCN":"这个施动后缀产生了护发产品之名。"},{"word":"unconditioned","structure":"un- + conditioned (negative prefix)","meaning":"not produced by training","meaningCN":"非由训练产生的","example":"The prefix marks the natural counterpart.","exampleCN":"这个前缀标记天生的对应项。"}],"latinEntries":[{"word":"dicere","structure":"dicere, dixi, dictum (verb, third conjugation)","meaning":"to say, declare","meaningCN":"说；宣告"},{"word":"condicere","structure":"condicere, condixi, condictum (verb, third conjugation)","meaning":"to agree upon, stipulate","meaningCN":"商定；规定"},{"word":"condicio","structure":"condicio, condicionis (f., third declension)","meaning":"agreement, stipulation, condition","meaningCN":"约定；条款；状况"},{"word":"conditio","structure":"conditio, conditionis (f., third declension, variant spelling)","meaning":"a making, a state, a condition","meaningCN":"制作；状态；状况"}]}}]);
